_ovf    or      a               ; clear carry
        sbc     hl,de           ; undo the failed subtraction
        or      a               ; is count zero?
        jr      nz,_show
        exx
        ld      a,b
        or      a
        exx
        ret     z               ; leading zero, suppress
        xor     a               ; mid-number zero
_show   exx
        ld      b,1
        exx
        add     a,'0'
        push    hl              ; putchar clobbers HL
        call    rbt_putchar
        pop     hl
        ret

; ----------------------------------------------------------------------------
; rbt_ink / rbt_paper / rbt_bright / rbt_flash - modify rbt_attr. A = value.
; ----------------------------------------------------------------------------
rbt_ink:
        and     7
        ld      b,a
        ld      a,(rbt_attr)
        and     #f8
        or      b
        ld      (rbt_attr),a
        ret

rbt_paper:
        and     7
        add     a,a
        add     a,a
        add     a,a
        ld      b,a
        ld      a,(rbt_attr)
        and     #c7
        or      b
        ld      (rbt_attr),a
        ret

rbt_bright:
        and     1
        rrca
        rrca                    ; bit0 -> bit6
        ld      b,a
        ld      a,(rbt_attr)
        and     #bf
        or      b
        ld      (rbt_attr),a
        ret

rbt_flash:
        and     1
        rrca                    ; bit0 -> bit7
        ld      b,a
        ld      a,(rbt_attr)
        and     #7f
        or      b
        ld      (rbt_attr),a
        ret

; ----------------------------------------------------------------------------
; rbt_fillattr - fill attribute rectangle.
; In: B = x, C = y, D = w, E = h. Uses current rbt_attr.
; ----------------------------------------------------------------------------
rbt_fillattr:
        ld      a,e
        or      a
        ret     z
_row    push    bc
        push    de
        ; HL = #5800 + y*32 + x
        ld      a,c
        ld      l,a
        ld      h,0
        add     hl,hl
        add     hl,hl
        add     hl,hl
        add     hl,hl
        add     hl,hl
        ld      a,b
        or      l
        ld      l,a
        ld      a,h
        add     a,#58
        ld      h,a
        ; fill D cells
        ld      a,(rbt_attr)
_fc     ld      (hl),a
        inc     hl
        dec     d
        jr      nz,_fc
        pop     de
        pop     bc
        inc     c
        dec     e
        jr      nz,_row
        ret
''',
    'core': r'''
; ============================================================================
; rbt_core_asm - Rainbow runtime core
; Entry point, stack setup, frame sync, pause, border, cls, RNG, waitkey.
; Included by generated main_asm (single concatenated assembly).
; Preserves IY for the ROM interrupt (IM1) - user ASM blocks should too.
; ============================================================================

RBT_STACK       equ #7ffe       ; stack top (bank 5 free RAM, always mapped)

rbt_start:
        di
        ld      sp,RBT_STACK
        im      1
        ei
        call    rb_main         ; user program entry (MAIN:)
rbt_end:
        call    rbt_sfx_drain
        halt
        call    rbt_hook_frame
        jr      rbt_end         ; program end: idle forever

; ----------------------------------------------------------------------------
; rbt_vsync - wait for the next frame interrupt (HALT)
; ----------------------------------------------------------------------------
rbt_vsync:
        call    rbt_sfx_drain   ; play any queued effect during the idle gap
        halt
        call    rbt_hook_frame
        ret

; ----------------------------------------------------------------------------
; rbt_pause - pause for B frames (B=0 waits for a keypress)
; ----------------------------------------------------------------------------
rbt_pause:
        call    rbt_sfx_drain
        ld      a,b
        or      a
        jr      z,rbt_waitkey
_ploop  halt
        call    rbt_hook_frame
        djnz    _ploop
        ret

; ----------------------------------------------------------------------------
; rbt_waitkey - block until any key is pressed (50Hz polling so the AY
; music hook keeps ticking while waiting)
; ----------------------------------------------------------------------------
rbt_waitkey:
        call    rbt_sfx_drain
_wk     halt
        call    rbt_hook_frame
        xor     a
        in      a,(#fe)         ; all half-rows
        cpl
        and     #1f
        jr      z,_wk
_rel    xor     a               ; wait for release
        in      a,(#fe)
        cpl
        and     #1f
        jr      nz,_rel
        ret

; ----------------------------------------------------------------------------
; rbt_border - set border to A (0-7)
; ----------------------------------------------------------------------------
rbt_border:
        and     7
        out     (#fe),a
        rlca                    ; BORDCR wants border in bits 3-5
        rlca
        rlca
        ld      (#5c48),a
        ret

; ----------------------------------------------------------------------------
; rbt_scrmode - select hardware screen mode (A = mode). The ZX has a single
; fixed 256x192 mode so this is a no-op; the CPC and C64 runtimes provide real
; implementations (CPC: GA/CRTC mode 0-2, C64: hires/multicolour bitmap).
; ----------------------------------------------------------------------------
rbt_scrmode:
        ret

; ----------------------------------------------------------------------------
; rbt_cls - clear bitmap, fill attributes with rbt_attr, home cursor
; ----------------------------------------------------------------------------
rbt_cls:
        ld      hl,#4000
        ld      de,#4001
        ld      bc,#17ff
        ld      (hl),0
        ldir
        ld      hl,#5800
        ld      de,#5801
        ld      bc,#02ff
        ld      a,(rbt_attr)
        ld      (hl),a
        ldir
        xor     a
        ld      (rbt_col),a
        ld      (rbt_row),a
        ret

; ----------------------------------------------------------------------------
; rbt_rnd8 - 8-bit Galois LFSR. Out: A = pseudo-random byte
; ----------------------------------------------------------------------------
rbt_rnd8:
        ld      a,(rbt_seed)
        add     a,a
        jr      nc,_no_xor
        xor     #1d
_no_xor ld      (rbt_seed),a
        ret

; ----------------------------------------------------------------------------
; rbt_mod8 - A = A mod B (unsigned). Clobbers C,E.
; ----------------------------------------------------------------------------
rbt_mod8:
        ld      c,a
        xor     a
        ld      e,a             ; E = quotient
        ld      a,c
_dl     cp      b
        jr      c,_done
        sub     b
        inc     e
        jr      _dl
_done   ret                     ; A = remainder

; ----------------------------------------------------------------------------
; data
; ----------------------------------------------------------------------------
rbt_seed        defw #ace1
rbt_dataptr     defw 0          ; READ pointer (set to rbd_data by compiler)
rbt_col         defb 0          ; PRINT cursor column (charset)
rbt_row         defb 0          ; PRINT cursor row (charset)
rbt_over        defb 0          ; 0 = normal, 1 = invert (OVER)
rbt_attr        defb #38        ; current attr: ink|paper<<3|bright<<6|flash<<7
                                ; (rbt_cls fills the attr plane with this;
                                ;  charset's INK/PAPER/BRIGHT/FLASH update it)
''',
    'input': r'''
; ============================================================================
; rbt_input_asm - keyboard matrix + joystick input
; Key code encoding: code = row*8 + bit.
;   row 0 (#FEFE): 0=SHIFT 1=Z 2=X 3=C 4=V
;   row 1 (#FDFE): 0=A 1=S 2=D 3=F 4=G
;   row 2 (#FBFE): 0=Q 1=W 2=E 3=R 4=T
;   row 3 (#F7FE): 0=1 1=2 2=3 3=4 4=5
;   row 4 (#EFFE): 0=0 1=9 2=8 3=7 4=6
;   row 5 (#DFFE): 0=P 1=O 2=I 3=U 4=Y
;   row 6 (#BFFE): 0=ENTER 1=L 2=K 3=J 4=H
;   row 7 (#7FFE): 0=SPACE 1=SYM 2=M 3=N 4=B
; ============================================================================

rbt_rowtbl      defb #fe,#fd,#fb,#f7,#ef,#df,#bf,#7f

; code -> ASCII map (0 = no ascii). Index = row*8+bit.
rbt_keymap:
        defb    0,'z','x','c','v',0,0,0          ; row 0
        defb    'a','s','d','f','g',0,0,0        ; row 1
        defb    'q','w','e','r','t',0,0,0        ; row 2
        defb    '1','2','3','4','5',0,0,0        ; row 3
        defb    '0','9','8','7','6',0,0,0        ; row 4
        defb    'p','o','i','u','y',0,0,0        ; row 5
        defb    13,'l','k','j','h',0,0,0         ; row 6
        defb    ' ',0,'m','n','b',0,0,0          ; row 7

; ----------------------------------------------------------------------------
; rbt_key - test one key. In: A = code (row<<3 | bit). Out: A=1 pressed, 0 not.
; ----------------------------------------------------------------------------
rbt_key:
        ld      e,a             ; E = code
        and     7
        ld      c,a             ; C = bit index
        ld      a,e
        rrca
        rrca
        rrca
        and     7               ; A = row
        ld      hl,rbt_rowtbl
        ld      d,0
        ld      e,a
        add     hl,de
        ld      a,(hl)          ; port high byte
        ld      e,c             ; E = bit index
        ld      b,a
        ld      c,#fe
        in      a,(c)           ; A = row bits (0 = pressed)
        ; shift bit E into carry
        ld      b,e
        inc     b
_sh     rra
        djnz    _sh
        ld      a,0
        ret     c               ; bit was 1 -> not pressed
        inc     a
        ret

; ----------------------------------------------------------------------------
; rbt_anykey - A = 1 if any key pressed
; ----------------------------------------------------------------------------
rbt_anykey:
        xor     a
        in      a,(#fe)
        cpl
        and     #1f
        ret     z
        ld      a,1
        ret

; ----------------------------------------------------------------------------
; rbt_inkey - scan matrix, return ASCII of first pressed key (or 0)
; ----------------------------------------------------------------------------
rbt_inkey:
        ld      b,64
        ld      c,0             ; C = code
_scan   ld      a,c
        push    bc
        call    rbt_key
        pop     bc
        or      a
        jr      nz,_found
        inc     c
        djnz    _scan
        xor     a
        ret
_found  ld      hl,rbt_keymap
        ld      d,0
        ld      e,c
        add     hl,de
        ld      a,(hl)
        ret

; ----------------------------------------------------------------------------
; rbt_joy - read joystick port.
;   rbt_joymode: 0 = none, 1 = Kempston (port 31), 2 = Sinclair1 (5678),
;                3 = Sinclair2 (1234), 4 = Cursor (890;)
; Out: A = bitmask %000FUDLR (fire,up,down,left,right)
; ----------------------------------------------------------------------------
rbt_joymode     defb 0

rbt_joy:
        ld      a,(rbt_joymode)
        or      a
        ret     z               ; A = 0: no joystick
        cp      1
        jr      z,_kempston
        ; Sinclair variants read the keyboard matrix:
        ;   SINCLAIR1 = keys 6,7,8,9,0 -> row 4 (#EFFE): 0=fire... map:
        ;   port #EFFE bits: 0='0' 1='9' 2='8' 3='7' 4='6'
        ;   sinclair1: right=6,left=7,down=8,up=9,fire=0
        ;   sinclair2: right=1? standard: SINCLAIR2 = keys 1-5 row #F7FE
        cp      3
        jr      z,_sin2
_sin1   ld      b,#ef           ; row 4: 6 7 8 9 0
        ld      c,#fe
        in      a,(c)
        ; bits: 4=right('6') 3=left('7') 2=down('8') 1=up('9') 0=fire('0')
        ; build %000FUDLR
        ld      b,a
        and     1               ; fire (bit0) -> bit4
        add     a,a
        add     a,a
        add     a,a
        add     a,a
        ld      e,a
        ld      a,b
        and     2               ; up -> bit3
        add     a,a
        add     a,a
        or      e
        ld      e,a
        ld      a,b
        and     4               ; down -> bit2
        or      e
        ld      e,a
        ld      a,b
        and     8               ; left -> bit1
        rra
        or      e
        ld      e,a
        ld      a,b
        and     16              ; right -> bit0
        rra
        rra
        rra
        rra
        or      e
        cpl
        and     #1f             ; pressed bits are 0 -> invert
        ret
_sin2   ld      b,#f7           ; row 3: 1 2 3 4 5
        ld      c,#fe
        in      a,(c)
        ; sinclair2: left='1'(bit0)... fire='5'(bit4)
        ; bits: 0=left 1=right? convention: 1=left 2=right 3=down 4=up 5=fire
        ld      b,a
        and     1               ; left -> bit1
        add     a,a
        ld      e,a
        ld      a,b
        and     2               ; right -> bit0
        rra
        or      e
        ld      e,a
        ld      a,b
        and     4               ; down -> bit2
        or      e
        ld      e,a
        ld      a,b
        and     8               ; up -> bit3
        or      e
        ld      e,a
        ld      a,b
        and     16              ; fire -> bit4
        or      e
        cpl
        and     #1f
        ret
_kempston:
        ld      bc,#001f        ; port 31
        in      a,(c)
        and     #1f             ; already %000FUDLR
        ret
''',
    'p3load': r'''
; ============================================================================
; rbt_p3load - Rainbow runtime: +3DOS bank loader (zxplus3 only)
;
; Emitted first so RANDOMIZE USR <org> lands here. Each bank file is
; loaded through +3DOS: DOS_READ takes the destination bank in C and
; pages it in at #C000 itself. +3DOS keeps its workspace in bank 7 and
; its sector cache/RAMdisc in pages 1,3,4,6 — DOS_SET_1346 confines it
; to bank 1, freeing banks 0/3/4/6 for assets.
;
; A DOS entry requires ROM 2 (the +3DOS ROM — it carries the jump block
; at #0100) at #0000, bank 7 at #C000, a stack inside #4000-#BFE0 and
; interrupts enabled. ROM number = 7FFD.bit4 | 1FFD.bit2<<1, so ROM2 is
; res 4 on the BANKM mirror once 1FFD bit2 is set (forced here via
; BANK678). Every DOS call corrupts BC DE HL IX — the table pointer
; rides the stack across each call.
;
; File table rbt_bankfiles is emitted by the compiler:
;   defb bank / defm "BANKn.BIN" / defb #FF  ... defb #FF
; ============================================================================

RBT_P3_DOS_OPEN   equ #0106
RBT_P3_DOS_CLOSE  equ #0109
RBT_P3_DOS_READ   equ #0112
RBT_P3_GET_EOF    equ #0139
RBT_P3_S1346      equ #013F
RBT_P3_SETMSG     equ #014E
RBT_P3_DD_MOT_OFF equ #019C
RBT_P3_BANKM      equ #5B5C
RBT_P3_BANK678    equ #5B67

rbt_p3load:
        di
        ld      sp,RBT_STACK    ; #7ffe: inside the #4000-#BFE0 DOS
                                ; stack window, in always-mapped bank 5
        call    rbt_p3_dosram   ; bank7 + ROM2, ei
        xor     a
        call    RBT_P3_SETMSG   ; disable ALERT dialogs — errors just
                                ; return carry clear
        ld      de,#001C        ; cache = buffers 0-27, RAMdisc = 28-31:
        ld      hl,#1C04        ; page 1 only — 0/3/4/6 free for assets
        call    RBT_P3_S1346
        jr      nc,_fail
        ld      ix,rbt_bankfiles
_next:
        ld      a,(ix)          ; bank number, #FF = end
        cp      #ff
        jr      z,_done
        ld      bc,#0005        ; B = file 0, C = shared-read
        ld      de,#0001        ; open existing + read header; error if
                                ; absent
        push    ix
        pop     hl
        inc     hl              ; -> "BANKn.BIN",#FF
        push    ix              ; DOS corrupts IX
        call    RBT_P3_DOS_OPEN
        pop     ix
        jr      nc,_fail
        ld      b,0
        push    ix
        call    RBT_P3_GET_EOF  ; E:HL = file size incl. 128-byte
        pop     ix              ; PLUS3DOS header
        jr      nc,_fail
        ld      a,e
        or      a
        jr      nz,_fail        ; >64K file — impossible for a bank
        ld      e,l
        ld      d,h             ; DE = EOF
        ld      hl,-128
        add     hl,de           ; HL = data length past the header
        ex      de,hl           ; DE = length for DOS_READ
        ld      a,d
        or      e
        jr      z,_fail         ; DE=0 would read 64K and hit EOF
        ld      b,0             ; file 0
        ld      c,(ix)          ; C = destination page at #C000
        ld      hl,#C000
        push    ix
        call    RBT_P3_DOS_READ
        pop     ix
        jr      nc,_fail
        ld      b,0
        push    ix
        call    RBT_P3_DOS_CLOSE
        pop     ix
        jr      nc,_fail
        ld      de,11           ; entry = bank + "BANKn.BIN"(9) + #FF
        add     ix,de
        jr      _next
_done:
        ld      b,0
        call    RBT_P3_DOS_CLOSE
        call    RBT_P3_DD_MOT_OFF
        call    rbt_p3_useram   ; bank0 + ROM3 (48K BASIC) for the game
        jp      rbt_start
_fail:
        call    rbt_p3_useram
        ld      a,#07           ; white border flash — the game cannot
_h:     halt                    ; run without its banks
        xor     #07
        out     (#FE),a
        jr      _h

; page RAM bank 7 (DOS workspace) at #C000 and the DOS ROM (ROM2) at
; #0000: res 4 on BANKM with 1FFD bit2 forced through BANK678
rbt_p3_dosram:
        ld      a,(RBT_P3_BANK678)
        or      #04             ; 1FFD bit2 = ROM select high bit
        ld      (RBT_P3_BANK678),a
        ld      bc,#1FFD
        out     (c),a
        ld      a,(RBT_P3_BANKM)
        res     4,a             ; ROM2
        or      #07             ; bank 7
        ld      (RBT_P3_BANKM),a
        ld      bc,#7FFD
        out     (c),a
        ei                      ; DOS wants interrupts enabled
        ret

; resting state for the game: bank 0 + ROM3 (48K BASIC) — the same
; configuration rbt_bank maintains through RBT_BANKROM
rbt_p3_useram:
        di
        ld      a,(RBT_P3_BANKM)
        and     #F8             ; bank 0
        set     4,a             ; ROM3
        ld      (RBT_P3_BANKM),a
        ld      bc,#7FFD
        out     (c),a
        ei
        ret
''',
    'pixel': r'''
; ============================================================================
; rbt_pixel_asm - pixel addressing, PLOT / POINT / LINE
; ============================================================================

rbt_bitmask     defb #80,#40,#20,#10,#08,#04,#02,#01

; ----------------------------------------------------------------------------
; rbt_pix - pixel (x=C, y=B) -> HL = screen address, A = bit mask
; ----------------------------------------------------------------------------
rbt_pix:
        ld      a,b
        and     #c0
        rra
        rra
        rra
        and     %00011000       ; y7y6 -> H bits 4,3
        ld      h,a
        ld      a,b
        and     7
        or      h
        or      #40
        ld      h,a             ; H = #40 | (y&c0)>>3 | (y&7)
        ld      a,b
        and     #38
        add     a,a
        add     a,a             ; (y&38)<<2
        ld      l,a
        ld      a,c
        rra
        rra
        rra
        and     %00011111       ; x>>3
        or      l
        ld      l,a
        ld      a,c
        and     7
        push    hl
        ld      hl,rbt_bitmask
        ld      d,0
        ld      e,a
        add     hl,de
        ld      a,(hl)
        pop     hl
        ret

; ----------------------------------------------------------------------------
; rbt_plot - plot pixel (x=C, y=B). Honours rbt_over (1 = invert).
; ----------------------------------------------------------------------------
rbt_plot:
        call    rbt_pix
        ld      b,a
        ld      a,(rbt_over)
        or      a
        ld      a,(hl)
        jr      z,_set
        xor     b
        jr      _wr
_set    or      b
_wr     ld      (hl),a
        ret

; ----------------------------------------------------------------------------
; rbt_point - test pixel (x=C, y=B). Out: A = 1 set, 0 clear
; ----------------------------------------------------------------------------
rbt_point:
        call    rbt_pix
        and     (hl)
        ret     z
        ld      a,1
        ret

; ----------------------------------------------------------------------------
; rbt_line - draw line from (C,B) to (rbt_lx,rbt_ly) - Bresenham.
; Clobbers everything. rbt_over honoured via rbt_plot.
; ----------------------------------------------------------------------------
rbt_lx          defb 0
rbt_ly          defb 0

rbt_line:
        ; compute dx = |lx - x|, sx = sign
        ld      a,(rbt_lx)
        sub     c
        jr      nc,_dxp
        neg
_dxp    ld      d,a             ; D = dx
        ld      a,(rbt_lx)
        cp      c
        ld      a,1
        jr      nc,_sx
        ld      a,-1
_sx     ld      (rbt_lsx),a
        ld      a,(rbt_ly)
        sub     b
        jr      nc,_dyp
        neg
_dyp    ld      e,a             ; E = dy
        ld      a,(rbt_ly)
        cp      b
        ld      a,1
        jr      nc,_sy
        ld      a,-1
_sy     ld      (rbt_lsy),a
        ; err = dx - dy
        ld      a,d
        sub     e
        ld      h,a             ; H = err
_loop   push    hl
        push    de
        call    rbt_plot        ; plot (C,B)
        pop     de
        pop     hl
        ; if x==lx and y==ly done
        ld      a,(rbt_lx)
        cp      c
        jr      nz,_step
        ld      a,(rbt_ly)
        cp      b
        ret     z
_step   ; e2 = 2*err
        ld      a,h
        add     a,a
        ; if e2 > -dy: err -= dy; x += sx
        ld      l,a
        ld      a,e
        neg
        cp      l               ; -dy vs e2: e2 > -dy?
        jr      nc,_skipx       ; if -dy >= e2 skip? (cp l: NC means -dy>=e2)
        ld      a,h
        sub     e
        ld      h,a             ; err -= dy
        ld      a,(rbt_lsx)
        add     a,c
        ld      c,a             ; x += sx
_skipx  ; if e2 < dx: err += dx; y += sy
        ld      a,l             ; e2
        cp      d               ; e2 < dx?
        jr      nc,_skipy
        ld      a,h
        add     a,d
        ld      h,a             ; err += dx
        ld      a,(rbt_lsy)
        add     a,b
        ld      b,a             ; y += sy
_skipy  jr      _loop

rbt_lsx         defb 0
rbt_lsy         defb 0

; ----------------------------------------------------------------------------
; rbt_showpic - HL -> 6912-byte screen (bitmap + attrs) copied to #4000.
; ----------------------------------------------------------------------------
rbt_showpic:
        ld      de,#4000
        ld      bc,6912
        ldir
        ret
''',
    'sfx': r'''
; ============================================================================
; rbt_sfx_asm - Rainbow beeper sound effects
;
; SFX queues an effect instead of playing it inline: the pending pointer is
; drained at the next idle point (rbt_vsync / rbt_pause / rbt_waitkey /
; rbt_end / rbt_sp_update entry), so the effect plays during dead frame time
; instead of stalling the game loop. If a second SFX arrives while one is
; still pending, the pending one plays immediately so ordering is preserved.
;
; rbt_sfx       - queue an effect: HL = step data, A = bank (#ff = resident)
; rbt_sfx_drain - play the pending effect now if one is queued (called by
;                 the frame-wait routines; stubbed to ret when sfx unused)
; rbt_sfx_play  - blocking player: HL = step data (di during playback)
;
; Step format (3 bytes): len, period, slide
;   len    = number of speaker toggles (1..255; 0 = end of effect)
;   period = delay between toggles (~13*T per unit, 1..255)
;   slide  = signed byte added to period each toggle (pitch bend)
; ============================================================================

rbt_sfx:
        push    hl
        push    af
        call    rbt_sfx_drain         ; flush a queued effect first (ordering)
        pop     af
        pop     hl
        ld      (rbt_sfx_pbank),a
        ld      (rbt_sfx_pending),hl
        ret

rbt_sfx_drain:
        ld      hl,(rbt_sfx_pending)
        ld      a,h
        or      l
        ret     z
        push    hl                    ; step ptr
        xor     a
        ld      (rbt_sfx_pending),a
        ld      (rbt_sfx_pending+1),a
        ld      a,(rbt_sfx_pbank)
        ld      hl,rbt_sfx_pprev
        call    rbt_pg_in             ; pages only when pbank <> #ff
        pop     hl
        call    rbt_sfx_play
        ld      hl,rbt_sfx_pprev
        jp      rbt_pg_out            ; restore bank (no-op when resident)

rbt_sfx_play:
        di
        ld      c,#10                   ; speaker output level
_step   ld      a,(hl)                  ; len
        or      a
        jr      z,_done
        inc     hl
        ld      d,(hl)                  ; period
        inc     hl
        ld      e,(hl)                  ; slide
        inc     hl
        push    hl
        ld      b,a
_toggle ld      a,c
        out     (#fe),a                 ; write speaker level
        xor     #10
        ld      c,a
        ld      a,d                     ; delay: ~13T * period
        or      a
        jr      nz,_wait
        inc     a                       ; period 0 -> 1 (avoid hang)
_wait   dec     a
        jr      nz,_wait
        ld      a,d                     ; period += slide
        add     a,e
        ld      d,a
        nop                             ; pad loop timing
        nop
        djnz    _toggle
        pop     hl
        jr      _step
_done   xor     a
        out     (#fe),a
        ei
        ret

rbt_sfx_pending defw    0               ; queued effect step ptr (0 = none)
rbt_sfx_pbank   defb    #ff             ; bank of the queued effect
rbt_sfx_pprev   defb    0               ; bank save byte for the drain guard
''',
    'spcoll': r'''
; ============================================================================
; rbt_spcoll_asm - sprite <-> tilemap collision bridge.
; Requires BOTH the sprite module (rbt_slot) and the tilemap module
; (rbt_tm_* vars, rbt_tm_mapat, rbt_ct_* scratch).
; ============================================================================

; ----------------------------------------------------------------------------
; rbt_colltile - A = sprite id -> A = flags of first solid tile overlapped
; (0 = none). Requires the sprite module (uses rbt_sprites via rbt_slot).
; ----------------------------------------------------------------------------
rbt_colltile:
        call    rbt_slot        ; IX = slot
        ld      a,(ix+0)
        bit     0,a
        ret     z               ; inactive -> no collision
        ; cell range from pixel bbox
        ld      a,(ix+1)
        and     #f8
        rrca
        rrca
        rrca
        ld      (rbt_ct_c0),a   ; x>>3
        ld      a,(ix+3)
        add     a,a
        add     a,a
        add     a,a             ; w*8
        dec     a
        add     a,(ix+1)        ; x+w*8-1
        and     #f8
        rrca
        rrca
        rrca
        ld      (rbt_ct_c1),a
        ld      a,(ix+2)
        and     #f8
        rrca
        rrca
        rrca
        ld      (rbt_ct_r0),a   ; y>>3
        ld      a,(ix+4)
        dec     a
        add     a,(ix+2)        ; y+h-1
        and     #f8
        rrca
        rrca
        rrca
        ld      (rbt_ct_r1),a
        ; loop rows r0..r1
        ld      a,(rbt_ct_r0)
        ld      (rbt_ct_r),a
_cr     ld      a,(rbt_ct_c0)
        ld      (rbt_ct_c),a
_cc     ; inside view?
        ld      a,(rbt_tm_vx)
        ld      b,a
        ld      a,(rbt_ct_c)
        cp      b
        jp      c,_cskip
        ld      a,(rbt_tm_vw)
        add     a,b
        ld      b,a
        ld      a,(rbt_ct_c)
        cp      b
        jp      nc,_cskip
        ld      a,(rbt_tm_vy)
        ld      b,a
        ld      a,(rbt_ct_r)
        cp      b
        jp      c,_cskip
        ld      a,(rbt_tm_vh)
        add     a,b
        ld      b,a
        ld      a,(rbt_ct_r)
        cp      b
        jp      nc,_cskip
        ; map coords
        ld      a,(rbt_ct_c)
        ld      b,a
        ld      a,(rbt_tm_vx)
        ld      c,a
        ld      a,b
        sub     c
        ld      b,a
        ld      a,(rbt_tm_camx)
        add     a,b
        ld      b,a             ; mx
        ld      a,(rbt_ct_r)
        ld      c,a
        ld      a,(rbt_tm_vy)
        ld      d,a
        ld      a,c
        sub     d
        ld      c,a
        ld      a,(rbt_tm_camy)
        add     a,c
        ld      c,a             ; my
        ; in map? (else treat as not solid)
        ld      a,(rbt_tm_mw)
        cp      b
        jp      c,_cskip
        jp      z,_cskip
        ld      a,(rbt_tm_mh)
        cp      c
        jp      c,_cskip
        jp      z,_cskip
        call    rbt_tm_mapat
        call    rbt_tileflags   ; A = flags (self-pages tileset bank)
        bit     0,a
        ret     nz              ; solid -> return flags
_cskip  ld      a,(rbt_ct_c)
        inc     a
        ld      (rbt_ct_c),a
        ld      b,a
        ld      a,(rbt_ct_c1)
        cp      b
        jp      nc,_cc
        ld      a,(rbt_ct_r)
        inc     a
        ld      (rbt_ct_r),a
        ld      b,a
        ld      a,(rbt_ct_r1)
        cp      b
        jp      nc,_cr
        xor     a               ; none
        ret
''',
    'sprite': r'''
; ============================================================================
; rbt_sprite_asm - masked sprite engine
; 16 slots x 14 bytes. Draws 1bpp sprites (any byte width, any pixel height)
; with per-byte masks at arbitrary pixel-x (on-the-fly right shift).
; Modes: 0 = mask (screen&mask)|bmp, 1 = or, 2 = xor.
; Erasing is the game's job (TILEMAP REDRAW / CLS) - AGD-style explicit model.
; 128K: slot +14 holds the asset's bank (#FF resident); every asset
; dereference is wrapped in rbt_pg_in/out so banked sprites just work.
; ============================================================================

RBT_NSLOTS      equ 16
RBT_SLOT        equ 15          ; bytes per slot
; slot offsets:
;  +0  flags: bit0 active, bit1 hidden
;  +1  x (pixels) +2  y (pixels)
;  +3  w (bytes) +4  h (pixels)
;  +5  frame +6,7 asset ptr
;  +8  attr +9  mode
;  +10 animFirst +11 animLast
;  +12 animFlags: bit0 pingpong, bit1 animating
;  +13 animDir (1 / -1)
;  +14 asset bank (#ff = resident)

rbt_sprites     defs RBT_NSLOTS*RBT_SLOT

; ----------------------------------------------------------------------------
; rbt_slot - A = sprite id -> IX = slot address. Preserves BC,DE,HL.
; ----------------------------------------------------------------------------
rbt_slot:
        and     RBT_NSLOTS-1
        push    de
        ld      e,a
        add     a,a
        add     a,a
        add     a,a
        add     a,a             ; id*16
        sub     e               ; id*15
        ld      e,a
        ld      d,0
        ld      ix,rbt_sprites
        add     ix,de
        pop     de
        ret

; ----------------------------------------------------------------------------
; rbt_sp_create - A=id, HL=asset, B=mode(0/1/2), C=x, D=y, E=asset bank
; asset: defb wb,h,nframes,attr, frame data...
; ----------------------------------------------------------------------------
rbt_sp_create:
        push    hl
        call    rbt_slot        ; preserves DE (E = bank)
        pop     hl
        ld      a,e
        ld      (ix+14),a       ; asset bank (#ff resident)
        ld      (ix+6),l
        ld      (ix+7),h        ; asset ptr
        ld      (ix+0),1        ; active
        ld      (ix+1),c        ; x
        ld      (ix+2),d        ; y
        ld      a,(hl)
        ld      (ix+3),a        ; w bytes
        inc     hl
        ld      a,(hl)
        ld      (ix+4),a        ; h
        inc     hl
        inc     hl              ; skip nframes
        ld      a,(hl)
        ld      (ix+8),a        ; attr
        xor     a
        ld      (ix+5),a        ; frame 0
        ld      (ix+9),b        ; mode
        ld      (ix+12),a       ; anim off
        ret

; ----------------------------------------------------------------------------
; rbt_sp_move - A=id, B=dx (signed), C=dy (signed). Clamps to screen.
; ----------------------------------------------------------------------------
rbt_sp_move:
        call    rbt_slot
        ; x += B with clamp to [0, 256 - w*8]
        ld      e,(ix+1)        ; old x
        ld      a,e
        add     a,b
        bit     7,b
        jr      nz,_mvxn
        ; positive dx: clamp to maxX
        jr      c,_mvxmax       ; wrapped past 255
        ld      d,a             ; D = new x
        ld      a,(ix+3)
        add     a,a
        add     a,a
        add     a,a             ; w*8
        neg                     ; 256 - w*8 = maxX
        cp      d
        jr      c,_mvxset       ; new > maxX -> store maxX (A)
        ld      a,d
        jr      _mvxset
_mvxmax ld      a,(ix+3)
        add     a,a
        add     a,a
        add     a,a
        neg
        jr      _mvxset
_mvxn   ; negative dx: underflow (new > old) -> 0
        cp      e
        jr      c,_mvxset       ; new < old: normal move, A = new x
        xor     a
_mvxset ld      (ix+1),a
_mvy    ; y += C with clamp to [0, 192 - h]
        ld      e,(ix+2)
        ld      a,e
        add     a,c
        bit     7,c
        jr      nz,_mvyn
        jr      c,_mvymax
        ld      d,a             ; D = new y
        ld      a,(ix+4)
        neg                     ; 256 - h
        add     a,192-256       ; = 192 - h
        cp      d
        jr      c,_mvyset
        ld      a,d
        jr      _mvyset
_mvymax ld      a,(ix+4)
        neg
        add     a,192-256
        jr      _mvyset
_mvyn   cp      e
        jr      c,_mvyset
        xor     a
_mvyset ld      (ix+2),a
        ret

; ----------------------------------------------------------------------------
; rbt_sp_place - A=id, B=x, C=y
; ----------------------------------------------------------------------------
rbt_sp_place:
        call    rbt_slot
        ld      (ix+1),b
        ld      (ix+2),c
        ret

; ----------------------------------------------------------------------------
; rbt_sp_frame - A=id, B=frame (clamped to nframes-1)
; ----------------------------------------------------------------------------
rbt_sp_frame:
        call    rbt_slot
        ld      a,(ix+14)       ; asset bank
        ld      hl,rbt_sp_prev
        call    rbt_pg_in
        ld      l,(ix+6)
        ld      h,(ix+7)
        inc     hl
        inc     hl
        ld      a,(hl)          ; nframes
        dec     a
        cp      b
        jr      nc,_ok
        ld      b,a
_ok     ld      (ix+5),b
        ld      hl,rbt_sp_prev
        jp      rbt_pg_out

; ----------------------------------------------------------------------------
; rbt_sp_anim - A=id, B=first frame, C=last frame, D=0 loop / 1 pingpong
; ----------------------------------------------------------------------------
rbt_sp_anim:
        call    rbt_slot
        ld      (ix+10),b
        ld      (ix+11),c
        ld      (ix+5),b        ; frame = first
        ld      a,d
        and     1
        or      2               ; bit1 = animating
        ld      (ix+12),a
        ld      (ix+13),1
        ret

; ----------------------------------------------------------------------------
; rbt_sp_show / rbt_sp_hide / rbt_sp_kill - A=id
; ----------------------------------------------------------------------------
rbt_sp_show:
        call    rbt_slot
        ld      (ix+0),1
        ret
rbt_sp_hide:
        call    rbt_slot
        ld      a,(ix+0)
        or      2
        ld      (ix+0),a
        ret
rbt_sp_kill:
        call    rbt_slot
        ld      (ix+0),0
        ret

; ----------------------------------------------------------------------------
; rbt_sp_attr - A=id, B=attr byte
; ----------------------------------------------------------------------------
rbt_sp_attr:
        call    rbt_slot
        ld      (ix+8),b
        ret

; ----------------------------------------------------------------------------
; rbt_spx / rbt_spy - A=id -> A = x / y
; ----------------------------------------------------------------------------
rbt_spx:
        call    rbt_slot
        ld      a,(ix+1)
        ret
rbt_spy:
        call    rbt_slot
        ld      a,(ix+2)
        ret

; ----------------------------------------------------------------------------
; rbt_paddr - A = pixel y -> HL = bitmap address of line start (col 0).
; Preserves BC,DE. Clips nothing: caller must range-check y.
; ----------------------------------------------------------------------------
rbt_paddr:
        ld      l,a
        and     #c0
        rrca
        rrca
        rrca                    ; third * 8
        ld      h,a
        ld      a,l
        and     7
        or      h
        add     a,#40
        ld      h,a             ; H = #40 + third*8 + line
        ld      a,l
        and     #38
        add     a,a
        add     a,a             ; row * 32
        ld      l,a
        ret

; ----------------------------------------------------------------------------
; rbt_sp_draw - A = id: draw slot now (if active and not hidden).
; ----------------------------------------------------------------------------
rbt_sp_draw:
        call    rbt_slot
        ; fall through to draw at IX
rbt_sp_drawix:
        ld      a,(ix+0)
        bit     0,a
        ret     z               ; inactive
        bit     1,a
        ret     nz              ; hidden
        ld      a,(ix+14)       ; page the sprite asset's bank
        ld      hl,rbt_sp_prev
        call    rbt_pg_in
        ; ---- compute frame data pointers ----
        ld      l,(ix+6)
        ld      h,(ix+7)        ; HL = asset
        ld      a,(hl)
        ld      (rbt_sp_w),a    ; w bytes
        inc     hl
        ld      a,(hl)
        ld      (rbt_sp_h),a    ; h
        inc     hl
        ld      a,(hl)          ; nframes -> frame data skips the
        inc     hl              ; nframes*8 u16 offset table (F*16 bytes)
        inc     hl
        add     a,a
        add     a,a
        add     a,a
        add     a,a             ; A = F*16
        call    rbt_sp_idx      ; HL += A -> frame data start
        ; frame size = 2*w*h; off = frame * size
        ld      a,(rbt_sp_w)
        ld      e,a
        ld      a,(rbt_sp_h)
        ld      d,a
        call    rbt_sp_mul         ; DE = w*h (E*w? -> see _mul_de: DE=result)
        ld      a,(ix+5)        ; frame
        or      a
        jr      z,_f0
        ld      b,a
_fmul   add     hl,de
        add     hl,de           ; += 2*w*h
        djnz    _fmul
_f0     ld      (rbt_sp_mptr),hl
        add     hl,de           ; bmp ptr = mptr + w*h
        ld      (rbt_sp_bptr),hl
        ; ---- shift / column counts ----
        ld      a,(ix+1)
        and     7
        ld      (rbt_sp_shift),a
        ld      a,(ix+1)
        and     #f8
        rrca
        rrca
        rrca
        ld      (rbt_sp_col0),a ; x>>3
        ld      a,(rbt_sp_w)
        ld      b,a
        ld      a,(rbt_sp_shift)
        or      a
        jr      z,_nc
        inc     b
_nc     ld      a,b
        ld      (rbt_sp_ncols),a
        ; ---- row loop ----
        xor     a
        ld      (rbt_sp_row),a
_rloop  ld      a,(rbt_sp_row)
        ld      b,a
        ld      a,(rbt_sp_h)
        cp      b
        jp      z,_attrs        ; all rows done
        ; sy = y + row, skip if > 191
        ld      a,(ix+2)
        add     a,b
        jp      c,_nextrow      ; wrapped: off screen bottom
        cp      192
        jp      nc,_nextrow
        call    rbt_paddr       ; HL = line base for this pixel row
        ld      (rbt_sp_line),hl
        ; src pointers for this row
        ld      hl,(rbt_sp_mptr)
        ld      (rbt_sp_srcm),hl
        ld      hl,(rbt_sp_bptr)
        ld      (rbt_sp_srcb),hl
        ; ---- column loop ----
        xor     a
        ld      (rbt_sp_k),a
_kloop  ld      a,(rbt_sp_k)
        ld      b,a
        ld      a,(rbt_sp_ncols)
        cp      b
        jp      z,_nextrow
        ; ---- shifted mask byte ----
        ; cur byte into E first (H must survive for the prev byte)
        ld      a,(rbt_sp_k)
        ld      b,a
        ld      a,(rbt_sp_w)
        cp      b
        jr      z,_kcurmx       ; k == w: virtual cur = #ff
        ld      hl,(rbt_sp_srcm)
        ld      a,b
        call    rbt_sp_idx
        ld      e,(hl)
        jr      _kpm
_kcurmx ld      e,#ff
_kpm    ld      a,(rbt_sp_k)
        or      a
        jr      nz,_kprev
        ld      h,#ff           ; virtual prev mask = opaque screen-keep
        jr      _kprevd
_kprev  dec     a
        ld      hl,(rbt_sp_srcm)
        call    rbt_sp_idx
        ld      h,(hl)
_kprevd ld      l,e
_kshm   ld      a,(rbt_sp_shift)
        or      a
        jr      z,_kmdone       ; shift 0: L = cur already correct? no!
        ; when shift==0 we only iterate k<w and want cur -> handled below
        ld      b,a
_kshl   srl     h
        rr      l
        djnz    _kshl
_kmdone ld      a,l
        ld      (rbt_sp_mout),a ; mask out byte (shift 0 path below fixes)
        ld      a,(rbt_sp_shift)
        or      a
        jr      nz,_kbmp
        ; shift==0: mask out = cur byte (L already), ok as-is
_kbmp   ; ---- shifted bitmap byte ----
        ld      a,(rbt_sp_k)
        ld      b,a
        ld      a,(rbt_sp_w)
        cp      b
        jr      z,_kbcx         ; k == w: virtual cur = 0
        ld      hl,(rbt_sp_srcb)
        ld      a,b
        call    rbt_sp_idx
        ld      e,(hl)
        jr      _kpb
_kbcx   ld      e,0
_kpb    ld      a,(rbt_sp_k)
        or      a
        jr      nz,_kbprev
        ld      h,0
        jr      _kprevb
_kbprev dec     a
        ld      hl,(rbt_sp_srcb)
        call    rbt_sp_idx
        ld      h,(hl)
_kprevb ld      l,e
_kshb   ld      a,(rbt_sp_shift)
        or      a
        jr      z,_kbdone
        ld      b,a
_kshbl  srl     h
        rr      l
        djnz    _kshbl
_kbdone ld      b,l             ; B = bitmap out byte
        ld      a,(rbt_sp_mout)
        ld      c,a             ; C = mask out byte
        ; ---- screen write ----
        ld      a,(rbt_sp_col0)
        ld      hl,rbt_sp_k
        add     a,(hl)          ; screen column
        cp      32
        jr      nc,_kskip
        ld      e,a
        ld      hl,(rbt_sp_line)
        ld      a,l
        add     a,e
        ld      l,a             ; HL = screen byte addr
        ld      a,(ix+9)        ; mode
        cp      1
        jr      z,_mor
        cp      2
        jr      z,_mxor
        ; mask mode: (scr & mout) | bout
        ld      a,(hl)
        and     c
        or      b
        ld      (hl),a
        jr      _kskip
_mor    ld      a,(hl)
        or      b
        ld      (hl),a
        jr      _kskip
_mxor   ld      a,(hl)
        xor     b
        ld      (hl),a
_kskip  ld      a,(rbt_sp_k)
        inc     a
        ld      (rbt_sp_k),a
        jp      _kloop
_nextrow:
        ; advance src pointers by w
        ld      a,(rbt_sp_w)
        ld      e,a
        ld      d,0
        ld      hl,(rbt_sp_mptr)
        add     hl,de
        ld      (rbt_sp_mptr),hl
        ld      hl,(rbt_sp_bptr)
        add     hl,de
        ld      (rbt_sp_bptr),hl
        ld      a,(rbt_sp_row)
        inc     a
        ld      (rbt_sp_row),a
        jp      _rloop
        ; ---- attribute fill ----
_attrs  ; attr cells: rows (y>>3)..((y+h-1)>>3), cols (x>>3)..(x>>3)+ncols-1
        ld      a,(ix+8)
        cp      #ff
        jr      z,_dexit        ; attr $FF = don't touch attributes (no clash)
        ld      a,(ix+2)
        and     #f8
        rrca
        rrca
        rrca
        ld      (rbt_sp_ar0),a  ; first attr row
        ld      a,(ix+2)
        ld      b,a
        ld      a,(ix+4)
        dec     a
        add     a,b             ; y+h-1
        jr      c,_ar1max
        and     #f8
        rrca
        rrca
        rrca
        jr      _ar1
_ar1max ld      a,23
_ar1    ld      (rbt_sp_ar1),a
        ld      a,(rbt_sp_ar0)
        ld      (rbt_sp_ar),a   ; current attr row
_arow   ld      a,(rbt_sp_ar)
        cp      24
        jr      nc,_done
        ld      b,a
        ld      a,(rbt_sp_ar1)
        cp      b
        jr      c,_done         ; past last
        ; col loop: c = col0 .. col0+ncols-1, clip <32
        ld      a,(rbt_sp_col0)
        ld      (rbt_sp_ac),a
_acol   ld      a,(rbt_sp_ac)
        cp      32
        jr      nc,_arnext
        ld      b,a
        ld      a,(rbt_sp_col0)
        ld      c,a
        ld      a,(rbt_sp_ncols)
        dec     a
        add     a,c             ; last col
        cp      b
        jr      c,_arnext
        ; addr = #5800 + arow*32 + acol
        ld      a,(rbt_sp_ar)
        ld      l,a
        ld      h,0
        add     hl,hl
        add     hl,hl
        add     hl,hl
        add     hl,hl
        add     hl,hl
        ld      a,(rbt_sp_ac)
        or      l
        ld      l,a
        ld      a,h
        add     a,#58
        ld      h,a
        ld      a,(ix+8)
        ld      (hl),a
        ld      a,(rbt_sp_ac)
        inc     a
        ld      (rbt_sp_ac),a
        jr      _acol
_arnext ld      a,(rbt_sp_ar)
        inc     a
        ld      (rbt_sp_ar),a
        jr      _arow
_done
_dexit  ld      hl,rbt_sp_prev
        jp      rbt_pg_out      ; restore bank, return to caller

; helpers ---------------------------------------------------------------------
rbt_sp_idx                      ; HL += A (k index)
        add     a,l
        ld      l,a
        ret     nc
        inc     h
        ret
rbt_sp_mul                      ; D=h, E=w -> DE = w*h (w*h <= 31*192 fits 16b)
        push    bc
        push    hl
        ld      hl,0
        ld      b,e             ; w
        ld      a,b
        or      a
        jr      z,_zero
        ld      a,d             ; h
        ld      d,0
        ld      e,a             ; DE = h (addend)
_mdl    add     hl,de
        djnz    _mdl
        ex      de,hl           ; DE = result
        jr      _out
_zero   ld      de,0
_out    pop     hl
        pop     bc
        ret

; ----------------------------------------------------------------------------
; rbt_sp_drawall - draw every drawable slot, then advance animations.
; ----------------------------------------------------------------------------
rbt_sp_drawall:
        ld      b,RBT_NSLOTS
        ld      ix,rbt_sprites
_dal    push    bc
        ld      a,(ix+0)
        bit     0,a
        jr      z,_dan          ; inactive
        bit     1,a
        jr      nz,_dan         ; hidden
        call    rbt_sp_drawix
_dan    ld      de,RBT_SLOT
        add     ix,de
        pop     bc
        djnz    _dal
        ; ---- advance animations ----
        ld      b,RBT_NSLOTS
        ld      ix,rbt_sprites
_daa    push    bc
        ld      a,(ix+0)
        bit     0,a
        jr      z,_danx
        ld      a,(ix+12)
        bit     1,a
        jr      z,_danx         ; not animating
        ld      a,(ix+5)
        add     a,(ix+13)       ; frame += dir
        bit     0,(ix+12)
        jr      nz,_ping
        ; loop mode: wrap first..last
        ld      b,a
        ld      a,(ix+11)       ; last
        cp      b
        jr      nc,_setf
        ld      b,(ix+10)       ; wrap to first
        jr      _setf
_ping   ; pingpong: bounce at bounds
        ld      b,a
        ld      a,(ix+11)
        cp      b
        jr      nc,_plo
        ; past last: reverse, frame = last-1
        ld      a,(ix+13)
        neg
        ld      (ix+13),a
        ld      a,(ix+11)
        dec     a
        ld      b,a
        jr      _setf
_plo    ld      a,(ix+10)
        cp      b
        jr      c,_setf         ; frame >= first ok
        jr      nz,_phi         ; frame < first -> below first
        ; frame == first ok
        jr      _setf
_phi    ; frame < first: reverse, frame = first+1
        ld      a,(ix+13)
        neg
        ld      (ix+13),a
        ld      a,(ix+10)
        inc     a
        ld      b,a
_setf   ld      (ix+5),b
_danx   ld      de,RBT_SLOT
        add     ix,de
        pop     bc
        djnz    _daa
        ret

; ----------------------------------------------------------------------------
; rbt_spcoll - A=id1, B=id2 -> A = 1 if bounding boxes overlap.
; ----------------------------------------------------------------------------
rbt_spcoll:
        push    bc
        call    rbt_slot        ; IX = slot a
        pop     bc
        ld      a,(ix+0)
        bit     0,a
        jr      z,_no
        push    iy
        ; IY = slot b
        ld      a,b
        and     RBT_NSLOTS-1
        ld      e,a
        add     a,a
        add     a,a
        add     a,a
        add     a,a
        sub     e               ; id*15
        ld      e,a
        ld      d,0
        ld      iy,rbt_sprites
        add     iy,de
        ld      a,(iy+0)
        bit     0,a
        jr      z,_noy
        ; x1 < x2 + w2*8 ?
        ld      a,(iy+3)
        add     a,a
        add     a,a
        add     a,a
        add     a,(iy+1)        ; x2 + w2*8
        ld      b,a
        ld      a,(ix+1)
        cp      b
        jr      nc,_noy
        ; x2 < x1 + w1*8 ?
        ld      a,(ix+3)
        add     a,a
        add     a,a
        add     a,a
        add     a,(ix+1)
        ld      b,a
        ld      a,(iy+1)
        cp      b
        jr      nc,_noy
        ; y1 < y2 + h2 ?
        ld      a,(iy+4)
        add     a,(iy+2)
        ld      b,a
        ld      a,(ix+2)
        cp      b
        jr      nc,_noy
        ; y2 < y1 + h1 ?
        ld      a,(ix+4)
        add     a,(ix+2)
        ld      b,a
        ld      a,(iy+2)
        cp      b
        jr      nc,_noy
        pop     iy
        ld      a,1
        ret
_noy    pop     iy
_no     xor     a
        ret

; ----------------------------------------------------------------------------
; SP1-style composited sprite update.
;
; Each slot tracks the cell rect it was last composited into (rbt_sp_old, valid
; when flags bit2 set). rbt_sp_update:
;   1. marks dirty every cell in old-rect (drawn sprites) + new-rect (visible
;      sprites), then updates rbt_sp_old
;   2. recomposites each dirty cell in RAM: background (bound tilemap tile, else
;      blank) + every covering sprite slice, then writes the 8 bitmap bytes and
;      the attr byte to the screen in ONE burst. The screen never contains a
;      "sprite erased" intermediate state, so there is nothing to flicker.
; Do NOT mix with SPRITES DRAWALL/SPRITE REDRAW on the same slots.
; ----------------------------------------------------------------------------

rbt_sp_old      defs RBT_NSLOTS*4     ; per slot: col0,row0,col1,row1
rbt_sp_dirty    defs 96               ; 32x24 cell dirty bitmap
rbt_sp_cmplo    defs 96               ; covering-sprite mask per cell, sids 0-7
rbt_sp_cmphi    defs 96               ; same, sids 8-15
rbt_uc_buf      defs 8                ; composited cell bytes
rbt_uc_cx       defb 0
rbt_uc_cy       defb 0
rbt_uc_row      defb 0
rbt_uc_sid      defb 0
rbt_uc_bga      defb 0                ; pending attr (#ff = leave screen attr)
rbt_uc_w        defb 0
rbt_uc_h        defb 0
rbt_uc_shf      defb 0
rbt_uc_c0       defb 0
rbt_uc_c1       defb 0
rbt_uc_lr       defb 0
rbt_uc_t        defb 0
rbt_uc_mr       defb 0
rbt_uc_mc       defb 0
rbt_uc_bit      defb 0                ; pass-2 dirty-bit index (cellcomp clobbers sid)
rbt_uc_db       defb 0                ; pass-2 dirty byte (cellcomp clobbers t)
rbt_uc_nr       defs 4                ; pass-1: new sprite cell rect col0,row0,col1,row1
rbt_uc_off      defw 0                ; cellcomp: lr*w + i source offset
rbt_uc_of       defb 0                ; cellcomp: rbt_uc_off initialised flag
rbt_uc_ci       defb 0                ; cellcomp: cx - col0 (constant per cell)
rbt_uc_cm       defb 0                ; cellcomp: cmap candidate mask byte
rbt_uc_cb       defb 0                ; cellcomp: cmap candidate bit index
rbt_uc_rh       defb 0                ; cellcomp: last covered row (rowhi)
rbt_uc_ow2      defb 0                ; cellcomp: pre-shifted row stride (wb+1)*2
rbt_uc_n        defb 0                ; cellcomp: rows left to composite
rbt_uc_bp       defw 0                ; cellcomp: buf write pointer
rbt_uc_mptr     defw 0
rbt_uc_bptr     defw 0

; rbt_sp_srect - IX=slot -> sprite cell rect into rbt_uc_c0/c1-style regs:
; B=col0 C=row0 D=col1 E=row1, A=1 if on screen else A=0.
rbt_sp_srect:
        ld      l,(ix+6)
        ld      h,(ix+7)
        ld      a,(hl)
        ld      (rbt_uc_w),a        ; w bytes
        inc     hl
        ld      a,(hl)
        ld      (rbt_uc_h),a        ; h px
        ; col0 = x>>3
        ld      a,(ix+1)
        and     #f8
        rrca
        rrca
        rrca
        ld      b,a
        cp      32
        jr      nc,_srno            ; fully off right
        ; ncols = w + (x&7 ? 1 : 0); col1 = col0+ncols-1
        ld      a,(ix+1)
        and     7
        ld      c,a
        ld      a,(rbt_uc_w)
        dec     a
        inc     c
        dec     c
        jr      z,_sra              ; shift 0: ncols=w
        inc     a
_sra    add     a,b
        ld      d,a                 ; col1 (may exceed 31)
        ; row0 = y>>3
        ld      a,(ix+2)
        and     #f8
        rrca
        rrca
        rrca
        ld      c,a
        cp      24
        jr      nc,_srno
        ; row1 = (y+h-1)>>3, saturate 255
        ld      a,(rbt_uc_h)
        dec     a
        add     a,(ix+2)
        jr      nc,_srb
        ld      a,#ff
_srb    and     #f8
        rrca
        rrca
        rrca
        ld      e,a                 ; row1
        ; clip col1<=31, row1<=23
        ld      a,d
        cp      32
        jr      c,_src
        ld      d,31
_src    ld      a,e
        cp      24
        jr      c,_srd
        ld      e,23
_srd    ld      a,1
        ret
_srno   xor     a
        ret

; rbt_sp_markrect - set dirty bits for B=col0,C=row0,D=col1,E=row1 (inclusive,
; already clipped). Preserves DE.
rbt_sp_markrect:
        inc     d
        inc     e                   ; -> exclusive ends
        ld      a,b
        ld      (rbt_uc_mc),a       ; col0 stash (B is the djnz counter)
        ld      a,c
        ld      (rbt_uc_mr),a
_mr1    ld      a,(rbt_uc_mr)
        cp      e
        ret     nc                  ; past last row -> done
        add     a,a
        add     a,a                 ; row*4 = dirty byte base
        ld      c,a
        ld      a,(rbt_uc_mc)
        rrca
        rrca
        rrca
        and     #1f                 ; col0>>3
        add     a,c
        ld      hl,rbt_sp_dirty
        call    rbt_sp_idx          ; HL = first dirty byte of this row span
        ; C = start bit 1<<(col0&7), walks left; carry out -> next byte
        ld      a,(rbt_uc_mc)
        and     7
        ld      c,a
        ld      a,1
        inc     c
_mrm    dec     c
        jr      z,_mrd
        add     a,a
        jr      _mrm
_mrd    ld      c,a
        ld      a,(rbt_uc_mc)
        ld      b,a
        ld      a,d
        sub     b
        ld      b,a                 ; B = col count -> djnz
_mrcl   ld      a,(hl)
        or      c
        ld      (hl),a
        ld      a,c
        add     a,a
        jr      nc,_mrsb
        inc     hl                  ; bit wrapped -> next dirty byte
        ld      a,1
_mrsb   ld      c,a
        djnz    _mrcl
_mrnext ld      a,(rbt_uc_mr)
        inc     a
        ld      (rbt_uc_mr),a
        jr      _mr1

; ----------------------------------------------------------------------------
; rbt_sp_markcov - OR the current slot's bit into the covering-sprite map for
; every cell of rbt_uc_nr (the sprite's new rect). Lets cellcomp iterate only
; the sprites that actually cover a dirty cell. Preserves nothing.
; ----------------------------------------------------------------------------
rbt_sp_markcov:
        ; sid bit -> rbt_uc_t ; plane base -> rbt_uc_mptr
        ld      a,(rbt_uc_sid)
        and     7
        ld      b,a
        ld      a,1
        inc     b
_cvm    dec     b
        jr      z,_cvmd
        add     a,a
        jr      _cvm
_cvmd   ld      (rbt_uc_t),a
        ld      a,(rbt_uc_sid)
        and     8
        ld      hl,rbt_sp_cmplo
        jr      z,_cvp
        ld      hl,rbt_sp_cmphi
_cvp    ld      (rbt_uc_mptr),hl
        ; for r = row0..row1, c = col0..col1: plane[cell byte] |= sid bit
        ld      a,(rbt_uc_nr+1)
        ld      (rbt_uc_mr),a         ; r = row0
_cvr1   ld      a,(rbt_uc_mr)
        ld      b,a
        ld      a,(rbt_uc_nr+3)
        cp      b
        ret     c                     ; r > row1 -> done
        ld      a,(rbt_uc_mr)
        add     a,a
        add     a,a                   ; row*4
        ld      c,a
        ld      a,(rbt_uc_nr)
        rrca
        rrca
        rrca
        and     #1f                   ; col0>>3
        add     a,c
        ld      hl,(rbt_uc_mptr)
        call    rbt_sp_idx            ; HL = plane + row*4 + col0>>3
        ; byte walk: every covered cell ORs the same sid bit; advance the
        ; cell byte only when the column crosses a byte boundary
        ld      a,(rbt_uc_nr)
        and     7
        ld      c,a                   ; C = col0&7 (bit position)
        ld      a,(rbt_uc_nr+2)
        ld      b,a
        ld      a,(rbt_uc_nr)
        ld      d,a
        ld      a,b
        sub     d
        inc     a
        ld      b,a                   ; B = col count -> djnz
_cvc    ld      a,(rbt_uc_t)
        or      (hl)
        ld      (hl),a
        inc     c
        ld      a,c
        cp      8
        jr      nz,_cvs
        inc     hl                    ; col wrapped -> next cell byte
        xor     a
        ld      c,a
_cvs    djnz    _cvc
_cvn    ld      a,(rbt_uc_mr)
        inc     a
        ld      (rbt_uc_mr),a
        jr      _cvr1

; rbt_sp_update - recompose all dirty cells (see header comment).
rbt_sp_update:
        call    rbt_sfx_drain         ; drain queued SFX at the frame boundary
        ; ---- clear dirty map + covering-sprite maps (contiguous) ----
        ld      hl,rbt_sp_dirty
        ld      de,rbt_sp_dirty+1
        ld      bc,96*3-1
        ld      (hl),0
        ldir
        ; ---- pass 1: dirty old + new rects, refresh bookkeeping ----
        xor     a
        ld      (rbt_uc_sid),a
_udp1   ld      a,(rbt_uc_sid)
        call    rbt_slot            ; IX = slot
        ; old rect (if drawn)
        ; visible? -> rbt_uc_nr = new cell rect; else no new rect
        ld      a,(ix+0)
        bit     0,a
        jp      z,_unov             ; inactive
        bit     1,a
        jp      nz,_unov            ; hidden
        call    rbt_sp_srect        ; B,C,D,E = rect, or A=0 offscreen
        or      a
        jp      z,_unov
        ld      hl,rbt_uc_nr
        ld      (hl),b
        inc     hl
        ld      (hl),c
        inc     hl
        ld      (hl),d
        inc     hl
        ld      (hl),e
        bit     2,(ix+0)
        jr      z,_unonly           ; not drawn before -> mark new rect only
        ; union(old, new) -> B,C,D,E; one markrect covers both old and new
        ld      a,(rbt_uc_sid)
        add     a,a
        add     a,a
        ld      hl,rbt_sp_old
        call    rbt_sp_idx          ; HL = old + sid*4
        ld      a,(rbt_uc_nr)
        ld      b,a
        ld      a,(hl)
        cp      b
        jr      nc,_uu0             ; old >= new -> keep new (min col0)
        ld      b,a
_uu0    ld      a,(rbt_uc_nr+1)
        ld      c,a
        inc     hl
        ld      a,(hl)
        cp      c
        jr      nc,_uu1             ; min row0
        ld      c,a
_uu1    inc     hl
        ld      a,(rbt_uc_nr+2)
        ld      d,a
        ld      a,(hl)
        cp      d
        jr      c,_uu2              ; old < new -> keep new (max col1)
        ld      d,a
_uu2    inc     hl
        ld      a,(rbt_uc_nr+3)
        ld      e,a
        ld      a,(hl)
        cp      e
        jr      c,_uu3              ; max row1
        ld      e,a
_uu3    call    rbt_sp_markrect     ; mark the union once
        ; store new rect to rbt_sp_old for next frame / cellcomp reject
        ld      a,(rbt_uc_sid)
        add     a,a
        add     a,a
        ld      hl,rbt_sp_old
        call    rbt_sp_idx
        ld      a,(rbt_uc_nr)
        ld      (hl),a
        inc     hl
        ld      a,(rbt_uc_nr+1)
        ld      (hl),a
        inc     hl
        ld      a,(rbt_uc_nr+2)
        ld      (hl),a
        inc     hl
        ld      a,(rbt_uc_nr+3)
        ld      (hl),a
        call    rbt_sp_markcov      ; record covering sid for pass 2
        jr      _unx
_unonly ; first draw: mark new rect only, store it, set drawn
        ld      a,(rbt_uc_sid)
        add     a,a
        add     a,a
        ld      hl,rbt_sp_old
        call    rbt_sp_idx
        ld      a,(rbt_uc_nr)
        ld      b,a
        ld      (hl),a
        inc     hl
        ld      a,(rbt_uc_nr+1)
        ld      c,a
        ld      (hl),a
        inc     hl
        ld      a,(rbt_uc_nr+2)
        ld      d,a
        ld      (hl),a
        inc     hl
        ld      a,(rbt_uc_nr+3)
        ld      e,a
        ld      (hl),a
        set     2,(ix+0)
        call    rbt_sp_markrect
        call    rbt_sp_markcov
        jr      _unx
_unov   ; no new rect: erase old if drawn
        bit     2,(ix+0)
        jr      z,_unx
        ld      a,(rbt_uc_sid)
        add     a,a
        add     a,a
        ld      hl,rbt_sp_old
        call    rbt_sp_idx
        ld      b,(hl)
        inc     hl
        ld      c,(hl)
        inc     hl
        ld      d,(hl)
        inc     hl
        ld      e,(hl)
        call    rbt_sp_markrect
        res     2,(ix+0)
_unx    ld      a,(rbt_uc_sid)
        inc     a
        cp      RBT_NSLOTS
        jr      c,_unxok
        jr      _upd2
_unxok  ld      (rbt_uc_sid),a
        jp      _udp1
        ; ---- pass 2: recompose dirty cells ----
        ; byte-wise scan: dirty byte i covers cy=i>>2, cols (i&3)*8+bit
_upd2   xor     a
        ld      (rbt_uc_mr),a         ; byte index i
_usc    ld      a,(rbt_uc_mr)
        cp      96
        ret     nc                    ; scanned whole map -> done
        ld      e,a
        ld      d,0
        ld      hl,rbt_sp_dirty
        add     hl,de
        ld      a,(hl)
        or      a
        jr      z,_usnx               ; clean byte
        ; cy = i>>2 ; cxbase = (i&3)<<3 ; bit counter reuses uc_sid
        ld      a,(rbt_uc_mr)
        rrca
        rrca
        and     #3f
        ld      (rbt_uc_cy),a
        ld      a,(rbt_uc_mr)
        and     3
        add     a,a
        add     a,a
        add     a,a
        ld      (rbt_uc_mc),a         ; col base for this byte
        ld      a,(hl)
        ld      (rbt_uc_db),a         ; stash byte
        xor     a
        ld      (rbt_uc_bit),a        ; bit index 0..7
_usb    ld      a,(rbt_uc_db)
        and     1
        jr      z,_usbn
        ld      a,(rbt_uc_mc)
        ld      b,a
        ld      a,(rbt_uc_bit)
        add     a,b
        ld      (rbt_uc_cx),a         ; cx = base + bit
        call    rbt_sp_cellcomp
_usbn   ld      a,(rbt_uc_db)
        rra
        ld      (rbt_uc_db),a
        ld      a,(rbt_uc_bit)
        inc     a
        cp      8
        jr      nc,_usnx
        ld      (rbt_uc_bit),a
        jr      _usb
_usnx   ld      a,(rbt_uc_mr)
        inc     a
        ld      (rbt_uc_mr),a
        jr      _usc

; rbt_sp_cellcomp - recompose cell (rbt_uc_cx, rbt_uc_cy) and write once.
rbt_sp_cellcomp:
        ; ---- background bytes + attr ----
        ld      a,#ff
        ld      (rbt_uc_bga),a
        ld      hl,(rbt_tm_map)
        ld      a,h
        or      l
        jr      z,_bg0
        ; mx = cx - vx + camx ; my = cy - vy + camy
        ld      a,(rbt_tm_vx)
        ld      b,a
        ld      a,(rbt_uc_cx)
        sub     b
        ld      b,a
        ld      a,(rbt_tm_camx)
        add     a,b
        ld      b,a                 ; B = mx (mapat bounds-checks)
        ld      a,(rbt_tm_vy)
        ld      c,a
        ld      a,(rbt_uc_cy)
        sub     c
        ld      c,a
        ld      a,(rbt_tm_camy)
        add     a,c
        ld      c,a                 ; C = my
        call    rbt_tm_mapat        ; A = tile id (0 when out of map)
        ld      e,a
        ld      a,(rbt_tm_tbank)    ; page tileset bank for tattr/bmp reads
        ld      hl,rbt_tm_tprev
        call    rbt_pg_in
        ld      d,0
        ld      hl,(rbt_tm_tattr)
        add     hl,de
        ld      a,(hl)
        ld      (rbt_uc_bga),a      ; tile attr
        sla     e
        rl      d
        sla     e
        rl      d
        sla     e
        rl      d
        ld      hl,(rbt_tm_bmp)
        add     hl,de               ; src = bmp + tid*8
        ld      de,rbt_uc_buf
        ld      bc,8
        ldir
        ld      hl,rbt_tm_tprev
        call    rbt_pg_out
        jr      _bgs
_bg0    ld      hl,rbt_uc_buf
        ld      b,8
        xor     a
_bg0l   ld      (hl),a
        inc     hl
        djnz    _bg0l
_bgs    ; ---- composite every covering sprite in slot order ----
        ; candidates come from the covering-sprite map: cmplo bit per sid 0-7,
        ; cmphi for 8-15, both indexed like the dirty map. Iterating the set
        ; bits skips the ~16-slot scan; the old-rect check below still rejects
        ; candidates that cover a neighbouring cell of the same byte.
        ld      a,(rbt_uc_cy)
        add     a,a
        add     a,a                 ; cy*4
        ld      b,a
        ld      a,(rbt_uc_cx)
        rrca
        rrca
        rrca
        and     #1f
        add     a,b
        ld      (rbt_uc_lr),a       ; cmap byte index for this cell
        ld      hl,rbt_sp_cmplo
        call    rbt_sp_idx
        ld      a,(hl)
        ld      (rbt_uc_cm),a       ; candidate mask byte
        xor     a
        ld      (rbt_uc_cb),a       ; bit index 0..7
        ld      (rbt_uc_nr),a       ; phase: 0 = sids 0-7, 8 = sids 8-15
        ; scan: shift cm right through carry; cb counts bits consumed. The
        ; loop exits the moment cm drains, so sparse maps cost little.
_cs     ld      a,(rbt_uc_cm)
        or      a
        jp      z,_csph             ; plane drained -> next plane / commit
        srl     a                   ; bit0 -> carry (inc/ld below keep it)
        ld      (rbt_uc_cm),a
        ld      a,(rbt_uc_cb)
        inc     a
        ld      (rbt_uc_cb),a
        jp      nc,_cs              ; bit was clear -> next
        ld      a,(rbt_uc_cb)
        dec     a
        ld      b,a
        ld      a,(rbt_uc_nr)
        add     a,b
        ld      (rbt_uc_sid),a      ; sid = phase + bit index
        call    rbt_slot            ; IX = slot
        ; cheap reject vs the slot's current cell rect (stored in pass 1):
        ; rbt_sp_old + sid*4 = col0,row0,col1,row1
        ld      a,(rbt_uc_sid)
        add     a,a
        add     a,a
        ld      e,a
        ld      d,0
        ld      hl,rbt_sp_old
        add     hl,de
        ld      b,(hl)              ; col0
        inc     hl
        ld      c,(hl)              ; row0
        inc     hl
        ld      a,(hl)              ; col1
        inc     hl
        ld      h,(hl)              ; row1
        ld      l,a                 ; L=col1 H=row1
        ld      a,(rbt_uc_cx)
        cp      b
        jp      c,_cs               ; cx < col0
        ld      a,(rbt_uc_cy)
        cp      c
        jp      c,_cs               ; cy < row0
        inc     l
        ld      a,(rbt_uc_cx)
        cp      l
        jp      nc,_cs              ; cx > col1
        inc     h
        ld      a,(rbt_uc_cy)
        cp      h
        jp      nc,_cs              ; cy > row1
        ld      a,(ix+14)           ; page the sprite asset's bank
        ld      hl,rbt_sp_prev
        call    rbt_pg_in
        ; load dims; keep the asset base in mptr for the offset-table lookup
        ld      l,(ix+6)
        ld      h,(ix+7)
        ld      (rbt_uc_mptr),hl
        ld      a,(hl)
        ld      (rbt_uc_w),a
        inc     hl
        ld      a,(hl)
        ld      (rbt_uc_h),a
        inc     hl
        ld      a,(hl)              ; nframes
        ld      (rbt_uc_t),a        ; stash for the fidx loop below
        ; col coverage: col0 = x>>3 ; col1 = col0 + ncols - 1
        ld      a,(ix+1)
        and     #f8
        rrca
        rrca
        rrca
        ld      (rbt_uc_c0),a
        ld      a,(ix+1)
        and     7
        ld      (rbt_uc_shf),a
        ; col1 = col0 + ncols - 1 ; ncols = w + (shf ? 1 : 0)
        ld      a,(rbt_uc_w)
        dec     a
        ld      b,a
        ld      a,(rbt_uc_shf)
        or      a
        jr      z,_cnc2
        inc     b
_cnc2   ld      a,(rbt_uc_c0)
        add     a,b
        ld      (rbt_uc_c1),a
        ; ow2 = (wb+1)*2 : row stride of the pre-shifted blocks
        ld      a,(rbt_uc_w)
        inc     a
        add     a,a
        ld      (rbt_uc_ow2),a
        ; ---- find the pre-shifted block for (phase, frame) ----
        ; fidx = shf*nframes + frame ; block = asset + u16 offs[fidx]
        ld      a,(rbt_uc_t)
        ld      c,a                 ; C = nframes
        ld      a,(rbt_uc_shf)
        ld      b,a
        ld      a,(ix+5)            ; frame
        inc     b
_cfml   dec     b
        jr      z,_cf0
        add     a,c                 ; += nframes
        jr      _cfml
_cf0    add     a,a                 ; fidx*2 (table entries are u16)
        ld      hl,(rbt_uc_mptr)
        inc     hl
        inc     hl
        inc     hl
        inc     hl                  ; HL = asset+4 = offset table
        call    rbt_sp_idx          ; HL += A -> &offs[fidx]
        ld      e,(hl)
        inc     hl
        ld      d,(hl)              ; DE = block offset
        ld      hl,(rbt_uc_mptr)
        add     hl,de
        ld      (rbt_uc_mptr),hl    ; mptr = block base
        ; ---- per-row slice composite into buf ----
        ; i = cx - col0 (constant for this cell). Coverage is already proved,
        ; so iterate only the covered rows: rowlo = max(0, sy-cy*8),
        ; rowhi = min(7, sy+h-1-cy*8).
        ld      a,(rbt_uc_cx)
        ld      b,a
        ld      a,(rbt_uc_c0)
        ld      c,a
        ld      a,b
        sub     c
        ld      (rbt_uc_ci),a
        ld      a,(rbt_uc_cy)
        add     a,a
        add     a,a
        add     a,a                 ; A = cy*8
        ld      c,a
        ld      a,(ix+2)            ; sy
        sub     c                   ; sy - cy*8
        jr      c,_rlz
        jr      _rlv
_rlz    xor     a
_rlv    ld      (rbt_uc_row),a      ; rowlo: first covered CELL row
        ; srow = rowlo - (sy-cy*8) = first covered SPRITE row: 0 when the
        ; sprite starts in this cell, cy*8-sy when it started above it.
        ; C must stay cy*8 for the rowhi computation below.
        ld      b,a
        ld      a,(ix+2)            ; sy
        neg
        add     a,c                 ; cy*8 - sy (8-bit wrap handles both cases)
        add     a,b
        ld      (rbt_uc_off),a      ; srow for mp
        ld      a,(rbt_uc_h)
        dec     a
        add     a,(ix+2)            ; sy+h-1 (carry if >255 -> covers whole cell)
        jr      c,_rh7
        sub     c                   ; sy+h-1-cy*8 (>= rowlo: coverage proved)
        cp      8
        jr      c,_rhc
_rh7    ld      a,7
_rhc    ld      (rbt_uc_rh),a
        ; mp = block + srow*ow2 + i*2 ; bp = buf+rowlo ; n = rowhi-rowlo+1
        ld      a,(rbt_uc_off)
        ld      d,a
        ld      a,(rbt_uc_ow2)
        ld      e,a
        call    rbt_sp_mul          ; DE = rowlo*ow2
        ld      a,(rbt_uc_ci)
        add     a,a
        add     a,e
        ld      e,a
        jr      nc,_mof
        inc     d
_mof    ld      hl,(rbt_uc_mptr)
        add     hl,de
        ld      (rbt_uc_mptr),hl    ; mp = &(m_i,b_i) of rowlo
        ld      hl,rbt_uc_buf
        ld      a,(rbt_uc_row)
        call    rbt_sp_idx
        ld      (rbt_uc_bp),hl      ; buf write ptr
        ld      a,(rbt_uc_rh)
        ld      b,a
        ld      a,(rbt_uc_row)
        ld      c,a
        ld      a,b
        sub     c
        inc     a
        ld      (rbt_uc_n),a        ; n = rows to composite
_crl    ld      a,(rbt_uc_n)
        or      a
        jp      z,_cattr
        dec     a
        ld      (rbt_uc_n),a
        ld      hl,(rbt_uc_mptr)
        ld      c,(hl)              ; pre-shifted mask for this cell col
        inc     hl
        ld      b,(hl)              ; pre-shifted bitmap
        dec     hl
        ld      a,(rbt_uc_ow2)
        add     a,l
        ld      l,a
        jr      nc,_mpa
        inc     h
_mpa    ld      (rbt_uc_mptr),hl    ; mp += ow2 (next row)
        ; apply mode to buf[row] via the write pointer
        ld      hl,(rbt_uc_bp)
        ld      a,(ix+9)            ; mode
        cp      1
        jr      z,_cmor
        cp      2
        jr      z,_cmxr
        ld      a,(hl)              ; mask: (buf & m) | b
        and     c
        or      b
        ld      (hl),a
        jr      _crn
_cmor   ld      a,(hl)
        or      b
        ld      (hl),a
        jr      _crn
_cmxr   ld      a,(hl)
        xor     b
        ld      (hl),a
_crn    inc     hl
        ld      (rbt_uc_bp),hl      ; bp++
        jp      _crl
_cattr  ; sprite attr overrides pending attr unless #ff
        ld      a,(ix+8)
        cp      #ff
        jr      z,_csout
        ld      (rbt_uc_bga),a
_csout  ld      hl,rbt_sp_prev
        call    rbt_pg_out          ; restore bank after this sprite
        jp      _cs
_csph   ld      a,(rbt_uc_nr)       ; plane phase
        or      a
        jr      nz,_cwr             ; hi plane done -> commit cell
        ld      a,(rbt_uc_lr)
        ld      hl,rbt_sp_cmphi
        call    rbt_sp_idx
        ld      a,(hl)
        ld      (rbt_uc_cm),a
        xor     a
        ld      (rbt_uc_cb),a
        ld      a,8
        ld      (rbt_uc_nr),a       ; phase -> sids 8-15
        jp      _cs
        ; ---- commit cell: 8 bitmap bytes + attr in one burst ----
_cwr    ld      a,(rbt_uc_cy)
        ld      b,a
        and     #f8
        add     a,#40
        ld      h,a                 ; H = #40 + (cy&F8) + r
        ld      a,b
        and     7
        add     a,a
        add     a,a
        add     a,a
        add     a,a
        add     a,a                 ; (cy&7)*32
        ld      b,a
        ld      a,(rbt_uc_cx)
        add     a,b
        ld      l,a                 ; L = (cy&7)*32 + cx
        ld      de,rbt_uc_buf
        ld      b,8
_cwl    ld      a,(de)
        ld      (hl),a
        inc     de
        inc     h
        djnz    _cwl
        ; attr: skip if #ff
        ld      a,(rbt_uc_bga)
        cp      #ff
        ret     z
        ld      a,(rbt_uc_cy)
        ld      l,a
        ld      h,0
        add     hl,hl
        add     hl,hl
        add     hl,hl
        add     hl,hl
        add     hl,hl
        ld      a,(rbt_uc_cx)
        or      l
        ld      l,a
        ld      a,h
        add     a,#58
        ld      h,a
        ld      a,(rbt_uc_bga)
        ld      (hl),a
        ret

rbt_sp_prev     defb 0          ; pg guard save (asset bank)
rbt_sp_w        defb 0
rbt_sp_h        defb 0
rbt_sp_shift    defb 0
rbt_sp_col0     defb 0
rbt_sp_ncols    defb 0
rbt_sp_row      defb 0
rbt_sp_k        defb 0
rbt_sp_mout     defb 0
rbt_sp_ar0      defb 0
rbt_sp_ar1      defb 0
rbt_sp_ar       defb 0
rbt_sp_ac       defb 0
rbt_sp_line     defw 0
rbt_sp_mptr     defw 0
rbt_sp_bptr     defw 0
rbt_sp_srcm     defw 0
rbt_sp_srcb     defw 0
''',
    'tilemap': r'''
; ============================================================================
; rbt_tilemap_asm - tile / tilemap engine (tile-step scrolling)
;
; Tileset layout: defb n, n*8 bitmaps, n attrs, n flag bytes (bit0 = solid)
; Tilemap layout: defb w, h, w*h tile indices (row-major)
;
; View: screen window in char cells (vx,vy,vw,vh); camera in map tile coords.
; Scrolling = camera move + full view redraw.
; ============================================================================

; State vars and rbt_tm_mapat live in rbt_tmdata.asm (shared with the sprite
; compositor).

; ----------------------------------------------------------------------------
; rbt_tm_settiles - HL = tileset data
; ----------------------------------------------------------------------------
rbt_tm_settiles:
        ld      (rbt_tm_tiles),hl
        ld      a,(hl)
        ld      (rbt_tm_n),a
        inc     hl
        ld      (rbt_tm_bmp),hl
        ; attr base = bmp + n*8
        ld      e,a
        ld      d,0
        sla     e
        rl      d
        sla     e
        rl      d
        sla     e
        rl      d               ; DE = n*8
        add     hl,de
        ld      (rbt_tm_tattr),hl
        ; flag base = attr + n
        ld      a,(rbt_tm_n)
        ld      e,a
        ld      d,0
        add     hl,de
        ld      (rbt_tm_tflags),hl
        ret

; ----------------------------------------------------------------------------
; rbt_tm_setmap - HL = tilemap data
; ----------------------------------------------------------------------------
rbt_tm_setmap:
        ld      (rbt_tm_map),hl
        ld      a,(hl)
        ld      (rbt_tm_mw),a
        inc     hl
        ld      a,(hl)
        ld      (rbt_tm_mh),a
        inc     hl
        ld      (rbt_tm_cells),hl
        ; clamp the camera into the new map's bounds (it may be smaller
        ; than the previous map while scrolled)
        ld      a,(rbt_tm_mw)
        ld      c,a
        ld      a,(rbt_tm_vw)
        ld      b,a
        ld      a,c
        sub     b
        jr      nc,_cmx
        xor     a
_cmx    ld      b,a             ; B = max(0, mw - vw)
        ld      a,(rbt_tm_camx)
        cp      b
        jr      c,_cy
        ld      a,b
        ld      (rbt_tm_camx),a
_cy     ld      a,(rbt_tm_mh)
        ld      c,a
        ld      a,(rbt_tm_vh)
        ld      b,a
        ld      a,c
        sub     b
        jr      nc,_cmy
        xor     a
_cmy    ld      c,a             ; C = max(0, mh - vh)
        ld      a,(rbt_tm_camy)
        cp      c
        jr      c,_cdone
        ld      a,c
        ld      (rbt_tm_camy),a
_cdone  ret

; ----------------------------------------------------------------------------
; rbt_tm_view - B=x, C=y, D=w, E=h (screen cells, clamped to 32x24)
; ----------------------------------------------------------------------------
rbt_tm_view:
        ld      a,b
        and     31
        ld      (rbt_tm_vx),a
        ld      a,c
        cp      24
        jr      c,_vy
        ld      a,23
_vy     ld      (rbt_tm_vy),a
        ld      a,d
        or      a
        jr      nz,_vw
        inc     a
_vw     cp      33
        jr      c,_vw2
        ld      a,32
_vw2    ld      (rbt_tm_vw),a
        ld      a,e
        or      a
        jr      nz,_vh
        inc     a
_vh     cp      25
        jr      c,_vh2
        ld      a,24
_vh2    ld      (rbt_tm_vh),a
        ret

; ----------------------------------------------------------------------------
; rbt_tm_camera - B=tx, C=ty (map coords, clamped so view fits in map)
; ----------------------------------------------------------------------------
rbt_tm_camera:
        ; camx = min(b, max(0, mw - vw))
        ld      a,(rbt_tm_mw)
        ld      e,a
        ld      a,(rbt_tm_vw)
        ld      d,a
        ld      a,e
        sub     d
        jr      nc,_cx          ; A = mw - vw (max camera)
        xor     a
_cx     cp      b
        jr      nc,_cxs         ; max >= b -> keep b
        ld      b,a             ; clamp to max
_cxs    ld      a,b
        ld      (rbt_tm_camx),a
        ; camy = min(c, max(0, mh - vh))
        ld      a,(rbt_tm_mh)
        ld      e,a
        ld      a,(rbt_tm_vh)
        ld      d,a
        ld      a,e
        sub     d
        jr      nc,_cy
        xor     a
_cy     cp      c
        jr      nc,_cys
        ld      c,a
_cys    ld      a,c
        ld      (rbt_tm_camy),a
        ret

; ----------------------------------------------------------------------------
; rbt_tm_blit - draw tile A at screen cell B=x, C=y. Clobbers everything.
; ----------------------------------------------------------------------------
rbt_tm_blit:
        ld      hl,rbt_tm_tprev
        push    af
        ld      a,(rbt_tm_tbank)
        call    rbt_pg_in       ; page tileset bank (no-op when resident)
        pop     af
        call    _blb
        ld      hl,rbt_tm_tprev
        jp      rbt_pg_out

_blb    ld      (rbt_tm_tid),a
        push    bc
        ; src = bmp + id*8
        ld      e,a
        ld      d,0
        sla     e
        rl      d
        sla     e
        rl      d
        sla     e
        rl      d               ; DE = id*8
        ld      hl,(rbt_tm_bmp)
        add     hl,de
        ex      de,hl           ; DE = src
        ; dst = cell addr: H = #40+(cy>>3)*8, L = (cy&7)*32+cx
        ld      a,c
        and     #f8
        rrca
        rrca
        rrca
        add     a,a
        add     a,a
        add     a,a
        add     a,#40
        ld      h,a
        ld      a,c
        and     7
        rrca
        rrca
        rrca
        or      b
        ld      l,a
        ld      b,8
_tbl    ld      a,(de)
        ld      (hl),a
        inc     de
        inc     h
        djnz    _tbl
        ; attr = #5800 + cy*32 + cx
        ld      a,c
        ld      l,a
        ld      h,0
        add     hl,hl
        add     hl,hl
        add     hl,hl
        add     hl,hl
        add     hl,hl           ; cy*32
        pop     bc
        ld      a,b
        or      l
        ld      l,a
        ld      a,h
        add     a,#58
        ld      h,a
        ld      a,(rbt_tm_tid)
        ld      e,a
        ld      d,0
        push    hl
        ld      hl,(rbt_tm_tattr)
        add     hl,de
        ld      a,(hl)
        pop     hl
        ld      (hl),a
        ret

; ----------------------------------------------------------------------------
; rbt_tm_draw - draw the whole view window
; ----------------------------------------------------------------------------
rbt_tm_draw:
        xor     a
        ld      (rbt_tm_r),a
_dr     ld      a,(rbt_tm_vh)
        ld      b,a
        ld      a,(rbt_tm_r)
        cp      b
        ret     nc
        xor     a
        ld      (rbt_tm_c),a
_dc     ld      a,(rbt_tm_vw)
        ld      b,a
        ld      a,(rbt_tm_c)
        cp      b
        jp      nc,_dnext
        ; map coords
        ld      a,(rbt_tm_camx)
        ld      b,a
        ld      a,(rbt_tm_c)
        add     a,b
        ld      b,a             ; mx = camx + c
        ld      a,(rbt_tm_camy)
        ld      c,a
        ld      a,(rbt_tm_r)
        add     a,c
        ld      c,a             ; my = camy + r
        call    rbt_tm_mapat          ; A = tile id
        push    af
        ; screen cell = (vx+c, vy+r)
        ld      a,(rbt_tm_vx)
        ld      b,a
        ld      a,(rbt_tm_c)
        add     a,b
        ld      b,a
        ld      a,(rbt_tm_vy)
        ld      c,a
        ld      a,(rbt_tm_r)
        add     a,c
        ld      c,a
        pop     af
        call    rbt_tm_blit
        ld      a,(rbt_tm_c)
        inc     a
        ld      (rbt_tm_c),a
        jp      _dc
_dnext  ld      a,(rbt_tm_r)
        inc     a
        ld      (rbt_tm_r),a
        jp      _dr

; ----------------------------------------------------------------------------
; rbt_tm_redraw - B=x, C=y, D=w, E=h: repair a screen-cell region from the map
; ----------------------------------------------------------------------------
rbt_tm_redraw:
        ld      a,e
        ld      (rbt_ct_r1),a   ; rows remaining
        ld      a,d
        ld      (rbt_tm_dir),a  ; spare var: original col count
        ld      a,c
        ld      (rbt_ct_r),a    ; current row
        ld      a,b
        ld      (rbt_ct_c0),a   ; start col
_rr     ld      a,(rbt_ct_r1)
        or      a
        ret     z
        ld      a,(rbt_tm_dir)
        ld      (rbt_ct_c1),a   ; cols remaining this row
        ld      a,(rbt_ct_c0)
        ld      (rbt_ct_c),a
_rc     ld      a,(rbt_ct_c1)
        or      a
        jp      z,_rnext
        ; inside view? c in [vx,vx+vw), r in [vy,vy+vh)
        ld      a,(rbt_tm_vx)
        ld      b,a
        ld      a,(rbt_ct_c)
        cp      b
        jp      c,_rskip
        ld      a,(rbt_tm_vw)
        add     a,b
        ld      b,a
        ld      a,(rbt_ct_c)
        cp      b
        jp      nc,_rskip
        ld      a,(rbt_tm_vy)
        ld      b,a
        ld      a,(rbt_ct_r)
        cp      b
        jp      c,_rskip
        ld      a,(rbt_tm_vh)
        add     a,b
        ld      b,a
        ld      a,(rbt_ct_r)
        cp      b
        jp      nc,_rskip
        ; map coords = cell - view origin + camera
        ld      a,(rbt_ct_c)
        ld      b,a
        ld      a,(rbt_tm_vx)
        ld      c,a
        ld      a,b
        sub     c
        ld      b,a
        ld      a,(rbt_tm_camx)
        add     a,b
        ld      b,a             ; mx
        ld      a,(rbt_ct_r)
        ld      c,a
        ld      a,(rbt_tm_vy)
        ld      d,a
        ld      a,c
        sub     d
        ld      c,a
        ld      a,(rbt_tm_camy)
        add     a,c
        ld      c,a             ; my
        call    rbt_tm_mapat
        push    af
        ld      a,(rbt_ct_c)
        ld      b,a
        ld      a,(rbt_ct_r)
        ld      c,a
        pop     af
        call    rbt_tm_blit
_rskip  ld      a,(rbt_ct_c1)
        dec     a
        ld      (rbt_ct_c1),a
        ld      a,(rbt_ct_c)
        inc     a
        ld      (rbt_ct_c),a
        jp      _rc
_rnext  ld      a,(rbt_ct_r1)
        dec     a
        ld      (rbt_ct_r1),a
        ld      a,(rbt_ct_r)
        inc     a
        ld      (rbt_ct_r),a
        jp      _rr

; ----------------------------------------------------------------------------
; rbt_tm_laddr - B = byte col, C = pixel line -> HL = bitmap address. Uses A,HL.
; ----------------------------------------------------------------------------
rbt_tm_laddr:
        ld      a,c
        and     #c0
        rrca
        rrca
        rrca
        add     a,#40
        ld      h,a
        ld      a,c
        and     7
        or      h
        ld      h,a             ; H = #40 + (y&#C0)>>3 + (y&7)
        ld      a,c
        and     #38
        add     a,a
        add     a,a
        or      b
        ld      l,a             ; L = ((y&#38)<<2) | x
        ret

; ----------------------------------------------------------------------------
; rbt_tm_arow - B = col, C = attr row -> HL = #5800 + row*32 + col. Uses A,HL.
; ----------------------------------------------------------------------------
rbt_tm_arow:
        ld      l,c
        ld      h,0
        add     hl,hl
        add     hl,hl
        add     hl,hl
        add     hl,hl
        add     hl,hl
        ld      a,b
        or      l
        ld      l,a
        ld      a,h
        add     a,#58
        ld      h,a
        ret

; ----------------------------------------------------------------------------
; rbt_tm_shl / rbt_tm_shr - shift the view's bitmap+attr bytes left/right by
; one cell (8 pixels). Does not draw anything.
; ----------------------------------------------------------------------------
rbt_tm_shl:                     ; content moves left (camera right)
        ld      a,(rbt_tm_vw)
        dec     a
        ret     z               ; 1-cell view: nothing to shift
        ld      (rbt_tm_cnt),a
        ld      a,(rbt_tm_vy)
        add     a,a
        add     a,a
        add     a,a
        ld      (rbt_ct_r),a    ; current pixel line
        ld      b,a
        ld      a,(rbt_tm_vh)
        add     a,a
        add     a,a
        add     a,a
        add     a,b
        ld      (rbt_ct_r1),a   ; end line
_shll   ld      a,(rbt_ct_r)
        ld      b,a
        ld      a,(rbt_ct_r1)
        cp      b
        jp      z,_shla
        ld      a,(rbt_tm_vx)
        ld      b,a
        ld      a,(rbt_ct_r)
        ld      c,a
        call    rbt_tm_laddr
        ex      de,hl           ; DE = dst (vx, line)
        inc     b
        call    rbt_tm_laddr    ; HL = src (vx+1, line)
        ld      a,(rbt_tm_cnt)
        ld      c,a
        ld      b,0
        ldir
        ld      a,(rbt_ct_r)
        inc     a
        ld      (rbt_ct_r),a
        jp      _shll
_shla   ; attr rows
        ld      a,(rbt_tm_vy)
        ld      (rbt_ct_r),a
        ld      a,(rbt_tm_vh)
        ld      b,a
        ld      a,(rbt_ct_r)
        add     a,b
        ld      (rbt_ct_r1),a
_shlal  ld      a,(rbt_ct_r)
        ld      b,a
        ld      a,(rbt_ct_r1)
        cp      b
        ret     z
        ld      a,(rbt_tm_vx)
        ld      b,a
        ld      a,(rbt_ct_r)
        ld      c,a
        call    rbt_tm_arow     ; HL = dst
        push    hl
        pop     de              ; DE = dst
        inc     hl              ; HL = src (vx+1)
        ld      a,(rbt_tm_cnt)
        ld      c,a
        ld      b,0
        ldir
        ld      a,(rbt_ct_r)
        inc     a
        ld      (rbt_ct_r),a
        jp      _shlal

rbt_tm_shr:                     ; content moves right (camera left)
        ld      a,(rbt_tm_vw)
        dec     a
        ret     z
        ld      (rbt_tm_cnt),a
        ld      a,(rbt_tm_vy)
        add     a,a
        add     a,a
        add     a,a
        ld      (rbt_ct_r),a
        ld      b,a
        ld      a,(rbt_tm_vh)
        add     a,a
        add     a,a
        add     a,a
        add     a,b
        ld      (rbt_ct_r1),a
_shrl   ld      a,(rbt_ct_r)
        ld      b,a
        ld      a,(rbt_ct_r1)
        cp      b
        jp      z,_shra
        ld      a,(rbt_tm_vx)
        ld      b,a
        ld      a,(rbt_tm_vw)
        add     a,b
        dec     a
        ld      b,a             ; B = vx+vw-1 (rightmost col)
        ld      a,(rbt_ct_r)
        ld      c,a
        call    rbt_tm_laddr
        ex      de,hl           ; DE = dst (rightmost)
        dec     b
        call    rbt_tm_laddr    ; HL = src (rightmost-1)
        ld      a,(rbt_tm_cnt)
        ld      c,a
        ld      b,0
        lddr
        ld      a,(rbt_ct_r)
        inc     a
        ld      (rbt_ct_r),a
        jp      _shrl
_shra   ld      a,(rbt_tm_vy)
        ld      (rbt_ct_r),a
        ld      a,(rbt_tm_vh)
        ld      b,a
        ld      a,(rbt_ct_r)
        add     a,b
        ld      (rbt_ct_r1),a
_shral  ld      a,(rbt_ct_r)
        ld      b,a
        ld      a,(rbt_ct_r1)
        cp      b
        ret     z
        ld      a,(rbt_tm_vx)
        ld      b,a
        ld      a,(rbt_tm_vw)
        add     a,b
        dec     a
        ld      b,a
        ld      a,(rbt_ct_r)
        ld      c,a
        call    rbt_tm_arow     ; HL = dst (rightmost)
        push    hl
        pop     de              ; DE = dst
        dec     hl              ; HL = src (rightmost-1)
        ld      a,(rbt_tm_cnt)
        ld      c,a
        ld      b,0
        lddr
        ld      a,(rbt_ct_r)
        inc     a
        ld      (rbt_ct_r),a
        jp      _shral

; ----------------------------------------------------------------------------
; rbt_tm_shu / rbt_tm_shd - shift the view's bitmap+attr bytes up/down by
; one cell (8 lines).
; ----------------------------------------------------------------------------
rbt_tm_shd:                     ; content moves up (camera down)
        ld      a,(rbt_tm_vh)
        dec     a
        ret     z
        xor     a
        ld      (rbt_ct_r),a    ; d = 0 .. vh*8-9
_shdl   ld      a,(rbt_tm_vh)
        add     a,a
        add     a,a
        add     a,a
        sub     8
        ld      b,a             ; vh*8 - 8
        ld      a,(rbt_ct_r)
        cp      b
        jp      nc,_shda
        ld      a,(rbt_tm_vy)
        add     a,a
        add     a,a
        add     a,a
        ld      b,a             ; vy*8
        ld      a,(rbt_ct_r)
        add     a,b
        ld      c,a             ; dst line = vy*8 + d
        ld      a,(rbt_tm_vx)
        ld      b,a
        call    rbt_tm_laddr
        ex      de,hl           ; DE = dst
        ld      a,c
        add     a,8
        ld      c,a             ; src line = dst+8
        call    rbt_tm_laddr    ; HL = src
        ld      a,(rbt_tm_vw)
        ld      c,a
        ld      b,0
        ldir
        ld      a,(rbt_ct_r)
        inc     a
        ld      (rbt_ct_r),a
        jp      _shdl
_shda   ; attr rows: dst row r <- src row r+1, r = vy .. vy+vh-2
        ld      a,(rbt_tm_vy)
        ld      (rbt_ct_r),a
_shdal  ld      a,(rbt_tm_vh)
        dec     a
        ld      b,a
        ld      a,(rbt_tm_vy)
        add     a,b
        ld      b,a             ; vy+vh-1 (exclusive end)
        ld      a,(rbt_ct_r)
        cp      b
        ret     nc
        ld      a,(rbt_tm_vx)
        ld      b,a
        ld      a,(rbt_ct_r)
        ld      c,a
        call    rbt_tm_arow
        ex      de,hl           ; DE = dst row r
        ld      a,(rbt_ct_r)
        inc     a
        ld      c,a
        call    rbt_tm_arow     ; HL = src row r+1
        ld      a,(rbt_tm_vw)
        ld      c,a
        ld      b,0
        ldir
        ld      a,(rbt_ct_r)
        inc     a
        ld      (rbt_ct_r),a
        jp      _shdal

rbt_tm_shu:                     ; content moves down (camera up)
        ld      a,(rbt_tm_vh)
        dec     a
        ret     z
        ld      a,(rbt_tm_vh)
        add     a,a
        add     a,a
        add     a,a
        dec     a
        ld      (rbt_ct_r),a    ; d = vh*8-1 .. 8
_shul   ld      a,(rbt_ct_r)
        cp      8
        jp      c,_shua
        ld      a,(rbt_tm_vy)
        add     a,a
        add     a,a
        add     a,a
        ld      b,a
        ld      a,(rbt_ct_r)
        add     a,b
        ld      c,a             ; dst line = vy*8 + d
        ld      a,(rbt_tm_vx)
        ld      b,a
        call    rbt_tm_laddr
        ex      de,hl           ; DE = dst
        ld      a,c
        sub     8
        ld      c,a             ; src line = dst-8
        call    rbt_tm_laddr    ; HL = src
        ld      a,(rbt_tm_vw)
        ld      c,a
        ld      b,0
        ldir
        ld      a,(rbt_ct_r)
        dec     a
        ld      (rbt_ct_r),a
        jp      _shul
_shua   ; attr rows: dst row r+1 <- src row r, r = vy+vh-2 .. vy
        ld      a,(rbt_tm_vh)
        dec     a
        ld      b,a
        ld      a,(rbt_tm_vy)
        add     a,b
        dec     a
        ld      (rbt_ct_r),a    ; r = vy+vh-2
_shual  ld      a,(rbt_tm_vy)
        ld      b,a
        ld      a,(rbt_ct_r)
        cp      b
        ret     c               ; r < vy -> done
        ld      a,(rbt_tm_vx)
        ld      b,a
        ld      a,(rbt_ct_r)
        inc     a
        ld      c,a
        call    rbt_tm_arow
        ex      de,hl           ; DE = dst row r+1
        ld      a,(rbt_ct_r)
        ld      c,a
        call    rbt_tm_arow     ; HL = src row r
        ld      a,(rbt_tm_vw)
        ld      c,a
        ld      b,0
        ldir
        ld      a,(rbt_ct_r)
        dec     a
        ld      (rbt_ct_r),a
        jp      _shual

; ----------------------------------------------------------------------------
; rbt_tm_colid - B = screen col, C = map col: draw vh cells down the column.
; rbt_tm_rowid - B = screen row, C = map row: draw vw cells across the row.
; ----------------------------------------------------------------------------
rbt_tm_colid:
        ld      a,b
        ld      (rbt_ct_c),a
        ld      a,c
        ld      (rbt_ct_c0),a
        xor     a
        ld      (rbt_ct_r),a
_ccl    ld      a,(rbt_tm_vh)
        ld      b,a
        ld      a,(rbt_ct_r)
        cp      b
        ret     nc
        ld      a,(rbt_ct_c0)
        ld      b,a             ; mx
        ld      a,(rbt_tm_camy)
        ld      c,a
        ld      a,(rbt_ct_r)
        add     a,c
        ld      c,a             ; my = camy + r
        call    rbt_tm_mapat
        push    af
        ld      a,(rbt_ct_c)
        ld      b,a
        ld      a,(rbt_tm_vy)
        ld      c,a
        ld      a,(rbt_ct_r)
        add     a,c
        ld      c,a
        pop     af
        call    rbt_tm_blit
        ld      a,(rbt_ct_r)
        inc     a
        ld      (rbt_ct_r),a
        jp      _ccl

rbt_tm_rowid:
        ld      a,b
        ld      (rbt_ct_r),a
        ld      a,c
        ld      (rbt_ct_r0),a
        xor     a
        ld      (rbt_ct_c),a
_crl    ld      a,(rbt_tm_vw)
        ld      b,a
        ld      a,(rbt_ct_c)
        cp      b
        ret     nc
        ld      a,(rbt_tm_camx)
        ld      b,a
        ld      a,(rbt_ct_c)
        add     a,b
        ld      b,a             ; mx = camx + c
        ld      a,(rbt_ct_r0)
        ld      c,a             ; my
        call    rbt_tm_mapat
        push    af
        ld      a,(rbt_tm_vx)
        ld      b,a
        ld      a,(rbt_ct_c)
        add     a,b
        ld      b,a
        ld      a,(rbt_ct_r)
        ld      c,a
        pop     af
        call    rbt_tm_blit
        ld      a,(rbt_ct_c)
        inc     a
        ld      (rbt_ct_c),a
        jp      _crl

; ----------------------------------------------------------------------------
; rbt_tm_scroll - A = dir (0=left,1=right,2=up,3=down), B = steps.
; Moves camera; per step, shifts the view's screen bytes one cell and draws
; only the newly exposed column/row.
; ----------------------------------------------------------------------------
rbt_tm_scroll:
        and     3
        ld      (rbt_tm_dir),a
        ld      a,b
        or      a
        ret     z
        ld      (rbt_tm_steps),a
_slp    ld      a,(rbt_tm_dir)
        or      a
        jr      nz,_sr
        ; left: camx--
        ld      a,(rbt_tm_camx)
        or      a
        jp      z,_sdone
        dec     a
        ld      (rbt_tm_camx),a
        call    rbt_tm_shr              ; content shifts right
        ld      a,(rbt_tm_vx)
        ld      b,a
        ld      a,(rbt_tm_camx)
        ld      c,a
        call    rbt_tm_colid            ; draw left edge column
        jp      _snext
_sr     cp      1
        jr      nz,_su
        ; right: camx++ iff camx+vw < mw
        ld      a,(rbt_tm_camx)
        ld      b,a
        ld      a,(rbt_tm_vw)
        add     a,b
        ld      b,a
        ld      a,(rbt_tm_mw)
        cp      b
        jp      c,_sdone
        jp      z,_sdone
        ld      a,(rbt_tm_camx)
        inc     a
        ld      (rbt_tm_camx),a
        call    rbt_tm_shl              ; content shifts left
        ld      a,(rbt_tm_vx)
        ld      b,a
        ld      a,(rbt_tm_vw)
        add     a,b
        dec     a
        ld      b,a                     ; screen col vx+vw-1
        ld      a,(rbt_tm_camx)
        ld      c,a
        ld      a,(rbt_tm_vw)
        add     a,c
        dec     a
        ld      c,a                     ; map col camx+vw-1
        call    rbt_tm_colid            ; draw right edge column
        jp      _snext
_su     cp      2
        jr      nz,_sdn
        ; up: camy--
        ld      a,(rbt_tm_camy)
        or      a
        jp      z,_sdone
        dec     a
        ld      (rbt_tm_camy),a
        call    rbt_tm_shu              ; content shifts down
        ld      a,(rbt_tm_vy)
        ld      b,a
        ld      a,(rbt_tm_camy)
        ld      c,a
        call    rbt_tm_rowid            ; draw top edge row
        jp      _snext
_sdn    ; down: camy++ iff camy+vh < mh
        ld      a,(rbt_tm_camy)
        ld      b,a
        ld      a,(rbt_tm_vh)
        add     a,b
        ld      b,a
        ld      a,(rbt_tm_mh)
        cp      b
        jp      c,_sdone
        jp      z,_sdone
        ld      a,(rbt_tm_camy)
        inc     a
        ld      (rbt_tm_camy),a
        call    rbt_tm_shd              ; content shifts up
        ld      a,(rbt_tm_vy)
        ld      b,a
        ld      a,(rbt_tm_vh)
        add     a,b
        dec     a
        ld      b,a                     ; screen row vy+vh-1
        ld      a,(rbt_tm_camy)
        ld      c,a
        ld      a,(rbt_tm_vh)
        add     a,c
        dec     a
        ld      c,a                     ; map row camy+vh-1
        call    rbt_tm_rowid            ; draw bottom edge row
_snext  ld      a,(rbt_tm_steps)
        dec     a
        ld      (rbt_tm_steps),a
        jp      nz,_slp
_sdone  ret

; ----------------------------------------------------------------------------
; rbt_tileat - B=tx, C=ty (map coords) -> A = tile id (255 = out of bounds)
; ----------------------------------------------------------------------------
rbt_tileat:
        ld      a,(rbt_tm_mw)
        cp      b
        jr      c,_ta0
        jr      z,_ta0
        ld      a,(rbt_tm_mh)
        cp      c
        jr      c,_ta0
        jr      z,_ta0
        call    rbt_tm_mapat
        ret
_ta0    ld      a,255
        ret

; ----------------------------------------------------------------------------
; rbt_tileatset - B=tx, C=ty, D=id : write map cell if in bounds
; ----------------------------------------------------------------------------
rbt_tileatset:
        ld      hl,rbt_tm_mprev
        ld      a,(rbt_tm_mbank)
        call    rbt_pg_in       ; page map bank
        call    _tsb
        ld      hl,rbt_tm_mprev
        jp      rbt_pg_out

_tsb    ld      a,(rbt_tm_mw)
        cp      b
        ret     c
        ret     z
        ld      a,(rbt_tm_mh)
        cp      c
        ret     c
        ret     z
        ; same offset calc as rbt_tm_mapat
        push    de
        push    bc
        ld      hl,(rbt_tm_cells)
        ld      a,c
        or      a
        jr      z,_tax
        ld      b,a
        ld      a,(rbt_tm_mw)
        ld      e,a
        ld      d,0
_tal    add     hl,de
        djnz    _tal
_tax    pop     bc
        ld      e,b
        ld      d,0
        add     hl,de
        pop     de
        ld      (hl),d
        ret

; ----------------------------------------------------------------------------
; rbt_tileflags - A = tile id -> A = flags byte (0 if out of range)
; ----------------------------------------------------------------------------
rbt_tileflags:
        ld      b,a             ; B = tile id (pg_in preserves BC)
        ld      hl,rbt_tm_tprev
        ld      a,(rbt_tm_tbank)
        call    rbt_pg_in       ; page tileset bank
        call    _tfb
        ld      hl,rbt_tm_tprev
        jp      rbt_pg_out      ; restores bank; preserves A = flags

_tfb    ld      a,(rbt_tm_n)
        cp      b
        jr      c,_tf0
        jr      z,_tf0
        ld      a,b
        ld      e,a
        ld      d,0
        ld      hl,(rbt_tm_tflags)
        add     hl,de
        ld      a,(hl)
        ret
_tf0    xor     a
        ret

''',
    'tmdata': r'''
; ============================================================================
; rbt_tmdata_asm - tilemap state + map query (shared by tilemap engine and the
; sprite compositor). Var layouts documented in rbt_tilemap.asm.
; ============================================================================

rbt_tm_tiles    defw 0          ; tileset base
rbt_tm_bmp      defw 0          ; bitmaps (tiles+1)
rbt_tm_tattr    defw 0          ; attr table (tiles+1+8n)
rbt_tm_tflags   defw 0          ; flag table (tiles+1+9n)
rbt_tm_n        defb 0          ; tile count
rbt_tm_tbank    defb #ff        ; tileset bank (#ff = resident, 128K)
rbt_tm_map      defw 0          ; map base
rbt_tm_mbank    defb #ff        ; map bank (#ff = resident, 128K)
rbt_tm_tprev    defb 0          ; pg guard save (tileset)
rbt_tm_mprev    defb 0          ; pg guard save (map)
rbt_tm_cells    defw 0          ; map cells (map+2)
rbt_tm_mw       defb 0          ; map width
rbt_tm_mh       defb 0          ; map height
rbt_tm_vx       defb 0
rbt_tm_vy       defb 0
rbt_tm_vw       defb 32
rbt_tm_vh       defb 24
rbt_tm_camx     defb 0
rbt_tm_camy     defb 0
rbt_tm_r        defb 0
rbt_tm_c        defb 0
rbt_tm_dir      defb 0
rbt_tm_steps    defb 0
rbt_tm_cnt      defb 0
rbt_tm_tid      defb 0
rbt_ct_c0       defb 0
rbt_ct_c1       defb 0
rbt_ct_r0       defb 0
rbt_ct_r1       defb 0
rbt_ct_r        defb 0
rbt_ct_c        defb 0

; ----------------------------------------------------------------------------
; rbt_tm_mapat - B=mx, C=my -> A = tile id (0 when out of bounds). Clobbers DE,HL.
; ----------------------------------------------------------------------------
rbt_tm_mapat:
        ld      hl,rbt_tm_mprev
        ld      a,(rbt_tm_mbank)
        call    rbt_pg_in       ; page map bank (no-op when resident)
        call    _mab
        ld      hl,rbt_tm_mprev
        jp      rbt_pg_out      ; restores bank; preserves A = tile id

_mab    push    bc
        ld      a,(rbt_tm_mw)
        cp      b
        jr      c,_ma0
        jr      z,_ma0          ; mx >= w
        ld      a,(rbt_tm_mh)
        cp      c
        jr      c,_ma0
        jr      z,_ma0          ; my >= h
        ld      hl,(rbt_tm_cells)
        ld      a,c
        or      a
        jr      z,_addx
        ld      b,a             ; loop my times
        ld      a,(rbt_tm_mw)
        ld      e,a
        ld      d,0             ; DE = w
_mal    add     hl,de
        djnz    _mal
_addx   pop     bc
        ld      e,b
        ld      d,0
        add     hl,de
        ld      a,(hl)
        ret
_ma0    pop     bc
        xor     a
        ret
''',
