  'cpc': {
    'math': r'''
; ============================================================================
; rbt_math_asm - arithmetic helpers for 8/16-bit ops
; ============================================================================

; ----------------------------------------------------------------------------
; rbt_mul8 - HL = D * E (unsigned, low 16 bits)
; ----------------------------------------------------------------------------
rbt_mul8:
        ld      hl,0
        ld      b,8
_ml     add     hl,hl
        sla     d
        jr      nc,_m0
        ld      a,l
        add     a,e
        ld      l,a
        jr      nc,_m0
        inc     h
_m0     djnz    _ml
        ret

; ----------------------------------------------------------------------------
; rbt_divmod8 - in: A = dividend, B = divisor. out: A = quotient, B = remainder
; ----------------------------------------------------------------------------
rbt_divmod8:
        ld      c,a
        xor     a
        ld      e,a             ; quotient
        ld      a,b
        or      a
        jr      z,_dz           ; divisor 0: return q=0, r=0
        ld      a,c
_dl     cp      b
        jr      c,_done
        sub     b
        inc     e
        jr      _dl
_done   ld      b,a             ; remainder
        ld      a,e             ; quotient
_dz     ret                     ; (a==0 here on the _dz path)

; ----------------------------------------------------------------------------
; rbt_mul16 - HL = DE * HL (low 16 bits; works for signed too)
; ----------------------------------------------------------------------------
rbt_mul16:
        ld      b,h
        ld      c,l
        ld      hl,0
        ld      a,16
_ml     add     hl,hl
        sla     c
        rl      b
        jr      nc,_m0
        add     hl,de
_m0     dec     a
        jr      nz,_ml
        ret

; ----------------------------------------------------------------------------
; rbt_divmod16 - unsigned: BC / DE -> BC = quotient, HL = remainder
; ----------------------------------------------------------------------------
rbt_divmod16:
        ld      hl,0            ; remainder
        ld      a,d
        or      e
        jr      z,_dz           ; divisor 0: return q=0, r=0
        ld      a,16
_dl     sla     c               ; num <<= 1, bit15 -> CY
        rl      b
        rl      l               ; rem <<= 1 + CY
        rl      h
        sbc     hl,de
        jr      nc,_q1
        add     hl,de           ; restore (CY=0 -> quotient bit 0)
        jr      _nxt
_q1     inc     c               ; quotient bit 1
_nxt    dec     a
        jr      nz,_dl
        ret
_dz     ld      b,h             ; quotient BC=0, remainder HL=0
        ld      c,l
        ret

; ----------------------------------------------------------------------------
; rbt_sdivmod16 - signed: BC / DE -> BC = quotient, HL = remainder
; quotient truncates toward zero; remainder takes dividend's sign.
; ----------------------------------------------------------------------------
rbt_sdivmod16:
        xor     a
        ld      (rbt_divsign),a ; bit0: result negative
        bit     7,b
        jr      z,_nnum
        ; negate BC
        ld      a,c
        cpl
        ld      c,a
        ld      a,b
        cpl
        ld      b,a
        inc     bc
        ld      a,(rbt_divsign)
        xor     1
        ld      (rbt_divsign),a
_nnum   bit     7,d
        jr      z,_ndiv
        ; negate DE
        ld      a,e
        cpl
        ld      e,a
        ld      a,d
        cpl
        ld      d,a
        inc     de
        ld      a,(rbt_divsign)
        xor     1
        ld      (rbt_divsign),a
_ndiv   call    rbt_divmod16
        ld      a,(rbt_divsign)
        or      a
        ret     z
        ; negate quotient BC
        ld      a,c
        cpl
        ld      c,a
        ld      a,b
        cpl
        ld      b,a
        inc     bc
        ret

rbt_divsign     defb 0

; ----------------------------------------------------------------------------
; rbt_neg16 - HL = -HL (two's complement)
; ----------------------------------------------------------------------------
rbt_neg16:
        xor     a
        sub     l
        ld      l,a
        sbc     a,a
        sub     h
        ld      h,a
        ret

; ----------------------------------------------------------------------------
; rbt_abs16 - HL = |HL|
; ----------------------------------------------------------------------------
rbt_abs16:
        bit     7,h
        ret     z
        jr      rbt_neg16
''',
    'ay': r'''
; ============================================================================
; rbt_ay_asm - Rainbow AY-3-8912 music player (Amstrad CPC)
;
; rbt_ay_start - HL = .ray song data; starts playback (non-blocking).
; rbt_ay_tick  - call once per frame (auto-called from rbt_vsync/rbt_pause
;                via rbt_frame_hook, or explicitly with MUSIC TICK).
; rbt_ay_stop  - stop playback and silence all channels.
;
; Same .ray row format as the ZX player: defb dur, then regs r0..r13
; (r13 = #ff = don't touch); end marker defb 0, defw loop offset
; (#ffff = stop + silence). The encoder rescales AY periods for the
; CPC's 1 MHz clock (ZX AY = 1.7734 MHz) so .ray assets are portable.
; All register traffic goes through rbt_psg (PPI-mediated).
; ============================================================================

; ----------------------------------------------------------------------------
; rbt_ay_start - HL = song data
; ----------------------------------------------------------------------------
rbt_ay_start:
        ld      (rbt_ay_base),hl
        ld      (rbt_ay_pos),hl
        ld      a,(rbt_cur_bank)        ; remember the song's bank
        ld      (rbt_ay_bank),a
        xor     a
        ld      (rbt_ay_dur),a          ; force row load on next tick
        inc     a
        ld      (rbt_ay_on),a
        ret

; ----------------------------------------------------------------------------
; rbt_ay_stop - stop playback and silence all channels.
; ----------------------------------------------------------------------------
rbt_ay_stop:
        xor     a
        ld      (rbt_ay_on),a
        ; fall through: silence the chip (vols 0, tone+noise off)
rbt_ay_silence:
        ld      e,7                     ; mixer: all off (#3f)
        ld      d,#3f
        call    rbt_psg
        ld      e,8                     ; regs 8,9,10 = channel volumes -> 0
        ld      d,0
_vol    call    rbt_psg
        inc     e
        ld      a,e
        cp      11
        jr      c,_vol
        ret

; ----------------------------------------------------------------------------
; rbt_ay_tick - advance one frame (called from rbt_hook_frame / MUSIC TICK)
; ----------------------------------------------------------------------------
rbt_ay_tick:
        ld      a,(rbt_ay_on)
        or      a
        ret     z
        ; page in the song bank, restore the caller's on exit. The save
        ; byte lives in RAM, not AF' - the firmware ISR owns the alt set.
        ld      a,(rbt_ay_bank)
        ld      hl,rbt_ay_prev
        call    rbt_pg_in
        call    _work
        ld      hl,rbt_ay_prev
        jp      rbt_pg_out              ; restore previous mapping (ret)
_work:
        ld      a,(rbt_ay_dur)
        or      a
        jr      z,_row
        dec     a
        ld      (rbt_ay_dur),a
        ret     nz
_row    ld      hl,(rbt_ay_pos)
        ld      a,(hl)                  ; dur byte
        or      a
        jr      z,_end
        ld      (rbt_ay_dur),a
        inc     hl
        ; write r0..r12 unconditionally, r13 unless #ff
        ld      e,0
_wr     ld      d,(hl)
        push    hl
        call    rbt_psg
        pop     hl
        ld      a,e
        cp      7
        jr      nz,_wnr
        ld      a,d
        ld      (rbt_ay_r7),a         ; shadow mixer for the sfx channel steal
_wnr
        inc     hl
        inc     e
        ld      a,e
        cp      13
        jr      c,_wr
        ld      a,(hl)                  ; r13 env shape: #ff = skip
        inc     hl
        cp      #ff
        jr      z,_next
        ld      d,a
        call    rbt_psg
_next   ld      (rbt_ay_pos),hl
        ret
_end    inc     hl
        ld      e,(hl)                  ; loop row offset (#ffff = stop)
        inc     hl
        ld      d,(hl)
        ld      a,d
        and     e
        inc     a
        jp      z,rbt_ay_stop           ; #ffff -> stop + silence
        ld      hl,(rbt_ay_base)
        add     hl,de
        ld      (rbt_ay_pos),hl
        ret

; ----------------------------------------------------------------------------
rbt_ay_base     dw 0                    ; song data base
rbt_ay_pos      dw 0                    ; current row pointer
rbt_ay_dur      db 0                    ; frames left on current row
rbt_ay_on       db 0                    ; playback active flag
rbt_ay_r7       db 0                    ; last mixer (r7) written - sfx steal mask
rbt_ay_bank     db #c0                  ; mapping the song data lives in (#c0 = resident)
rbt_ay_prev     db 0                    ; mapping save byte for the tick guard
''',
    'bank': r'''
; ============================================================================
; rbt_bank_asm - 6128 memory paging + disc bank loader (Amstrad CPC)
;
; The 6128's second 64K is four 16K pages (physical banks 4-7) mapped by
; the gate array MMR into the #4000-#7FFF window. Resident code lives at
; #8000 (physical bank 2) and the screen stays at #C000 (bank 3) so
; banked assets can page through #4000 without evicting either.
;
; MMR writes go to port #7Fxx (bits 7:6 = 11 -> MMR function):
;   #C0   = normal linear mapping (banks 0,1,2,3)
;   #C4+n = physical bank 4+n at #4000-#7FFF
; A 464 ignores these writes (no secondary RAM), but the module is only
; linked on cpc6128 builds anyway. The MMR is user domain: no firmware
; routine writes it, so a bank stays paged across interrupts and firmware
; calls (only the RMR rom enables get far-called).
;
; rbt_bank     - A = physical bank (4-7) to page in, or an MMR byte >= #C0
;                written raw (the restore path passes shadow bytes through).
;                rbt_cur_bank holds the last byte written.
; rbt_copybank - copy a banked asset into resident RAM:
;                A = bank, HL = src (#4000 window), DE = dst, BC = len
;                pages the bank in, LDIRs, restores the previous mapping
;                (dst must be outside #4000-#7FFF)
; rbt_pg_in    - A = bank byte (#FF = resident), HL -> save byte. Pages in.
; rbt_pg_out   - HL -> save byte. Restores the saved mapping.
; rbt_bankload - loads BANK<n>.BIN into each bank named in rbt_bankfiles
;                (emitted by the compiler). Called once from rbt_start.
; ============================================================================

FW_CAS_IN_OPEN  equ #bc77       ; HL = filename, B = len, DE = 2k work buffer
FW_CAS_IN_CLOSE equ #bc7a
FW_CAS_IN_DIR   equ #bc83       ; HL = load address
FW_KL_INIT_BACK equ #bcce       ; C = rom select, DE/HL = memory pool bounds

rbt_bank:
        push    bc
        cp      #c0
        jr      nc,_wr                  ; already an MMR byte
        or      #c0                     ; bank 4-7 -> config #c4-#c7
_wr     ld      (rbt_cur_bank),a
        ld      bc,#7f00
        out     (c),a                   ; MMR: ram bank at #4000
        pop     bc
        ret

rbt_copybank:
        di                              ; the firmware ISR owns the alt
        push    af                      ; registers AND rewrites the MMR
        ld      a,(rbt_cur_bank)        ; via a stale shadow value, so a
        ld      (rbt_cb_prev),a         ; bank must stay paged across the
        pop     af                      ; whole transfer atomically
        call    rbt_bank
        ldir                            ; hl -> de, bc bytes
        ld      a,(rbt_cb_prev)
        call    rbt_bank                ; restore previous mapping
        ei
        ret

rbt_cur_bank    db #c0                  ; last MMR byte written (#c0 = normal)
rbt_cb_prev     db 0                    ; copybank mapping save byte

; ----------------------------------------------------------------------------
; rbt_bankload - pull each banked-asset blob off disc into its RAM bank.
; rbt_bankfiles is emitted by the compiler: defb bank, defm "BANKn.BIN"
; records terminated by defb #ff. Files are AMSDOS binaries written by
; the .dsk packager.
;
; MC_START_PROGRAM (the firmware call that execs a RUN'd binary) shuts
; down all expansion ROMs, so AMSDOS's hook on the cassette vectors is
; gone and CAS_IN_OPEN would prompt for tape. KL_INIT_BACK on rom 7
; reinstalls it first. The memory pool is capped at #3fff so AMSDOS's
; work area can't sit under the #4000-#7fff bank window.
;
; Each file is loaded directly into its bank: the MMR pages the bank at
; #4000 before CAS IN DIRECT - the PAL is user domain so the firmware
; leaves the mapping alone - then #c0 restores the base 64k. The 2k
; cassette work buffer sits at #2000, outside the window. A missing
; file just skips its bank.
;
; Cart builds (RBT_CART) can't open files at all - each bank blob is a
; 16K cart page instead (page 0 is this resident code, blobs take pages
; 1..n in bank order). The compiler emits rbt_cartfiles: defb bank,
; defb page, defw size records, #FF-terminated. Selecting a page via
; the ROM-select port (id >= #80 -> cart block) plus RMR upper-rom-on
; makes it readable at #C000 while the RAM bank is paged at #4000, so
; the copy is a plain LDIR - no trampoline needed since the code page
; stays mapped at #0000. Screen RAM at #C000 is write-through under the
; ROM so the display is unaffected.
; ----------------------------------------------------------------------------
        if      RBT_CART
rbt_bankload:
        ld      hl,rbt_cartfiles
_cfl    ld      a,(hl)          ; bank id, #FF = end of table
        cp      #ff
        jr      z,_cfd
        inc     hl
        call    rbt_bank        ; page the RAM bank at #4000
        ld      a,(hl)          ; cart page -> upper ROM window
        inc     hl
        or      #80
        ld      bc,#df00
        out     (c),a
        ld      a,(rbt_rmr)     ; UR=0: cart page readable at #C000
        and     #f7
        ld      bc,#7f00
        out     (c),a
        ld      e,(hl)          ; DE = blob size (always <= #4000)
        inc     hl
        ld      d,(hl)
        inc     hl
        push    hl
        ld      b,d
        ld      c,e
        ld      hl,#c000
        ld      de,#4000
        ldir                    ; cart page -> RAM bank
        ld      a,(rbt_rmr)     ; UR=1: upper ROM back off
        or      #08
        ld      bc,#7f00
        out     (c),a
        pop     hl
        jr      _cfl
_cfd    ld      a,#c0
        jp      rbt_bank        ; restore normal mapping (ret)
        else
rbt_bankload:
        ld      de,#0040                ; first usable byte of memory
        ld      hl,#3fff                ; pool top: below the bank window
        ld      c,7                     ; AMSDOS rom select
        call    FW_KL_INIT_BACK
        ld      hl,rbt_bankfiles
_bfl    ld      a,(hl)                  ; bank id, #FF = end of table
        cp      #ff
        jr      z,_bfd
        push    hl                      ; record start
        inc     hl
        ld      b,9                     ; "BANKn.BIN"
        ld      de,#2000                ; work buffer outside the window
        call    FW_CAS_IN_OPEN
        pop     hl                      ; record start
        jr      nc,_bfn                 ; open failed -> next record
        push    hl
        ld      a,(hl)                  ; bank id
        call    rbt_bank                ; page it at #4000
        ld      hl,#4000
        call    FW_CAS_IN_DIR           ; data lands in the bank directly
        ld      a,#c0
        call    rbt_bank                ; normal mapping
        call    FW_CAS_IN_CLOSE
        pop     hl
_bfn    inc     hl                      ; past bank byte
        ld      de,9                    ; past filename -> next record
        add     hl,de
        jr      _bfl
_bfd    ld      a,#c0
        jp      rbt_bank                ; restore normal mapping (ret)
        endif

; ----------------------------------------------------------------------------
; rbt_pg_in / rbt_pg_out - nestable page guard for banked data access.
;
; pg_in:  A = bank byte (#FF = resident, nothing to page), HL -> save byte.
;         Stores the current MMR byte in (HL) and pages the given bank in.
;         Preserves all registers.
; pg_out: HL -> the same save byte. Restores the saved mapping.
;         Preserves all registers (including A).
;
; Guards nest correctly as long as each call site uses its own save byte.
; On 464 builds (no bank module) the compiler emits ret stubs; bank bytes
; are always #FF there so pg_in would early-out anyway.
; ----------------------------------------------------------------------------
rbt_pg_in:
        di                      ; atomic: a mid-guard ISR would restore
        push    af              ; the kernel's stale RMR shadow and
        ld      a,(rbt_cur_bank); unmap the bank under us
        ld      (hl),a          ; save previous mapping
        pop     af
        inc     a
        jp      z,rbt_pg_out    ; #FF = resident: restore ei and out
        dec     a
        jp      rbt_bank

rbt_pg_out:
        push    af
        ld      a,(hl)
        call    rbt_bank
        pop     af
        ei
        ret
''',
    'charset': r'''
; ============================================================================
; rbt_charset_asm - text output via the CPC firmware TXT pack
;
; INK/PAPER take ZX colour indices (0-7) and program pen 1 / pen 0 inks so
; portable code keeps its colours (INK 7 = white text on both machines).
; BRIGHT selects the bright-ink translation table; FLASH programs pen 1 to
; alternate between the current ink and paper colours.
; (rbt_col/rbt_row/rbt_over/rbt_attr vars live in core)
; ============================================================================

rbt_inkv        defb 7          ; current logical ink   (ZX colour)
rbt_papv        defb 0          ; current logical paper (ZX colour)
rbt_brightv     defb 0          ; 0 = normal, 1 = bright inks
rbt_flashv      defb 0          ; 0 = steady, 1 = ink/paper alternating
        if      RBT_CART
rbt_font        defw rbt_cartfont ; embedded font — there is no firmware one
        else
rbt_font        defw 0          ; .rbf glyph data (0 = use the firmware font)
        endif
rbt_fontbank    defb #ff        ; stored by CHARSET (#ff = resident)
rbt_fontprev    defb 0          ; mapping save byte for the glyph guard
rbt_p16s        defb 0          ; print_u16 leading-zero flag (B' is unsafe:
                                ; the firmware ISR owns the alt registers)

; bright variants of rbt_zx2cpc (in core): blue->2 red->6 magenta->8
; green->19 cyan->21 yellow->24 white->26
rbt_zx2cpc_b:   defb 0,2,6,8,19,21,24,26

; ----------------------------------------------------------------------------
; rbt_locate - set cursor. In: B = column (0-31), C = row (0-23).
; Firmware coordinates are 1-based; CPC has no 32-column mode so columns
; beyond the mode width wrap harmlessly in the firmware.
; ----------------------------------------------------------------------------
rbt_locate:
        ld      a,b
        cp      32
        jr      c,_colok
        xor     a
_colok  ld      (rbt_col),a
        if      RBT_CART
        else                    ; logical vars are all the font path needs
        inc     a
        call    FW_TXT_SET_COL           ; TXT SET COLUMN
        endif
        ld      a,c
        cp      24
        jr      c,_rowok
        xor     a
_rowok  ld      (rbt_row),a
        if      RBT_CART
        else
        inc     a
        call    FW_TXT_SET_ROW           ; TXT SET ROW
        endif
        ret

; ----------------------------------------------------------------------------
; rbt_putchar - print char A. With a custom font (CHARSET) glyphs are drawn
; via rbt_tile8 at the logical cell; otherwise the firmware cursor prints
; (auto-advance, wrap, scroll). Keeps rbt_col/rbt_row in step.
; ----------------------------------------------------------------------------
rbt_putchar:
        push    af              ; keep the char - the font probe clobbers A
        push    hl
        ld      hl,(rbt_font)
        ld      a,h
        or      l
        pop     hl
        jr      nz,_font
        pop     af
        call    FW_TXT_OUTPUT           ; TXT OUTPUT
        ld      a,(rbt_col)
        inc     a
        cp      32
        jr      c,_adv
        xor     a
        ld      (rbt_col),a
        ld      a,(rbt_row)
        inc     a
        cp      24
        jr      c,_advrow
        xor     a
_advrow ld      (rbt_row),a
        ld      a,(rbt_col)
        ret
_adv    ld      (rbt_col),a
        ret
_font   pop     af
        ; fall through
; ----------------------------------------------------------------------------
; rbt_cs_putf - draw char A as an 8x8 pen1/pen0 glyph at (rbt_col,rbt_row).
; .rbf data = 96 glyphs x 8 bytes, 1bpp, expanded by rbt_tile8.
; ----------------------------------------------------------------------------
rbt_cs_putf:
        sub     32
        cp      96
        jr      c,_glyph
        ld      a,'?'-32        ; out-of-range -> '?'
_glyph  ; glyph = font + a*8
        ld      e,a
        ld      d,0
        sla     e
        rl      d
        sla     e
        rl      d
        sla     e
        rl      d               ; DE = (code-32)*8
        ld      hl,(rbt_font)
        add     hl,de
        ex      de,hl           ; DE = glyph src
        ld      a,(rbt_col)
        ld      b,a
        ld      a,(rbt_row)
        ld      c,a
        ld      a,(rbt_fontbank)
        ld      hl,rbt_fontprev
        call    rbt_pg_in       ; page the font bank (#ff = resident)
        call    rbt_tile8       ; B=cell x, C=cell y, DE=src
        ld      hl,rbt_fontprev
        call    rbt_pg_out
        ; advance the logical cursor (wrap, no scroll)
        ld      a,(rbt_col)
        inc     a
        cp      32
        jr      c,_padv
        xor     a
        ld      (rbt_col),a
        ld      a,(rbt_row)
        inc     a
        cp      24
        jr      c,_prw
        xor     a
_prw    ld      (rbt_row),a
        ret
_padv   ld      (rbt_col),a
        ret

; ----------------------------------------------------------------------------
; rbt_newline - CR + LF (firmware path only; the font path just wraps vars)
; ----------------------------------------------------------------------------
rbt_newline:
        xor     a
        ld      (rbt_col),a
        push    hl
        ld      hl,(rbt_font)
        ld      a,h
        or      l
        pop     hl
        jr      nz,_nlrow       ; font path: skip firmware output
        ld      a,13
        call    FW_TXT_OUTPUT
        ld      a,10
        call    FW_TXT_OUTPUT
_nlrow  ld      a,(rbt_row)
        inc     a
        cp      24
        jr      c,_r
        xor     a
_r      ld      (rbt_row),a
        ret

; ----------------------------------------------------------------------------
; rbt_cs_inkval - ZX colour A -> CPC ink, honouring rbt_brightv
; ----------------------------------------------------------------------------
rbt_cs_inkval:
        and     7
        ld      hl,rbt_zx2cpc
        ld      b,a
        ld      a,(rbt_brightv)
        or      a
        jr      z,_tab
        ld      hl,rbt_zx2cpc_b
_tab    ld      a,b
        ld      d,0
        ld      e,a
        add     hl,de
        ld      a,(hl)
        ret

; ----------------------------------------------------------------------------
; rbt_cs_apply - program pen 1 (text) and pen 0 (paper) from the logical vars.
; FLASH alternates pen 1 between ink and paper inks.
; ----------------------------------------------------------------------------
rbt_cs_apply:
        ld      a,(rbt_inkv)
        call    rbt_cs_inkval         ; A = CPC ink for text
        ld      b,a
        ld      a,(rbt_flashv)
        or      a
        jr      z,_steady
        ld      a,(rbt_papv)
        call    rbt_cs_inkval         ; flash: second colour = paper ink
        ld      c,a
        jr      _setpen
_steady ld      c,b
_setpen ld      a,1             ; pen 1 = text pen
        if      RBT_CART
        ld      d,b             ; rbt_gpen: A=pen, D=ink1, E=ink2
        ld      e,c
        call    rbt_gpen
        ld      a,(rbt_papv)
        call    rbt_cs_inkval
        ld      d,a
        ld      e,a
        xor     a               ; pen 0 = paper
        call    rbt_gpen
        else
        call    FW_SCR_SET_INK           ; SCR SET INK A=pen B=ink1 C=ink2
        ld      a,(rbt_papv)
        call    rbt_cs_inkval
        ld      b,a
        ld      c,a
        xor     a               ; pen 0 = paper
        call    FW_SCR_SET_INK
        ld      a,1
        call    FW_TXT_SET_PEN           ; TXT SET PEN 1
        xor     a
        call    FW_TXT_SET_PAP           ; TXT SET PAPER 0
        endif
        ret

; ----------------------------------------------------------------------------
; rbt_ink / rbt_paper / rbt_bright / rbt_flash - attribute state (A = value)
; ----------------------------------------------------------------------------
rbt_ink:
        ld      (rbt_inkv),a
        jr      rbt_cs_apply
rbt_paper:
        ld      (rbt_papv),a
        jr      rbt_cs_apply
rbt_bright:
        ld      (rbt_brightv),a
        jr      rbt_cs_apply
rbt_flash:
        ld      (rbt_flashv),a
        jr      rbt_cs_apply

; ----------------------------------------------------------------------------
; rbt_fillattr - FILLATTR x,y,w,h. CPC has no attribute plane, so the
; ZX meaning (recolour a cell rect) maps to programming the pen inks from
; the logical INK/PAPER vars - a whole-screen recolour. Correct for the
; common full-screen use; partial rects recolour everything.
; ----------------------------------------------------------------------------
rbt_fillattr:
        jp      rbt_cs_apply

; ----------------------------------------------------------------------------
; rbt_print_str - print length-prefixed string at HL: defb len,"text"
; ----------------------------------------------------------------------------
rbt_print_str:
        ld      b,(hl)
        inc     hl
        ld      a,b
        or      a
        ret     z
_ps     ld      a,(hl)
        push    hl
        push    bc
        call    rbt_putchar
        pop     bc
        pop     hl
        inc     hl
        djnz    _ps
        ret

; ----------------------------------------------------------------------------
; rbt_print_u8 - print A as decimal (no leading zeros)
; ----------------------------------------------------------------------------
rbt_print_u8:
        ld      l,a
        ld      h,0
        ; fall through
; ----------------------------------------------------------------------------
; rbt_print_u16 - print HL as decimal (no leading zeros). rbt_p16s = started
; flag - the ZX version kept it in B' via EXX, but on CPC the firmware ISR
; owns the alternate registers, so EXX here would corrupt the interrupt
; handler's state.
; ----------------------------------------------------------------------------
rbt_print_u16:
        xor     a
        ld      (rbt_p16s),a
        ld      de,-10000
        call    _digit
        ld      de,-1000
        call    _digit
        ld      de,-100
        call    _digit
        ld      de,-10
        call    _digit
        ld      a,1             ; units digit always prints
        ld      (rbt_p16s),a
        ld      de,-1
        call    _digit
        ret
_digit                          ; A = count of |de| subtracted (0-9)
        xor     a
_dl     add     hl,de           ; de is negative; carry means HL >= |de|
        jr      nc,_ovf         ; result went negative -> stop
        inc     a
        jr      _dl
_ovf    or      a               ; clear carry
        sbc     hl,de           ; undo the failed subtraction
        or      a               ; is count zero?
        jr      nz,_show
        ld      a,(rbt_p16s)
        or      a
        ret     z               ; leading zero, suppress
        xor     a               ; mid-number zero
_show   push    af
        ld      a,1
        ld      (rbt_p16s),a
        pop     af
        add     a,'0'
        push    hl              ; putchar clobbers HL
        call    rbt_putchar
        pop     hl
        ret
''',
    'core': r'''
; ============================================================================
; rbt_core_asm - Rainbow runtime core (Amstrad CPC)
; Entry point, frame sync, pause, border, cls, mode, RNG, waitkey.
;
; Firmware-backed: runs inside the firmware environment created by the CDT
; BASIC loader (pasmo --cdtbas -> CALL <org>). IM1 + EI are kept so the ROM
; ISR at &0038 keeps scanning the keyboard and driving the sound queue.
; The stack is inherited from the firmware - do NOT relocate it (system
; variables live above &A700).
; ============================================================================

FW_TXT_OUTPUT   equ #bb5a       ; TXT OUTPUT        A = char
FW_TXT_SET_COL  equ #bb6f       ; TXT SET COLUMN    A = column (1-based)
FW_TXT_SET_ROW  equ #bb72       ; TXT SET ROW       A = row (1-based)
FW_TXT_SET_PEN  equ #bb90       ; TXT SET PEN       A = pen number
FW_TXT_SET_PAP  equ #bb96       ; TXT SET PAPER     A = pen number
FW_KM_WAIT_CHAR equ #bb18       ; KM WAIT CHAR      -> A = char
FW_KM_READ_CHAR equ #bb09       ; KM READ CHAR      -> carry? A = char
FW_SCR_SET_OFF  equ #bc05       ; SCR SET OFFSET    HL = scroll offset
FW_SCR_SET_BASE equ #bc08       ; SCR SET BASE      A = base page (#c0 -> #c000)
FW_SCR_SET_MODE equ #bc0e       ; SCR SET MODE      A = mode 0-2
FW_SCR_CLEAR    equ #bc14       ; SCR CLEAR
FW_SCR_SET_INK  equ #bc32       ; SCR SET INK       A=pen B=ink1 C=ink2
FW_SCR_SET_BORD equ #bc38       ; SCR SET BORDER    B=C = ink
FW_MC_WAIT_FLY  equ #bd19       ; MC WAIT FLYBACK   preserves all regs
FW_KL_FAST_TK   equ #bce0       ; KL NEW FAST TICKER HL=blk B=cls C=rom DE=rtn

; ----------------------------------------------------------------------------
; ZX colour index (0-7) -> CPC hardware ink. Keeps BORDER/INK/PAPER values
; portable: INK 7 gives white text on both machines.
; ----------------------------------------------------------------------------
rbt_zx2cpc:     defb 0,1,3,4,9,10,12,13

rbt_start:
        if      RBT_CART
        ; cart boot (CPC+/GX4000): no firmware at all — the preamble set
        ; the stack and disabled interrupts; banks come off cart pages
        ; and the screen needs an explicit mode+clear
        call    rbt_crtc_init   ; GX4000 boots with a dead CRTC — program
                                ; the standard firmware video setup or
                                ; port B never sees a vsync
        call    rbt_ink_init    ; GA pens also start indeterminate — apply
                                ; the firmware default ink table
        call    rbt_bankload    ; cart pages -> RAM banks (stub if unbanked)
        call    rbt_scr_home
        ld      a,1
        call    rbt_scrmode     ; mode 1, the BASIC loader's default
        call    rbt_cls
        else
        ei                      ; firmware ISR is already IM1 at &0038
        call    rbt_bankload    ; cpc6128: pull BANKn.BIN files into RAM
                                ; banks (stubbed to ret on unbanked builds)
        call    rbt_scr_home    ; undo any firmware text scroll (loader msgs)
        endif
        call    rb_main         ; user program entry (MAIN:)
rbt_end:
        if      RBT_CART
        call    rbt_sfx_drain   ; no BASIC to return to — idle loop that
        call    rbt_wfly        ; keeps the 50Hz frame hooks ticking
        call    rbt_hook_frame
        jr      rbt_end
        else
        ret                     ; back to the BASIC loader / prompt
        endif

; ----------------------------------------------------------------------------
; rbt_vsync - wait for frame flyback (50 Hz), then run the frame hooks
; ----------------------------------------------------------------------------
        if      RBT_CART
; ----------------------------------------------------------------------------
; rbt_wfly - wait for frame flyback by polling the CRTC VSYNC flag on
; PPI port B bit 0 (cart builds: MC WAIT FLYBACK doesn't exist).
; ----------------------------------------------------------------------------
rbt_wfly:
        ld      bc,#f500
_wf0   in      a,(c)
        rra
        jr      c,_wf0          ; still in vsync -> wait it out
_wf1   in      a,(c)
        rra
        jr      nc,_wf1         ; wait for the next vsync
        ret

; ----------------------------------------------------------------------------
; rbt_gpen - program a gate-array pen directly (no firmware).
;   In: A = pen (0-15; 16 = border), D = ink1, E = ink2. Consecutive INKR
;   writes store the pair and the GA alternates them (hardware flash).
; ----------------------------------------------------------------------------
rbt_gpen:
        push    bc
        ld      bc,#7f00
        out     (c),a           ; PENR: select pen
        ld      a,d
        or      #40
        out     (c),a           ; INKR: ink1
        ld      a,e
        or      #40
        out     (c),a           ; INKR: ink2
        pop     bc
        ret

; ----------------------------------------------------------------------------
; rbt_kbd_any - A = 1 while any matrix key (incl. joystick line 9) is down.
; Lives in core (not input) because cart rbt_waitkey calls it even when
; the program never touches INKEY/JOYSTICK.
; ----------------------------------------------------------------------------
rbt_kbd_any:
        ld      e,0             ; E = line
_kal    ld      a,e
        push    de
        call    rbt_kbd_scan
        pop     de
        inc     a               ; #ff -> 0 = line clear
        jr      nz,_kay
        inc     e
        ld      a,e
        cp      10
        jr      c,_kal
        xor     a
        ret
_kay    ld      a,1
        ret

; ----------------------------------------------------------------------------
; rbt_crtc_init - program the CRTC with the standard firmware display
; setup (50Hz PAL, 25 text rows, screen at #C000). On a cart nothing else
; programs it: the GX4000 has no firmware and a bare CPC+ boots the cart
; before the firmware initialisation runs.
; ----------------------------------------------------------------------------
rbt_crtc_init:
        ld      e,0             ; E = register number
        ld      hl,rbt_crtc_def
_ci     ld      bc,#bc00
        out     (c),e           ; select reg E
        ld      a,(hl)
        inc     hl
        ld      bc,#bd00
        out     (c),a           ; write data
        inc     e
        ld      a,e
        cp      16
        jr      c,_ci
        ret

; CRTC regs 0-15: the values the CPC firmware uses — 63,40,46,#8E,38,0,
; 25,30,0,7 + cursor/screen-base regs (12=#30 -> display at #C000).
rbt_crtc_def:
        defb    63,40,46,#8e,38,0,25,30,0,7,0,0,#30,0,0,0

; ----------------------------------------------------------------------------
; rbt_ink_init - apply the firmware default pen table. Without firmware the
; GA colour registers hold whatever the ASIC powered up with (black on a
; GX4000), so a cart that never calls INK/PAPER/BORDER would be invisible.
; ----------------------------------------------------------------------------
rbt_ink_init:
        ld      hl,rbt_ink_def
        xor     a               ; A = pen 0..15
_ii     push    af
        ld      d,(hl)
        ld      e,d             ; same ink twice -> no hardware flash
        call    rbt_gpen
        inc     hl
        pop     af
        inc     a
        cp      16
        jr      c,_ii
        ld      a,16            ; border pen
        ld      de,#0404        ; firmware default border = ink 4 (blue)
        jp      rbt_gpen

rbt_ink_def:
        defb    4,24,20,6,26,0,2,8,10,12,14,16,18,22,1,30
        endif

rbt_vsync:
        call    rbt_sfx_drain   ; no-op stub when SFX module absent
        if      RBT_CART
        call    rbt_wfly
        else
        call    FW_MC_WAIT_FLY
        endif
        call    rbt_hook_frame
        ret

; ----------------------------------------------------------------------------
; rbt_pause - pause for B frames (B=0 waits for a keypress)
; ----------------------------------------------------------------------------
rbt_pause:
        call    rbt_sfx_drain
        ld      a,b
        or      a
        jr      z,rbt_waitkey
_ploop
        if      RBT_CART
        call    rbt_wfly
        else
        call    FW_MC_WAIT_FLY
        endif
        call    rbt_hook_frame
        djnz    _ploop
        ret

; ----------------------------------------------------------------------------
; rbt_waitkey - block until a key is pressed (firmware key manager; cart
; builds poll the matrix directly, frame-paced so the hooks still tick)
; ----------------------------------------------------------------------------
rbt_waitkey:
        call    rbt_sfx_drain
        if      RBT_CART
_wk     call    rbt_wfly
        call    rbt_hook_frame
        call    rbt_kbd_any
        or      a
        jr      z,_wk
_wkr    call    rbt_kbd_any     ; then wait for the release
        or      a
        jr      nz,_wkr
        else
        call    FW_KM_WAIT_CHAR ; needs EI: firmware ISR scans the matrix
        endif
        ret

; ----------------------------------------------------------------------------
; rbt_border - set border to A (ZX colour 0-7, mapped to CPC ink)
; ----------------------------------------------------------------------------
rbt_border:
        and     7
        ld      hl,rbt_zx2cpc
        ld      d,0
        ld      e,a
        add     hl,de
        ld      a,(hl)
        if      RBT_CART
        ld      d,a             ; border = GA pen 16, ink1=ink2
        ld      e,a
        ld      a,16
        jp      rbt_gpen
        else
        ld      b,a
        ld      c,a
        call    FW_SCR_SET_BORD
        endif
        ret

; ----------------------------------------------------------------------------
; rbt_scrmode - select CPC graphics mode (A = 0-2). Real switch on CPC;
; the ZX runtime implements this label as a no-op. Cart: the RMR byte is
; #88|mode — upper ROM off, lower ROM (our cart page) on.
; ----------------------------------------------------------------------------
rbt_scrmode:
        and     3
        if      RBT_CART
        or      #88
        ld      (rbt_rmr),a
        ld      bc,#7f00
        out     (c),a
        else
        call    FW_SCR_SET_MODE
        endif
        ret

; ----------------------------------------------------------------------------
; rbt_scr_home - reset CRTC screen base/offset to RBT_SCRB+0. Firmware text
; scrolling moves the display origin, which would shear our pixel writes.
; RBT_SCRP is the compiler-emitted base page (#c0 = screen at #C000, the
; only 16k window the 6128's c4-c7 configs never remap).
; ----------------------------------------------------------------------------
rbt_scr_home:
        xor     a
        ld      (rbt_scr_soff),a
        ld      (rbt_scr_soff+1),a      ; clear the hardware scroll offset
        if      RBT_CART
        ; CRTC regs 12/13 hold the display start in 2-byte units — #3000
        ; is the #c000 screen (RBT_SCRP is always #c0 on this runtime).
        ld      bc,#bc0c
        out     (c),c
        ld      bc,#bd30
        out     (c),c
        ld      bc,#bc0d
        out     (c),c
        ld      bc,#bd00
        out     (c),c
        ret
        else
        ld      hl,0
        call    FW_SCR_SET_OFF
        ld      a,RBT_SCRP
        jp      FW_SCR_SET_BASE
        endif

; ----------------------------------------------------------------------------
; rbt_crtc_r1213 - set the CRTC display start. HL = offset in CRTC units
; (2 bytes each, 0-1023) added to the #C000 base. No di/ei: callers bracket
; it (the split ISR already runs with interrupts masked).
; ----------------------------------------------------------------------------
rbt_crtc_r1213:
        push    bc
        ld      bc,#bc0c
        out     (c),c           ; select R12
        ld      a,h
        and     #03
        or      #30             ; page #C000 -> #30xx
        ld      bc,#bd00
        out     (c),a
        ld      bc,#bc0d
        out     (c),c           ; select R13
        ld      bc,#bd00
        out     (c),l
        pop     bc
        ret

; ----------------------------------------------------------------------------
; rbt_split_install - hang the band-split routine off the firmware fast
; ticker (fires on every GA raster interrupt). Idempotent. The cartridge
; build has no firmware events - static bands are unsupported there.
; ----------------------------------------------------------------------------
        if      RBT_CART
rbt_split_install:
        ret
        else
rbt_split_install:
        ld      a,(rbt_int_on)
        or      a
        ret     nz
        inc     a
        ld      (rbt_int_on),a
        ld      hl,rbt_evblk
        ld      b,#c1           ; class: async + express + near -> runs on
                                ; the interrupt path, central-32K routine
        xor     a
        ld      c,a             ; rom select (unused for near events)
        ld      de,rbt_split_isr
        jp      FW_KL_FAST_TK
        endif

rbt_evblk       defs 10         ; firmware event block (must sit in central RAM)

; hardware-scroll state (core: laddr/sprite code may link without tmdata)
rbt_scr_soff    defw 0          ; CRTC scroll offset in bytes (0-2047)
rbt_scr_split   defb 0          ; band split char row (0 = whole screen scrolls)
rbt_scr_son     defb 0          ; 1 = scrolled addressing active
rbt_scr_woff    defw 0          ; last scrolled laddr band offset (wrap math)
rbt_scr_wnat    defb 0          ; 1 = last laddr came out natural (band row)
rbt_split_int   defb 0          ; raster-int index that triggers the split
rbt_int_cnt     defb 0          ; int counter inside rbt_split_isr
rbt_int_on      defb 0          ; 1 = split ticker installed

; ----------------------------------------------------------------------------
; rbt_split_isr - fast-ticker routine, called on every GA raster interrupt
; (~6 per frame). The int that falls inside vertical sync re-writes the
; scrolled display start so each frame opens with the world offset; the int
; indexed by rbt_split_int (inside the char row above the band) restores the
; natural start so rows >= rbt_scr_split stay static.
; ----------------------------------------------------------------------------
rbt_split_isr:
        push    af
        push    bc
        push    hl
        ld      bc,#f500
        in      a,(c)           ; PPI port B bit 0 = vertical sync
        and     1
        jr      z,_sinv
        ; inside vsync (one int, maybe two if the counter straddles it):
        ; reset the frame counter and re-apply the scrolled display start
        ; so the next frame opens with the world offset. Idempotent.
        xor     a
        ld      (rbt_int_cnt),a
        ld      hl,(rbt_scr_soff)
        srl     h
        rr      l               ; bytes -> CRTC units
        call    rbt_crtc_r1213
        jr      _sio
_sinv   ld      a,(rbt_int_cnt)
        inc     a
        ld      (rbt_int_cnt),a
        cp      6
        jr      c,_sick
        xor     a               ; lost frame sync - clamp the counter
        ld      (rbt_int_cnt),a
        jr      _sio
_sick   ld      b,a
        ld      a,(rbt_split_int)
        or      a
        jr      z,_sio          ; no split armed
        cp      b
        jr      nz,_sio
        ld      a,(rbt_scr_split)
        or      a
        jr      z,_sio
        ld      l,a
        ld      h,0
        add     hl,hl
        add     hl,hl
        add     hl,hl           ; *8
        ld      d,h
        ld      e,l
        add     hl,hl
        add     hl,hl           ; *32
        add     hl,de           ; split row * 40 = band offset in CRTC units
        call    rbt_crtc_r1213
_sio    pop     hl
        pop     bc
        pop     af
        ret

; ----------------------------------------------------------------------------
; rbt_cls - clear screen (firmware; cart: fill the 16K screen with pen 0)
; and home our logical cursor
; ----------------------------------------------------------------------------
rbt_cls:
        call    rbt_scr_home
        if      RBT_CART
        ld      hl,#c000
        ld      de,#c001
        ld      bc,#3fff
        ld      (hl),0
        ldir
        else
        call    FW_SCR_CLEAR
        endif
        call    rbt_sp_reset    ; sprite commits are stale (stub if unused)
        xor     a
        ld      (rbt_col),a
        ld      (rbt_row),a
        ret

; ----------------------------------------------------------------------------
; rbt_rnd8 - 8-bit Galois LFSR. Out: A = pseudo-random byte
; ----------------------------------------------------------------------------
rbt_rnd8:
        ld      a,(rbt_seed)
        add     a,a
        jr      nc,_no_xor
        xor     #1d
_no_xor ld      (rbt_seed),a
        ret

; ----------------------------------------------------------------------------
; rbt_mod8 - A = A mod B (unsigned). Clobbers C,E.
; ----------------------------------------------------------------------------
rbt_mod8:
        ld      c,a
        xor     a
        ld      e,a             ; E = quotient
        ld      a,c
_dl     cp      b
        jr      c,_done
        sub     b
        inc     e
        jr      _dl
_done   ret                     ; A = remainder

; ----------------------------------------------------------------------------
; rbt_psg - write an AY register through the 8255 PPI.
;   In: E = register (0-15), D = data. Clobbers A,B,C.
;   DI/EI bracket the transaction so the firmware ISR cannot retarget the
;   PSG register select mid-write. Port C low nibble stays 0 (the
;   keyboard decoder line rbt_kbd_scan also leaves selected).
; ----------------------------------------------------------------------------
rbt_psg:
        di
        ld      bc,#f782        ; PPI control: port A = output. The firmware
        out     (c),c           ; keyboard scanner leaves port A in input mode
                                ; after its ISR pass, which would silently drop
                                ; every write below until something re-outputs it.
        ld      b,#f4
        out     (c),e           ; PPI port A = register number
        ld      bc,#f6c0
        out     (c),c           ; PSG op: latch register
        ld      bc,#f600
        out     (c),c           ; PSG op: inactive
        ld      b,#f4
        out     (c),d           ; PPI port A = data
        ld      bc,#f680
        out     (c),c           ; PSG op: write data
        ld      bc,#f600
        out     (c),c           ; inactive
        ei
        ret

; ----------------------------------------------------------------------------
; data
; ----------------------------------------------------------------------------
        if      RBT_CART
rbt_rmr         defb #89        ; RMR shadow: upper ROM off, lower ROM (cart
                                ; page) on, mode 1 — RMR writes must preserve
                                ; LR=0 or this code vanishes mid-execution
        endif
rbt_seed        defw #ace1
rbt_dataptr     defw 0          ; READ pointer (set to rbd_data by compiler)
rbt_col         defb 0          ; PRINT cursor column (charset)
rbt_row         defb 0          ; PRINT cursor row (charset)
rbt_over        defb 0          ; written by OVER stmt (unused on CPC yet)
rbt_attr        defb #38        ; current attr byte (charset INK/PAPER state)
''',
    'input': r'''
; ============================================================================
; rbt_input_asm - keyboard matrix + joystick input (Amstrad CPC)
;
; The keyboard is a 10x8 matrix scanned through the AY-3-8912's I/O port
; (register 14) via the 8255 PPI. Key codes use the same encoding as the
; Spectrum runtime (code = line*8 + bit) but CPC line/bit positions:
;   lines 0-9, bit 0..7 of the line byte; bit = 0 means pressed.
; Matrix line 9 = joystick 0 (bits: 0=up 1=down 2=left 3=right 4=fire2 5=fire1).
; ============================================================================

; ----------------------------------------------------------------------------
; rbt_kbd_scan - read one matrix line.
;   In:  A = line (0-9)
;   Out: A = column bits (0 = pressed)
;   Clobbers B, C, E. DI/EI bracket the PSG transaction so the firmware ISR
;   cannot retarget register 14 mid-read.
; ----------------------------------------------------------------------------
rbt_kbd_scan:
        di
        ld      e,a             ; E = matrix line
        ld      bc,#f40e        ; write PSG reg number 14 to PPI port A
        out     (c),c
        ld      bc,#f6c0        ; PSG operation: latch register
        out     (c),c
        ld      bc,#f600        ; PSG operation: inactive
        out     (c),c
        ld      bc,#f792        ; PPI control: port A = input
        out     (c),c
        ld      a,e
        or      #40             ; port C: PSG read op (01) | matrix line
        ld      bc,#f600
        out     (c),a
        ld      b,#f4           ; read PPI port A = matrix column bits
        in      a,(c)
        push    af
        xor     a
        ld      bc,#f600        ; port C = 0: PSG inactive, decoder line 0
        out     (c),a
        ld      bc,#f782        ; restore PPI port A = output
        out     (c),c
        pop     af
        ei
        ret

; ----------------------------------------------------------------------------
; ZX key code (Spectrum row*8+bit) -> CPC matrix code (line*8+bit), #ff = no
; CPC equivalent. Keeps KEY(n) source-portable: same number, same key.
; ----------------------------------------------------------------------------
rbt_zx2cpckey:
        defb    21,71,63,62,55,#ff,#ff,#ff  ; row0: SHIFT Z X C V
        defb    69,60,61,53,52,#ff,#ff,#ff  ; row1: A S D F G
        defb    67,59,58,50,51,#ff,#ff,#ff  ; row2: Q W E R T
        defb    64,65,57,56,49,#ff,#ff,#ff  ; row3: 1 2 3 4 5
        defb    32,33,40,41,48,#ff,#ff,#ff  ; row4: 0 9 8 7 6
        defb    27,34,35,42,43,#ff,#ff,#ff  ; row5: P O I U Y
        defb    18,36,37,45,44,#ff,#ff,#ff  ; row6: ENTER L K J H
        defb    47,23,38,46,54,#ff,#ff,#ff  ; row7: SPACE SYM(ctrl) M N B

; ----------------------------------------------------------------------------
; rbt_key - test one key. In: A = ZX code (row<<3 | bit). Out: A=1, 0 not.
; ----------------------------------------------------------------------------
rbt_key:
        and     #3f
        ld      e,a
        ld      d,0
        ld      hl,rbt_zx2cpckey
        add     hl,de
        ld      a,(hl)          ; CPC line*8+bit, or #ff
        inc     a
        ret     z               ; unmapped -> never pressed
        dec     a
        ld      e,a             ; E = code
        and     7
        ld      b,a             ; B = bit index (scanline clobbers E)
        push    bc
        ld      a,e
        rrca
        rrca
        rrca
        and     #0f             ; A = line (0-9)
        call    rbt_kbd_scan
        pop     bc
        inc     b
_sh     rra                     ; shift bit B into carry
        djnz    _sh
        ld      a,0
        ret     c               ; bit was 1 -> not pressed
        inc     a
        ret

        if      RBT_CART
; ----------------------------------------------------------------------------
; rbt_inkey (cart) - scan the matrix directly and map to ASCII. There is no
; firmware key buffer: returns the first pressed key found, or 0. Shift
; (line 2 bit 5) selects the shifted table.
; ----------------------------------------------------------------------------
rbt_inkey:
        ld      c,0             ; C = matrix line
_il     ld      a,c
        push    bc
        call    rbt_kbd_scan
        pop     bc
        cp      #ff
        jr      nz,_ibits       ; something held on this line
        inc     c
        ld      a,c
        cp      10
        jr      c,_il
        xor     a
        ret
_ibits  ld      e,#ff           ; first 0 bit = first pressed key
_ibl    inc     e
        rra
        jr      c,_ibl          ; bit 1 = not pressed -> next bit
        ld      a,c             ; index = line*8 + bit
        add     a,a
        add     a,a
        add     a,a
        or      e
        push    af
        ld      a,2
        call    rbt_kbd_scan    ; shift held? line 2 bit 5
        bit     5,a
        pop     af
        ld      hl,rbt_kbdasc
        jr      nz,_ilut        ; shift up -> unshifted table
        ld      hl,rbt_kbdasc_sh
_ilut   ld      d,0
        ld      e,a
        add     hl,de
        ld      a,(hl)
        ret

; ----------------------------------------------------------------------------
; CPC matrix -> ASCII, index = line*8+bit (bit 0 first). 0 = non-printing
; key. Cursor keys, function keys, joystick and control keys report 0;
; CPC-specific keys follow the firmware's usual ASCII where one exists
; (Return/Enter 13, Clr 12, Esc 27, Tab 9, Del 127).
; ----------------------------------------------------------------------------
rbt_kbdasc:
        defb    0,0,0,0,0,0,13,0        ; L0: up right dn f9 f6 f3 ent f.
        defb    0,0,0,0,0,0,0,0         ; L1: left copy f7 f8 f5 f1 f2 f0
        defb    12,91,13,93,0,0,92,0    ; L2: clr [ ret ] f4 shft \ ctrl
        defb    94,45,64,112,59,58,47,46  ; L3: ^ - @ P ; : / .
        defb    48,57,111,105,108,107,109,44 ; L4: 0 9 O I L K M ,
        defb    56,55,117,121,104,106,110,32 ; L5: 8 7 U Y H J N spc
        defb    54,53,114,116,103,102,98,118 ; L6: 6 5 R T G F B V
        defb    52,51,101,119,115,100,99,120 ; L7: 4 3 E W S D C X
        defb    49,50,27,113,9,97,0,122  ; L8: 1 2 esc Q tab A cap Z
        defb    0,0,0,0,0,0,0,127       ; L9: joy0, -, del

rbt_kbdasc_sh:                          ; same matrix, shift held
        defb    0,0,0,0,0,0,13,0        ; L0
        defb    0,0,0,0,0,0,0,0         ; L1
        defb    12,123,13,125,0,0,124,0 ; L2: [ ] \ -> { } |
        defb    96,61,124,80,43,42,63,62  ; L3: ^ - @ P ; : / . -> ` = | P + * ? >
        defb    95,41,79,73,76,75,77,60 ; L4: 0 9 , -> _ ) <
        defb    40,39,85,89,72,74,78,32 ; L5: 8 7 -> ( '
        defb    38,37,82,84,71,70,66,86 ; L6: 6 5 -> & %
        defb    36,35,69,87,83,68,67,88 ; L7: 4 3 -> $ #
        defb    33,34,27,81,9,65,0,90   ; L8: 1 2 -> ! "
        defb    0,0,0,0,0,0,0,127       ; L9
        else
; ----------------------------------------------------------------------------
; rbt_inkey - return ASCII of next buffered key (or 0). Uses the firmware
; key buffer filled by the ROM ISR (rbt_start leaves EI on).
; ----------------------------------------------------------------------------
rbt_inkey:
        call    FW_KM_READ_CHAR           ; KM READ CHAR -> carry set: A = char
        ret     c
        xor     a
        ret
        endif

; ----------------------------------------------------------------------------
; rbt_joy - read joystick 0 (matrix line 9).
;   Out: A = bitmask %000FUDLR (fire,up,down,left,right) - same shape as ZX.
;   CPC bits: 5=fire1 4=fire2 3=right 2=left 1=down 0=up (pressed = 0).
;   Fire 1 and fire 2 both count as fire.
; ----------------------------------------------------------------------------
rbt_joymode     defb 0          ; written by JOYSTICK stmt; ignored on CPC

rbt_joy:
        ld      a,9
        call    rbt_kbd_scan
        cpl                     ; now 1 = pressed
        ld      b,a
        and     #30             ; either fire bit -> result bit 4
        jr      z,_nofire
        ld      a,16
        jr      _fired
_nofire xor     a
_fired  ld      c,a
        ld      a,b
        and     8               ; right -> bit 0
        rra
        rra
        rra
        or      c
        ld      c,a
        ld      a,b
        and     4               ; left -> bit 1
        rra
        or      c
        ld      c,a
        ld      a,b
        and     2               ; down -> bit 2
        add     a,a
        or      c
        ld      c,a
        ld      a,b
        and     1               ; up -> bit 3
        add     a,a
        add     a,a
        add     a,a
        or      c
        ret
''',
    'pixel': r'''
; ============================================================================
; rbt_pixel_asm - CPC screen primitives (mode 1 assumed: 320x200, 2bpp)
;
; The Rainbow logical screen is 256x192 at the top-left of the CPC screen.
; The base is RBT_SCRB - #C000 on both: on cpc6128 #4000-#7FFF is
; the bank window (the compiler emits the equ). CPC mode-1 layout:
; 4 pixels per byte, pixel k of a byte holds its 2-bit pen at positions
; (7-k) hi and (3-k) lo. Lines are interleaved:
;   addr = RBT_SCRB + (y & 7) * #800 + (y >> 3) * 80 + xbyte
; resolved via the 192-entry line table below.
;
; Pen convention for the port layer:
;   pen 0 = PAPER colour, pen 1 = INK colour (text, sprites, tiles)
;   pens 2,3 are free for future multicolour sprite work.
; Sprite/tile/font data expand 1bpp -> pen1/paper0, for which the nibble
; bits land directly at positions 3..0 (expansion is free).
; ============================================================================

; ----------------------------------------------------------------------------
; rbt_laddr - B = byte column (0..63), C = line (0..191) -> HL = screen addr.
; Uses A, DE, HL. Line 0 = RBT_SCRB.
;
; When hardware scrolling is active (rbt_scr_son) and the line's char row is
; above the band split, the address anchors to the LOGICAL position: the
; 2048-byte band holding the line is a circular buffer indexed by
;   off = (soff + charrow*80 + bytecol) & 2047
; so screen byte (col,row) maps to the tape position the CRTC displays there.
; off is also stored in rbt_scr_woff for the band-wrap checks in the sprite
; copy loops; rbt_scr_wnat marks lines that stayed natural (band rows).
; ----------------------------------------------------------------------------
rbt_laddr:
        ld      a,(rbt_scr_son)
        or      a
        jr      z,rbt_laddrn
        ld      a,(rbt_scr_split)
        or      a
        jr      z,_lscr         ; no band -> every row scrolls
        ld      d,a
        ld      a,c
        rrca
        rrca
        rrca
        and     #1f             ; char row = line/8
        cp      d
        jr      c,_lscr         ; scrolled region
        ld      a,1
        ld      (rbt_scr_wnat),a ; band row: natural addressing
        jr      rbt_laddrn
_lscr   xor     a
        ld      (rbt_scr_wnat),a
        ; off = (soff + charrow*80 + B) & #7ff
        ld      a,c
        rrca
        rrca
        rrca
        and     #1f
        add     a,a
        ld      e,a
        ld      d,0
        ld      hl,rbt_scr_r80
        add     hl,de
        ld      e,(hl)
        inc     hl
        ld      d,(hl)          ; DE = charrow*80
        ld      hl,(rbt_scr_soff)
        add     hl,de
        ld      e,b
        ld      d,0
        add     hl,de           ; + byte col
        ld      a,h
        and     #07
        ld      h,a             ; mod 2048
        ld      (rbt_scr_woff),hl ; band offset for the copy loops' wrap check
        push    hl
        ld      a,c
        and     7
        add     a,a
        ld      e,a
        ld      d,0
        ld      hl,rbt_scr_lines
        add     hl,de           ; entries 0-7 are the band bases
        ld      a,(hl)
        inc     hl
        ld      h,(hl)
        ld      l,a             ; HL = band base for line&7
        pop     de
        add     hl,de           ; + off
        ret
rbt_laddrn:                     ; natural-layout address (ignores scroll)
        ld      a,b             ; column -> scratch (returned via HL add)
        ld      l,c
        ld      h,0
        add     hl,hl
        ld      de,rbt_scr_lines
        add     hl,de
        ld      e,(hl)
        inc     hl
        ld      d,(hl)
        ex      de,hl           ; HL = line base
        ld      e,a
        ld      d,0
        add     hl,de           ; + column
        ret

; char row * 80 lookup for the scrolled address path (25 rows, row*80)
rbt_scr_r80:    defw 0,80,160,240,320,400,480,560,640,720,800,880,960
                defw 1040,1120,1200,1280,1360,1440,1520,1600,1680,1760,1840,1920

; ----------------------------------------------------------------------------
; rbt_wsplit - split a dst byte run at the circular band's 2048-byte
; boundary. In: B = byte count, HL = dst (fresh from rbt_laddr so
; rbt_scr_woff/rbt_scr_wnat describe this row). Out: B = first-run count,
; rbt_scr_w2 = second-run count (0 = no wrap). Callers wrap HL themselves
; after the first run: HL -= #800 lands on this band's base (even when the
; band end crossed #ffff). Preserves DE,HL.
; ----------------------------------------------------------------------------
rbt_wsplit:
        xor     a
        ld      (rbt_scr_w2),a
        ld      a,(rbt_scr_son)
        or      a
        ret     z               ; not scrolling -> single run
        ld      a,(rbt_scr_wnat)
        or      a
        ret     nz              ; band row (natural) -> single run
        push    hl
        push    de
        ld      hl,(rbt_scr_woff)
        ld      de,#0800
        ex      de,hl           ; HL = 2048, DE = band offset
        or      a
        sbc     hl,de           ; HL = bytes to the band end (1..2048)
        ld      a,h
        or      a
        jr      nz,_wok         ; >= 256: whole run fits
        ld      a,l
        cp      b
        jr      nc,_wok         ; run ends before the band edge
        ld      e,a             ; E = first run = bytes to the edge
        ld      a,b
        sub     e
        ld      (rbt_scr_w2),a  ; second run = remainder
        ld      b,e
_wok    pop     de
        pop     hl
        ret

rbt_scr_w2      defb 0          ; band-wrap second-run count

; ----------------------------------------------------------------------------
; rbt_plot - C = pixel x (0..255), B = line y (0..191): plot a pen-1 pixel.
; ----------------------------------------------------------------------------
rbt_plot:
        ld      a,c
        and     3
        ld      e,a             ; E = pixel-in-byte
        ld      a,c
        rrca
        rrca
        and     #3f             ; byte col
        ld      d,a
        ld      c,b             ; C = line
        ld      b,d             ; B = col
        push    de              ; laddr clobbers DE
        call    rbt_laddr
        pop     de
        ; pen-1 bit for pixel k sits at position 3-k: mask = #08 >> k
        ld      a,#08
        ld      b,e
        or      b
        jr      z,_plw
        ld      b,e
_plsh   srl     a
        djnz    _plsh
_plw    or      (hl)
        ld      (hl),a
        ret

; ----------------------------------------------------------------------------
; rbt_point - C = x, B = y -> A = 1 if the pixel is non-paper, else 0
; ----------------------------------------------------------------------------
rbt_point:
        ld      a,c
        and     3
        ld      e,a
        ld      a,c
        rrca
        rrca
        and     #3f
        ld      d,a
        ld      c,b
        ld      b,d
        push    de
        call    rbt_laddr
        pop     de
        ; both pen bits of pixel k: #88 >> k
        ld      a,#88
        ld      b,e
        or      b
        jr      z,_ptt
        ld      b,e
_ptsh   srl     a
        djnz    _ptsh
_ptt    and     (hl)
        ret     z
        ld      a,1
        ret

; ----------------------------------------------------------------------------
; rbt_scrfill - fill a byte-rect with A.
;   B = byte col, C = start line, D = byte count, E = line count.
; ----------------------------------------------------------------------------
rbt_scrfill:
        ld      (rbt_sf_bv),a
        ld      a,e
        ld      (rbt_sf_lc),a
        ld      a,d
        ld      (rbt_sf_bw),a
_sfrow  call    rbt_laddr       ; HL = row base (B=col, C=line)
        push    bc
        ld      a,(rbt_sf_bw)
        ld      b,a
        call    rbt_wsplit      ; split at the band edge when scrolling
        ld      a,b
        pop     bc
        ld      e,a
        ld      a,(rbt_sf_bv)
_sfb    ld      (hl),a
        inc     hl
        dec     e
        jr      nz,_sfb
        ld      a,(rbt_scr_w2)
        or      a
        jr      z,_sfd
        ld      e,a
        ld      a,h
        sub     8
        ld      h,a             ; wrapped -> band base
        ld      a,(rbt_sf_bv)
_sfb2   ld      (hl),a
        inc     hl
        dec     e
        jr      nz,_sfb2
_sfd    inc     c
        ld      a,(rbt_sf_lc)
        dec     a
        ld      (rbt_sf_lc),a
        jr      nz,_sfrow
        ret

rbt_sf_bv       defb 0
rbt_sf_lc       defb 0
rbt_sf_bw       defb 0

; ----------------------------------------------------------------------------
; rbt_tile8 - draw an 8x8 1bpp tile/glyph, pen1 ink on pen0 paper.
;   DE = src (8 bytes), B = cell x (0..31), C = cell y (0..23)
; Each src byte expands to two pen-1 nibbles: hi nibble -> byte0, lo -> byte1.
; ----------------------------------------------------------------------------
rbt_tile8:
        ld      a,b
        add     a,a             ; byte col = cell*2
        ld      b,a
        ld      a,c
        add     a,a
        add     a,a
        add     a,a             ; line = cell*8
        ld      c,a
        ld      a,8
        ld      (rbt_t8_cnt),a
_t8l    push    de              ; laddr clobbers DE (src ptr)
        call    rbt_laddr       ; HL = line base + col; BC kept
        pop     de
        ld      a,(de)          ; 8 src pixels -> two pen-1 nibbles
        inc     de
        push    de
        ld      e,a
        rrca
        rrca
        rrca
        rrca
        and     #0f             ; hi nibble = px0..3
        ld      (hl),a
        inc     hl
        ld      a,e
        and     #0f             ; lo nibble = px4..7
        ld      (hl),a
        pop     de
        inc     c               ; next line
        ld      a,(rbt_t8_cnt)
        dec     a
        ld      (rbt_t8_cnt),a
        jr      nz,_t8l
        ret

rbt_t8_cnt      defb 0

; ----------------------------------------------------------------------------
; rbt_showpic - HL = CPC-encoded .rbc (192 lines x 64 bytes, y-linear,
; pen1/pen0 expanded). Copies each line into the interleaved screen.
; ----------------------------------------------------------------------------
rbt_showpic:
        xor     a
        ld      (rbt_sp_ln0),a  ; line
_spr    ld      a,(rbt_sp_ln0)
        cp      192
        ret     nc
        ld      c,a
        ld      b,0
        push    hl              ; src
        call    rbt_laddrn      ; loading screens fill the natural layout
        ex      de,hl           ; DE = dst
        pop     hl              ; HL = src
        ld      bc,64
        ldir
        ld      a,(rbt_sp_ln0)
        inc     a
        ld      (rbt_sp_ln0),a
        jr      _spr

rbt_sp_ln0      defb 0

; ----------------------------------------------------------------------------
; Line base addresses for pixel lines 0..191 - RBT_SCRB + the mode-1
; interleave offset.
; ----------------------------------------------------------------------------
rbt_scr_lines:
        defw RBT_SCRB+#0000,RBT_SCRB+#0800,RBT_SCRB+#1000,RBT_SCRB+#1800,RBT_SCRB+#2000,RBT_SCRB+#2800,RBT_SCRB+#3000,RBT_SCRB+#3800
        defw RBT_SCRB+#0050,RBT_SCRB+#0850,RBT_SCRB+#1050,RBT_SCRB+#1850,RBT_SCRB+#2050,RBT_SCRB+#2850,RBT_SCRB+#3050,RBT_SCRB+#3850
        defw RBT_SCRB+#00a0,RBT_SCRB+#08a0,RBT_SCRB+#10a0,RBT_SCRB+#18a0,RBT_SCRB+#20a0,RBT_SCRB+#28a0,RBT_SCRB+#30a0,RBT_SCRB+#38a0
        defw RBT_SCRB+#00f0,RBT_SCRB+#08f0,RBT_SCRB+#10f0,RBT_SCRB+#18f0,RBT_SCRB+#20f0,RBT_SCRB+#28f0,RBT_SCRB+#30f0,RBT_SCRB+#38f0
        defw RBT_SCRB+#0140,RBT_SCRB+#0940,RBT_SCRB+#1140,RBT_SCRB+#1940,RBT_SCRB+#2140,RBT_SCRB+#2940,RBT_SCRB+#3140,RBT_SCRB+#3940
        defw RBT_SCRB+#0190,RBT_SCRB+#0990,RBT_SCRB+#1190,RBT_SCRB+#1990,RBT_SCRB+#2190,RBT_SCRB+#2990,RBT_SCRB+#3190,RBT_SCRB+#3990
        defw RBT_SCRB+#01e0,RBT_SCRB+#09e0,RBT_SCRB+#11e0,RBT_SCRB+#19e0,RBT_SCRB+#21e0,RBT_SCRB+#29e0,RBT_SCRB+#31e0,RBT_SCRB+#39e0
        defw RBT_SCRB+#0230,RBT_SCRB+#0a30,RBT_SCRB+#1230,RBT_SCRB+#1a30,RBT_SCRB+#2230,RBT_SCRB+#2a30,RBT_SCRB+#3230,RBT_SCRB+#3a30
        defw RBT_SCRB+#0280,RBT_SCRB+#0a80,RBT_SCRB+#1280,RBT_SCRB+#1a80,RBT_SCRB+#2280,RBT_SCRB+#2a80,RBT_SCRB+#3280,RBT_SCRB+#3a80
        defw RBT_SCRB+#02d0,RBT_SCRB+#0ad0,RBT_SCRB+#12d0,RBT_SCRB+#1ad0,RBT_SCRB+#22d0,RBT_SCRB+#2ad0,RBT_SCRB+#32d0,RBT_SCRB+#3ad0
        defw RBT_SCRB+#0320,RBT_SCRB+#0b20,RBT_SCRB+#1320,RBT_SCRB+#1b20,RBT_SCRB+#2320,RBT_SCRB+#2b20,RBT_SCRB+#3320,RBT_SCRB+#3b20
        defw RBT_SCRB+#0370,RBT_SCRB+#0b70,RBT_SCRB+#1370,RBT_SCRB+#1b70,RBT_SCRB+#2370,RBT_SCRB+#2b70,RBT_SCRB+#3370,RBT_SCRB+#3b70
        defw RBT_SCRB+#03c0,RBT_SCRB+#0bc0,RBT_SCRB+#13c0,RBT_SCRB+#1bc0,RBT_SCRB+#23c0,RBT_SCRB+#2bc0,RBT_SCRB+#33c0,RBT_SCRB+#3bc0
        defw RBT_SCRB+#0410,RBT_SCRB+#0c10,RBT_SCRB+#1410,RBT_SCRB+#1c10,RBT_SCRB+#2410,RBT_SCRB+#2c10,RBT_SCRB+#3410,RBT_SCRB+#3c10
        defw RBT_SCRB+#0460,RBT_SCRB+#0c60,RBT_SCRB+#1460,RBT_SCRB+#1c60,RBT_SCRB+#2460,RBT_SCRB+#2c60,RBT_SCRB+#3460,RBT_SCRB+#3c60
        defw RBT_SCRB+#04b0,RBT_SCRB+#0cb0,RBT_SCRB+#14b0,RBT_SCRB+#1cb0,RBT_SCRB+#24b0,RBT_SCRB+#2cb0,RBT_SCRB+#34b0,RBT_SCRB+#3cb0
        defw RBT_SCRB+#0500,RBT_SCRB+#0d00,RBT_SCRB+#1500,RBT_SCRB+#1d00,RBT_SCRB+#2500,RBT_SCRB+#2d00,RBT_SCRB+#3500,RBT_SCRB+#3d00
        defw RBT_SCRB+#0550,RBT_SCRB+#0d50,RBT_SCRB+#1550,RBT_SCRB+#1d50,RBT_SCRB+#2550,RBT_SCRB+#2d50,RBT_SCRB+#3550,RBT_SCRB+#3d50
        defw RBT_SCRB+#05a0,RBT_SCRB+#0da0,RBT_SCRB+#15a0,RBT_SCRB+#1da0,RBT_SCRB+#25a0,RBT_SCRB+#2da0,RBT_SCRB+#35a0,RBT_SCRB+#3da0
        defw RBT_SCRB+#05f0,RBT_SCRB+#0df0,RBT_SCRB+#15f0,RBT_SCRB+#1df0,RBT_SCRB+#25f0,RBT_SCRB+#2df0,RBT_SCRB+#35f0,RBT_SCRB+#3df0
        defw RBT_SCRB+#0640,RBT_SCRB+#0e40,RBT_SCRB+#1640,RBT_SCRB+#1e40,RBT_SCRB+#2640,RBT_SCRB+#2e40,RBT_SCRB+#3640,RBT_SCRB+#3e40
        defw RBT_SCRB+#0690,RBT_SCRB+#0e90,RBT_SCRB+#1690,RBT_SCRB+#1e90,RBT_SCRB+#2690,RBT_SCRB+#2e90,RBT_SCRB+#3690,RBT_SCRB+#3e90
        defw RBT_SCRB+#06e0,RBT_SCRB+#0ee0,RBT_SCRB+#16e0,RBT_SCRB+#1ee0,RBT_SCRB+#26e0,RBT_SCRB+#2ee0,RBT_SCRB+#36e0,RBT_SCRB+#3ee0
        defw RBT_SCRB+#0730,RBT_SCRB+#0f30,RBT_SCRB+#1730,RBT_SCRB+#1f30,RBT_SCRB+#2730,RBT_SCRB+#2f30,RBT_SCRB+#3730,RBT_SCRB+#3f30
''',
    'sfx': r'''
; ============================================================================
; rbt_sfx_asm - Rainbow sound effects via the AY (Amstrad CPC)
;
; Same queue/drain model as the ZX beeper engine: SFX queues an effect,
; the next idle point (vsync/pause/waitkey/end/sprite update) drains and
; plays it blocking — effects land in dead frame time. Instead of toggling
; a speaker the CPC player drives AY channel C: it "steals" the music
; channel's voice (the next .ray row reasserts the channel), or programs
; the mixer itself when no music is running.
;
; rbt_sfx       - queue an effect: HL = step data, A ignored (no banks)
; rbt_sfx_drain - play the pending effect now if one is queued
; rbt_sfx_play  - blocking player: HL = step data
;
; CPC-encoded .rsf step format (6 bytes):
;   defb len          ; update iterations (0 = end of effect)
;   defb dur          ; delay units between updates (~13T each)
;   defw period       ; AY tone period for channel C
;   defw slide        ; signed delta added to period each iteration
; ============================================================================

rbt_sfx:
        push    hl
        push    af
        call    rbt_sfx_drain         ; flush a queued effect first (ordering)
        pop     af
        pop     hl
        ld      (rbt_sfx_pbank),a     ; bank the effect data lives in (#ff = resident)
        ld      (rbt_sfx_pending),hl
        ret

rbt_sfx_drain:
        ld      hl,(rbt_sfx_pending)
        ld      a,h
        or      l
        ret     z
        push    hl                    ; step ptr
        xor     a
        ld      (rbt_sfx_pending),a
        ld      (rbt_sfx_pending+1),a
        ld      a,(rbt_sfx_pbank)
        ld      hl,rbt_sfx_pprev
        call    rbt_pg_in             ; no-op when resident (#ff) or no bank module
        pop     hl
        call    rbt_sfx_play
        ld      hl,rbt_sfx_pprev
        jp      rbt_pg_out            ; restore mapping (ret)

rbt_sfx_play:
        ld      e,10                  ; channel C volume
        ld      d,12
        call    rbt_psg
        ld      a,(rbt_ay_on)
        or      a
        jr      z,_mix0
        ; music owns the mixer: steal its C voice - force tone C on and
        ; noise C off, keeping the music's A/B channel bits (songs that
        ; use C for drums/noise would otherwise gate noise instead of
        ; the swept tone).
        ld      a,(rbt_ay_r7)
        and     #fb                   ; bit2 = 0: tone C enabled
        or      #20                   ; bit5 = 1: noise C disabled
        ld      d,a
        ld      e,7
        call    rbt_psg
        jr      _step
_mix0   ld      e,7                   ; no music: tone C on, rest off
        ld      d,#3b                 ; bits 0,1,3,4,5 set: C tone only
        call    rbt_psg
_step   ld      a,(hl)                ; len
        or      a
        jp      z,_done
        ld      (rbt_sfx_len),a
        inc     hl
        ld      a,(hl)                ; dur units
        inc     hl
        ld      (rbt_sfx_dur),a
        ld      a,(hl)                ; period lo
        inc     hl
        ld      (rbt_sfx_per),a
        ld      a,(hl)                ; period hi
        inc     hl
        ld      (rbt_sfx_per+1),a
        ld      a,(hl)                ; slide lo
        inc     hl
        ld      (rbt_sfx_sl),a
        ld      a,(hl)                ; slide hi
        inc     hl
        ld      (rbt_sfx_sl+1),a
        push    hl                    ; next-step pointer (HL = step+6)
_iter   ; write channel C period (regs 4,5); data is q8 -> shift >>3
        ld      a,(rbt_sfx_per)
        ld      l,a
        ld      a,(rbt_sfx_per+1)
        ld      h,a
        srl     h
        rr      l
        srl     h
        rr      l
        srl     h
        rr      l               ; HL = period
        ld      d,l
        ld      e,4
        call    rbt_psg
        ld      a,(rbt_sfx_per)
        ld      l,a
        ld      a,(rbt_sfx_per+1)
        ld      h,a
        srl     h
        rr      l
        srl     h
        rr      l
        srl     h
        rr      l
        ld      a,h
        and     #0f
        ld      d,a
        ld      e,5
        call    rbt_psg
        ; delay: dur x ~13T loop (encoder scales units for 4 MHz)
        ld      a,(rbt_sfx_dur)
        or      a
        jr      nz,_w
        inc     a
_w      ld      b,a
_wi     djnz    _wi
        ; period += slide (clamp at 0)
        ld      a,(rbt_sfx_per)
        ld      e,a
        ld      a,(rbt_sfx_per+1)
        ld      d,a
        ld      a,(rbt_sfx_sl)
        ld      l,a
        ld      a,(rbt_sfx_sl+1)
        ld      h,a
        add     hl,de
        bit     7,h
        jr      z,_pc
        ld      hl,0
_pc     ld      a,l
        ld      (rbt_sfx_per),a
        ld      a,h
        ld      (rbt_sfx_per+1),a
        ld      a,(rbt_sfx_len)
        dec     a
        ld      (rbt_sfx_len),a
        jr      nz,_iter
        pop     hl
        jp      _step
_done   ld      e,10                  ; channel C silent
        ld      d,0
        call    rbt_psg
        ret

rbt_sfx_pending defw    0             ; queued effect step ptr (0 = none)
rbt_sfx_pbank   defb    #ff           ; bank of the queued effect
rbt_sfx_pprev   defb    0             ; mapping save byte for the drain guard
rbt_sfx_len     defb    0
rbt_sfx_dur     defb    0
rbt_sfx_per     defw    0
rbt_sfx_sl      defw    0
''',
    'spcoll': r'''
; ============================================================================
; rbt_spcoll_asm - sprite <-> tilemap collision bridge (CPC).
; Requires BOTH the sprite module (rbt_slot) and the tilemap module
; (rbt_tm_* vars, rbt_tm_mapat, rbt_ct_* scratch).
; ============================================================================

; ----------------------------------------------------------------------------
; rbt_colltile - A = sprite id -> A = flags of first solid tile overlapped
; (0 = none). Requires the sprite module (uses rbt_sprites via rbt_slot).
; ----------------------------------------------------------------------------
rbt_colltile:
        call    rbt_slot        ; IX = slot
        ld      a,(ix+0)
        bit     0,a
        ret     z               ; inactive -> no collision
        ; cell range from pixel bbox
        ld      a,(ix+1)
        and     #f8
        rrca
        rrca
        rrca
        ld      (rbt_ct_c0),a   ; x>>3
        ld      a,(ix+3)        ; w in pixels on CPC
        dec     a
        add     a,(ix+1)        ; x+w-1
        and     #f8
        rrca
        rrca
        rrca
        ld      (rbt_ct_c1),a
        ld      a,(ix+2)
        and     #f8
        rrca
        rrca
        rrca
        ld      (rbt_ct_r0),a   ; y>>3
        ld      a,(ix+4)
        dec     a
        add     a,(ix+2)        ; y+h-1
        and     #f8
        rrca
        rrca
        rrca
        ld      (rbt_ct_r1),a
        ; loop rows r0..r1
        ld      a,(rbt_ct_r0)
        ld      (rbt_ct_r),a
_cr     ld      a,(rbt_ct_c0)
        ld      (rbt_ct_c),a
_cc     ; inside view?
        ld      a,(rbt_tm_vx)
        ld      b,a
        ld      a,(rbt_ct_c)
        cp      b
        jp      c,_cskip
        ld      a,(rbt_tm_vw)
        add     a,b
        ld      b,a
        ld      a,(rbt_ct_c)
        cp      b
        jp      nc,_cskip
        ld      a,(rbt_tm_vy)
        ld      b,a
        ld      a,(rbt_ct_r)
        cp      b
        jp      c,_cskip
        ld      a,(rbt_tm_vh)
        add     a,b
        ld      b,a
        ld      a,(rbt_ct_r)
        cp      b
        jp      nc,_cskip
        ; map coords
        ld      a,(rbt_ct_c)
        ld      b,a
        ld      a,(rbt_tm_vx)
        ld      c,a
        ld      a,b
        sub     c
        ld      b,a
        ld      a,(rbt_tm_camx)
        add     a,b
        ld      b,a             ; mx
        ld      a,(rbt_ct_r)
        ld      c,a
        ld      a,(rbt_tm_vy)
        ld      d,a
        ld      a,c
        sub     d
        ld      c,a
        ld      a,(rbt_tm_camy)
        add     a,c
        ld      c,a             ; my
        ; in map? (else treat as not solid)
        ld      a,(rbt_tm_mw)
        cp      b
        jp      c,_cskip
        jp      z,_cskip
        ld      a,(rbt_tm_mh)
        cp      c
        jp      c,_cskip
        jp      z,_cskip
        call    rbt_tm_mapat
        call    rbt_tileflags   ; A = flags
        bit     0,a
        ret     nz              ; solid -> return flags
_cskip  ld      a,(rbt_ct_c)
        inc     a
        ld      (rbt_ct_c),a
        ld      b,a
        ld      a,(rbt_ct_c1)
        cp      b
        jp      nc,_cc
        ld      a,(rbt_ct_r)
        inc     a
        ld      (rbt_ct_r),a
        ld      b,a
        ld      a,(rbt_ct_r1)
        cp      b
        jp      nc,_cr
        xor     a               ; none
        ret
''',
    'sprite': r'''
; ============================================================================
; rbt_sprite_asm - CPC masked sprite engine (mode 1 assumed)
;
; 16 slots x 18 bytes. Sprites are 1bpp source expanded at encode time to
; pen-1/pen-0 2bpp mask+bitmap pairs, pre-shifted for 4 pixel phases, so
; draw is a per-byte (screen & mask) | bmp merge - no runtime shifting.
;
; Erase model: MASK/OR sprites keep a saved copy of the background they
; cover (per-slot buffer, up to RBT_SPSAVE bytes; bigger rects draw
; without a save and then can't auto-erase). XOR sprites erase by
; redrawing. rbt_sp_place/frame only set state + dirty; rbt_sp_update
; commits dirty sprites (restore old rect, save + draw new). rbt_sp_draw
; (SPRITE REDRAW) commits one slot immediately.
;
; Slot layout:
;  +0  flags: bit0 active, bit1 hidden, bit2 dirty (pos/frame changed)
;  +1  x +2  y               (target position, pixels)
;  +3  wpx +4 h              (w in PIXELS, h lines)
;  +5  frame +6,7 asset ptr
;  +8  attr (stored, ignored) +9 mode (0 mask, 1 or, 2 xor)
;  +10 animFirst +11 animLast
;  +12 animFlags: bit0 pingpong, bit1 animating
;  +13 animDir (1 / -1)
;  +14 asset bank (#ff = resident; cpc6128 pages it per access)
;  +15 committed: 0 = nothing on screen, 1 = drawn at +16/+17
;  +16 cx +17 cy             (committed position)
;
; CPC sprite asset (.rbs encoded for cpc):
;   defb wpx, h, nframes, attr
;   defw nframes*4           ; offs[phase*nframes + frame], from asset start
;   blocks: h rows x (wpx/4+1) cols of {mask,bmp} pen-1 expanded pairs
; ============================================================================

RBT_NSLOTS      equ 16
RBT_SLOT        equ 18
RBT_SPSAVE      equ 160         ; save-buffer bytes per slot (max covered rect)

rbt_sprites     defs RBT_NSLOTS*RBT_SLOT
rbt_spsave      defs RBT_NSLOTS*RBT_SPSAVE

; ----------------------------------------------------------------------------
; rbt_slot - A = sprite id -> IX = slot address. Preserves BC,DE,HL.
; ----------------------------------------------------------------------------
rbt_slot:
        and     RBT_NSLOTS-1
        push    de
        ld      e,a
        add     a,a
        add     a,a
        add     a,a
        add     a,a             ; id*16
        add     a,e
        add     a,e             ; id*18 (id=15 -> 270: carry!)
        ld      e,a
        ld      d,0
        jr      nc,_nc
        inc     d               ; keep id*18 in 16 bits or slot 15
_nc     ld      ix,rbt_sprites  ; lands on slot0+14 and stomps it
        add     ix,de
        pop     de
        ret

; ----------------------------------------------------------------------------
; rbt_sp_savebuf - IX = slot -> HL = its save buffer. Uses A,DE,HL.
; ----------------------------------------------------------------------------
rbt_sp_savebuf:
        push    ix
        pop     de
        ld      hl,-rbt_sprites
        add     hl,de           ; HL = id*18 (0..270)
        ld      de,0
        ld      bc,18
_sbdv   or      a
        sbc     hl,bc
        jr      c,_sbd
        inc     e
        jr      _sbdv
_sbd    ; E = slot id -> HL = id*160
        ld      l,e
        ld      h,0
        add     hl,hl
        add     hl,hl
        add     hl,hl
        add     hl,hl
        add     hl,hl           ; *32
        ld      d,h
        ld      e,l             ; DE = id*32
        add     hl,hl
        add     hl,hl           ; *128
        add     hl,de           ; *160
        ld      de,rbt_spsave
        add     hl,de
        ret

; ----------------------------------------------------------------------------
; rbt_sp_create - A=id, HL=asset, B=mode(0/1/2), C=x, D=y, E=asset bank
; ----------------------------------------------------------------------------
rbt_sp_create:
        push    hl
        call    rbt_slot        ; preserves DE (E = bank)
        pop     hl
        ld      a,e
        ld      (ix+14),a       ; asset bank byte
        ld      (ix+6),l
        ld      (ix+7),h        ; asset ptr
        ld      (ix+0),1        ; active
        ld      (ix+1),c        ; x
        ld      (ix+2),d        ; y
        ld      a,(hl)
        ld      (ix+3),a        ; wpx
        inc     hl
        ld      a,(hl)
        ld      (ix+4),a        ; h
        inc     hl
        inc     hl              ; skip nframes
        ld      a,(hl)
        ld      (ix+8),a        ; attr (unused)
        xor     a
        ld      (ix+5),a        ; frame 0
        ld      (ix+9),b        ; mode
        ld      (ix+12),a       ; anim off
        ld      (ix+15),a       ; not committed
        ld      (ix+0),5        ; active + dirty -> first UPDATE draws it
        ret

; ----------------------------------------------------------------------------
; rbt_sp_place - A=id, B=x, C=y
; ----------------------------------------------------------------------------
rbt_sp_place:
        call    rbt_slot
        ld      (ix+1),b
        ld      (ix+2),c
        ld      a,(ix+0)
        or      4
        ld      (ix+0),a        ; dirty
        ret

; ----------------------------------------------------------------------------
; rbt_sp_move - A=id, B=dx (signed), C=dy (signed). Clamps to screen.
; ----------------------------------------------------------------------------
rbt_sp_move:
        call    rbt_slot
        ld      e,(ix+1)        ; old x
        ld      a,e
        add     a,b
        bit     7,b
        jr      nz,_mvxn
        jr      c,_mvxmax       ; wrapped past 255
        ld      d,a             ; D = new x
        ld      a,(ix+3)        ; wpx
        neg                     ; 256 - wpx = maxX
        cp      d
        jr      c,_mvxset       ; new > maxX -> store maxX (A)
        ld      a,d
        jr      _mvxset
_mvxmax ld      a,(ix+3)
        neg
        jr      _mvxset
_mvxn   cp      e
        jr      c,_mvxset       ; new < old: normal move
        xor     a
_mvxset ld      (ix+1),a
_mvy    ld      e,(ix+2)
        ld      a,e
        add     a,c
        bit     7,c
        jr      nz,_mvyn
        jr      c,_mvymax
        ld      d,a             ; D = new y
        ld      a,(ix+4)
        neg
        add     a,192-256       ; 192 - h
        cp      d
        jr      c,_mvyset
        ld      a,d
        jr      _mvyset
_mvymax ld      a,(ix+4)
        neg
        add     a,192-256
        jr      _mvyset
_mvyn   cp      e
        jr      c,_mvyset
        xor     a
_mvyset ld      (ix+2),a
        ld      a,(ix+0)
        or      4               ; dirty
        ld      (ix+0),a
        ret

; ----------------------------------------------------------------------------
; rbt_sp_frame - A=id, B=frame (clamped to nframes-1)
; ----------------------------------------------------------------------------
rbt_sp_frame:
        call    rbt_slot
        ld      a,(ix+14)       ; asset bank (#ff = resident)
        ld      hl,rbt_sp_prev
        call    rbt_pg_in       ; page sprite asset for the header read
        ld      l,(ix+6)
        ld      h,(ix+7)
        inc     hl
        inc     hl
        ld      a,(hl)          ; nframes
        dec     a
        cp      b
        jr      nc,_ok
        ld      b,a
_ok     ld      (ix+5),b
        ld      a,(ix+0)
        or      4
        ld      (ix+0),a
        ld      hl,rbt_sp_prev
        jp      rbt_pg_out

; ----------------------------------------------------------------------------
; rbt_sp_anim - A=id, B=first frame, C=last frame, D=0 loop / 1 pingpong
; ----------------------------------------------------------------------------
rbt_sp_anim:
        call    rbt_slot
        ld      (ix+10),b
        ld      (ix+11),c
        ld      (ix+5),b        ; frame = first
        ld      a,d
        and     1
        or      2               ; bit1 = animating
        ld      (ix+12),a
        ld      (ix+13),1
        ld      a,(ix+0)
        or      4
        ld      (ix+0),a
        ret

; ----------------------------------------------------------------------------
; rbt_sp_animstep - advance the animating frame of slot IX (loop/pingpong).
; ----------------------------------------------------------------------------
rbt_sp_animstep:
        ld      a,(ix+12)
        bit     1,a
        ret     z               ; not animating
        ld      a,(ix+13)
        bit     7,a
        jr      nz,_backw
        ; forward
        ld      a,(ix+5)
        inc     a
        cp      (ix+11)
        jr      c,_set
        jr      z,_set
        ; past last
        ld      a,(ix+12)
        bit     0,a
        jr      z,_loop         ; plain loop: back to first
        ld      a,#ff
        ld      (ix+13),a       ; pingpong: bounce back
        ld      a,(ix+11)
        dec     a
        jr      _set
_loop   ld      a,(ix+10)
        jr      _set
_backw  ld      a,(ix+5)
        dec     a
        cp      (ix+10)
        jr      nc,_set         ; >= first
        ld      a,1
        ld      (ix+13),a       ; bounce forward
        ld      a,(ix+10)
        inc     a
_set    ld      (ix+5),a
        ld      a,(ix+0)
        or      4               ; frame change -> dirty
        ld      (ix+0),a
        ret

; ----------------------------------------------------------------------------
; rbt_sp_show / rbt_sp_hide / rbt_sp_kill - A=id
; ----------------------------------------------------------------------------
rbt_sp_show:
        call    rbt_slot
        ld      a,(ix+0)
        and     #fd             ; clear hidden
        or      5               ; active + dirty -> redrawn
        ld      (ix+0),a
        ret
rbt_sp_hide:
        call    rbt_slot
        ld      a,(ix+0)
        or      6               ; hidden + dirty: the next commit/update
        ld      (ix+0),a        ; restores its rect in z-order (immediate
        ret                     ; restore could re-paste stale copies of
                                ; lower sprites it was saved over)
rbt_sp_kill:
        call    rbt_slot
        ld      (ix+0),4        ; inactive + dirty
        ret

; ----------------------------------------------------------------------------
; rbt_sp_attr - A=id, B=attr byte (stored, ignored on CPC)
; ----------------------------------------------------------------------------
rbt_sp_attr:
        call    rbt_slot
        ld      (ix+8),b
        ret

; ----------------------------------------------------------------------------
; rbt_spx / rbt_spy - A=id -> A = x / y
; ----------------------------------------------------------------------------
rbt_spx:
        call    rbt_slot
        ld      a,(ix+1)
        ret
rbt_spy:
        call    rbt_slot
        ld      a,(ix+2)
        ret

; ----------------------------------------------------------------------------
; rbt_sp_cols - IX slot -> A = nominal byte columns (wpx/4 + 1, covers p<=3).
; ----------------------------------------------------------------------------
rbt_sp_cols:
        ld      a,(ix+3)
        rrca
        rrca
        and     #3f
        inc     a
        ret

; rbt_sp_colsclip - nominal cols clipped to the 64-byte logical row from the
; byte col in rbt_sp_bc. -> A (1..cols)
; ----------------------------------------------------------------------------
rbt_sp_colsclip:
        push    hl              ; callers hold the screen ptr in HL here
        call    rbt_sp_cols
        ld      b,a
        ld      a,64
        ld      hl,rbt_sp_bc
        sub     (hl)            ; cols left in the row
        cp      b
        jr      nc,_ccr
        ld      b,a
_ccr    ld      a,b
        or      a
        jr      nz,_ccx
        inc     a
_ccx    pop     hl
        ret

; ----------------------------------------------------------------------------
; rbt_sp_srcptr - IX slot, B = draw x -> DE = asset phase/frame block,
; A = nominal cols. Phase comes from the DRAW x (committed and target
; positions can differ).
; ----------------------------------------------------------------------------
rbt_sp_srcptr:
        ld      l,(ix+6)
        ld      h,(ix+7)        ; HL = asset
        push    hl
        inc     hl
        inc     hl
        ld      a,(hl)          ; nframes
        ld      c,a
        ld      a,b
        and     3               ; phase p
        ld      b,a
        or      a
        jr      z,_p0
        ld      e,c             ; E = nframes
        xor     a
_pmul   add     a,e
        djnz    _pmul           ; A = p*nframes
_p0     add     a,(ix+5)        ; + frame
        add     a,a             ; *2 (u16 entries)
        ld      e,a
        ld      d,0
        pop     hl
        push    hl
        inc     hl
        inc     hl
        inc     hl
        inc     hl              ; HL = asset+4 (offset table)
        add     hl,de
        ld      e,(hl)
        inc     hl
        ld      d,(hl)          ; DE = block offset from asset
        pop     hl
        add     hl,de
        ex      de,hl           ; DE = block ptr
        call    rbt_sp_cols
        ret

; ----------------------------------------------------------------------------
; rbt_sp_rect - IX slot, B = x, C = y -> A = clipped cols, rbt_sp_rh = rows,
; rbt_sp_bc = byte col.
; ----------------------------------------------------------------------------
rbt_sp_rect:
        ld      a,b
        rrca
        rrca
        and     #3f
        ld      (rbt_sp_bc),a   ; byte col
        call    rbt_sp_colsclip    ; A = cols
        push    af
        ; rows = min(h, 192-y), 0 when y >= 192
        ld      a,c
        cp      192
        jr      c,_rc3
        xor     a
        jr      _rc4
_rc3    ld      d,a
        ld      a,192
        sub     d               ; lines left
        ld      d,a
        ld      a,(ix+4)
        cp      d
        jr      c,_rc4
        ld      a,d
_rc4    ld      (rbt_sp_rh),a
        pop     af
        ret

; ----------------------------------------------------------------------------
; rbt_sp_save - save the screen rect under the sprite's (x,y) into the slot
; buffer -> A = 1 saved, 0 skipped (too big / off screen: no auto-erase).
; ----------------------------------------------------------------------------
rbt_sp_save:
        ld      b,(ix+1)
        ld      c,(ix+2)
        call    rbt_sp_rect        ; A = cols, rbt_sp_rh = rows
        ld      b,a
        ld      a,(rbt_sp_rh)
        or      a
        jr      z,_skp
        ld      d,a             ; D = rows
        ld      a,b             ; A = cols
        call    rbt_sp_mul      ; DE = cols*rows
        ld      a,d
        or      a
        jr      nz,_skp         ; > 255: too big
        ld      a,e
        cp      RBT_SPSAVE+1
        jr      nc,_skp         ; > 160: too big
        ; row loop
        call    rbt_sp_savebuf  ; HL = save buf
        ex      de,hl           ; DE = save ptr
        ld      a,(rbt_sp_rh)
        ld      (rbt_sp_rc),a   ; rows left
        ld      a,(ix+1)
        rrca
        rrca
        and     #3f
        ld      (rbt_sp_bc),a   ; byte col
        ld      c,(ix+2)        ; C = line
_svr    ld      a,(rbt_sp_bc)
        ld      b,a
        push    de
        call    rbt_laddr
        pop     de
        call    rbt_sp_colsclip
        ld      b,a
        call    rbt_wsplit   ; split at the band edge when scrolling
_svcpy  ld      a,(hl)
        ld      (de),a
        inc     hl
        inc     de
        djnz    _svcpy
        ld      a,(rbt_scr_w2)
        or      a
        jr      z,_svd2
        ld      b,a
        ld      a,h
        sub     8
        ld      h,a             ; wrapped -> band base
_svc2   ld      a,(hl)
        ld      (de),a
        inc     hl
        inc     de
        djnz    _svc2
_svd2   inc     c
        ld      a,(rbt_sp_rc)
        dec     a
        ld      (rbt_sp_rc),a
        jr      nz,_svr
        ld      a,1
        ret
_skp    xor     a
        ret

; ----------------------------------------------------------------------------
; rbt_sp_restore - write the slot's save buffer back at its committed pos.
; ----------------------------------------------------------------------------
rbt_sp_restore:
        ld      a,(ix+16)
        rrca
        rrca
        and     #3f
        ld      (rbt_sp_bc),a   ; committed byte col
        ld      a,(ix+17)
        cp      192
        ret     nc
        ; rows = min(h, 192-cy)
        ld      c,a
        ld      a,192
        sub     c
        ld      d,a
        ld      a,(ix+4)
        cp      d
        jr      c,_rs1
        ld      a,d
_rs1    or      a
        ret     z
        ld      (rbt_sp_rc),a
        call    rbt_sp_savebuf
        ex      de,hl           ; DE = save ptr
        ld      c,(ix+17)
_rsr    ld      a,(rbt_sp_bc)
        ld      b,a
        push    de
        call    rbt_laddr
        pop     de
        call    rbt_sp_colsclip
        ld      b,a
        call    rbt_wsplit   ; split at the band edge when scrolling
_rscpy  ld      a,(de)
        ld      (hl),a
        inc     hl
        inc     de
        djnz    _rscpy
        ld      a,(rbt_scr_w2)
        or      a
        jr      z,_rsd2
        ld      b,a
        ld      a,h
        sub     8
        ld      h,a             ; wrapped -> band base
_rsc2   ld      a,(de)
        ld      (hl),a
        inc     hl
        inc     de
        djnz    _rsc2
_rsd2   inc     c
        ld      a,(rbt_sp_rc)
        dec     a
        ld      (rbt_sp_rc),a
        jr      nz,_rsr
        ret

; ----------------------------------------------------------------------------
; rbt_sp_eraseix - erase whatever slot IX has committed (internal + hide/kill)
; With a tilemap set (rbt_tm_on) the background is repainted from the map;
; otherwise the saved rect is restored (or the sprite redrawn for XOR).
; ----------------------------------------------------------------------------
rbt_sp_eraseix:
        ld      a,(ix+15)
        or      a
        ret     z
        ld      a,(rbt_tm_on)
        or      a
        jr      nz,_erm         ; tilemap active -> repaint cells
        ld      a,(ix+9)
        cp      2
        jr      z,_erx          ; xor: redraw to erase
        call    rbt_sp_restore
        xor     a
        ld      (ix+15),a
        ret
_erm    ; repaint the map cells under the committed rect
        ld      a,(ix+16)       ; cx
        and     #f8
        rrca
        rrca
        rrca
        ld      (rbt_sp_md),a   ; spare: x0 cell
        ld      a,(ix+3)
        dec     a
        add     a,(ix+16)       ; cx + w - 1
        and     #f8
        rrca
        rrca
        rrca                    ; x1 cell
        ld      b,a
        ld      a,(rbt_sp_md)
        ld      c,a
        ld      a,b
        sub     c
        inc     a
        ld      (rbt_sp_nc),a   ; cell width
        ld      a,(ix+17)       ; cy
        and     #f8
        rrca
        rrca
        rrca
        ld      (rbt_sp_md),a   ; y0 cell
        ld      a,(ix+4)
        dec     a
        add     a,(ix+17)       ; cy + h - 1
        and     #f8
        rrca
        rrca
        rrca                    ; y1 cell
        ld      b,a
        ld      a,(rbt_sp_md)
        ld      c,a
        ld      a,b
        sub     c
        inc     a
        ld      e,a             ; E = cell height
        ld      a,(rbt_sp_nc)
        ld      d,a             ; D = cell width
        ld      a,(rbt_sp_md)
        ld      c,a             ; C = y0 cell
        ld      a,(ix+16)
        and     #f8
        rrca
        rrca
        rrca
        ld      b,a             ; B = x0 cell
        push    ix
        call    rbt_tm_redraw
        pop     ix
        xor     a
        ld      (ix+15),a
        ret
_erx    ; draw XOR at committed pos
        push    ix
        ld      a,(ix+16)
        ld      b,a
        ld      a,(ix+17)
        ld      c,a
        call    rbt_sp_bli        ; uses B,C as draw pos
        pop     ix
        xor     a
        ld      (ix+15),a
        ret

; ----------------------------------------------------------------------------
; rbt_sp_bli - draw the sprite's frame at B=x, C=y using its mode.
; ----------------------------------------------------------------------------
rbt_sp_bli:
        ld      a,c
        ld      (rbt_sp_ln),a   ; first line
        ld      a,(ix+14)       ; asset bank (#ff = resident)
        ld      hl,rbt_sp_prev
        call    rbt_pg_in       ; the block data streams straight from it
        push    bc              ; srcptr clobbers B (phase) and C
        call    rbt_sp_srcptr      ; B = x -> DE = block, A = cols
        pop     bc
        push    de
        call    rbt_sp_rect        ; B,C = pos -> A = clipped cols, rh = rows
        pop     de
        ld      (rbt_sp_nc),a   ; cols
        ld      a,(rbt_sp_rh)
        or      a
        jp      z,_blout
        ld      (rbt_sp_rc),a   ; rows left
        ld      a,(ix+9)
        ld      (rbt_sp_md),a
_blr    ; per row: B = byte col, C = line
        ld      a,(rbt_sp_bc)
        ld      b,a
        ld      a,(rbt_sp_ln)
        ld      c,a
        push    de
        call    rbt_laddr       ; HL = dst row base
        pop     de
        ld      a,(rbt_sp_nc)
        ld      b,a             ; cols left
        call    rbt_wsplit   ; split at the band edge when scrolling
_bldisp ld      a,(rbt_sp_md)
        cp      2
        jr      z,_bxx          ; xor: bmp only
        cp      1
        jr      z,_bro          ; or: bmp only
_blm    ; mask: (scr & m) | b
        ld      a,(de)
        inc     de
        and     (hl)
        ld      c,a
        ld      a,(de)
        inc     de
        or      c
        ld      (hl),a
        inc     hl
        djnz    _blm
        jr      _blw
_bro    ; or: scr | bmp (skip mask byte)
        inc     de              ; skip mask
        ld      a,(de)
        inc     de
        or      (hl)
        ld      (hl),a
        inc     hl
        djnz    _bro
        jr      _blw
_bxx    ; xor: scr ^ bmp
        inc     de
        ld      a,(de)
        inc     de
        xor     (hl)
        ld      (hl),a
        inc     hl
        djnz    _bxx
_blw    ld      a,(rbt_scr_w2)   ; band-wrapped tail of this row
        or      a
        jr      z,_blnext
        ld      b,a
        xor     a
        ld      (rbt_scr_w2),a   ; consumed
        ld      a,h
        sub     8
        ld      h,a             ; dst wraps to the band base
        jr      _bldisp         ; same mode, tail run
_blnext ld      a,(rbt_sp_rc)
        dec     a
        ld      (rbt_sp_rc),a
        jr      z,_blout
        ld      a,(rbt_sp_ln)
        inc     a
        ld      (rbt_sp_ln),a
        jp      _blr
_blout  ld      hl,rbt_sp_prev
        jp      rbt_pg_out      ; restore mapping (ret)

; ----------------------------------------------------------------------------
; rbt_sp_commit - commit slot IX: erase committed pixels, save + draw at
; current (x,y). Used by update/draw/hide/kill paths.
; ----------------------------------------------------------------------------
rbt_sp_commit:
        ld      a,(ix+0)
        bit     0,a
        jr      z,_cmno         ; inactive: erase only
        bit     1,a
        jr      nz,_cmno        ; hidden: erase only
        call    rbt_sp_eraseix
        jr      rbt_sp_donew
_cmno   call    rbt_sp_eraseix
        ld      a,(ix+0)
        and     #fb
        ld      (ix+0),a
        ret

; ----------------------------------------------------------------------------
; rbt_sp_donew - pass-2 half of a commit: save the backdrop under (x,y) and
; draw there. rbt_sp_update calls this directly after its own erase pass so
; every save sees the lower slots' final positions.
; ----------------------------------------------------------------------------
rbt_sp_donew:
        ; save bg under new rect (mask/or modes)
        ld      a,(ix+9)
        cp      2
        jr      z,_dnxor
        call    rbt_sp_save        ; A = 1 if the rect was saved
        ld      (ix+15),a       ; committed only if auto-erase is possible
        jr      _dndr
_dnxor  ld      (ix+15),1       ; xor erases by redraw
_dndr   ; draw at (x,y)
        ld      b,(ix+1)
        ld      c,(ix+2)
        call    rbt_sp_bli
        ld      a,(ix+1)
        ld      (ix+16),a
        ld      a,(ix+2)
        ld      (ix+17),a
        ld      a,(ix+0)
        and     #fb             ; clear dirty
        ld      (ix+0),a
        ret

; ----------------------------------------------------------------------------
; rbt_sp_reset - drop all committed/screen state after CLS (called by
; rbt_cls; stubbed by the compiler when the sprite module is absent).
; ----------------------------------------------------------------------------
rbt_sp_reset:
        xor     a
        ld      (rbt_sp_i),a
_rsl    ld      a,(rbt_sp_i)
        call    rbt_slot
        ld      a,(ix+0)
        and     3               ; keep active+hidden, drop dirty
        ld      (ix+0),a
        bit     0,a
        jr      z,_rsk          ; inactive -> stays undrawn
        bit     1,a
        jr      nz,_rsk         ; hidden -> stays undrawn
        or      4
        ld      (ix+0),a        ; active+visible -> dirty: redrawn
_rsk    ld      (ix+15),0       ; nothing committed
        ld      a,(rbt_sp_i)
        inc     a
        ld      (rbt_sp_i),a
        cp      RBT_NSLOTS
        jr      c,_rsl
        ret

; ----------------------------------------------------------------------------
; rbt_sp_draw - A = id: draw slot now (commit). SPRITE REDRAW.
; ----------------------------------------------------------------------------
rbt_sp_draw:
        call    rbt_slot
        call    rbt_sp_commit
        jp      rbt_sp_animstep

; ----------------------------------------------------------------------------
; rbt_sp_update - commit every dirty slot (SPRITES UPDATE).
;
; Two passes keep save-under restores honest: a slot's save buffer can hold
; slices of lower-z sprites drawn beneath it when it was saved. Pass 1
; restores dirty slots high->low, so a sprite whose image a higher slot
; captured gets its own restore in afterwards, covering the stale copy.
; Pass 2 saves + redraws low->high, so every save records the lower slots'
; final positions — the next frame's restores stay consistent.
;
; An erase also damages any other committed sprite it overlaps: lower slots
; are pulled into the same erase pass (mark bit0 -> full recommit in pass 2),
; higher slots only need their bitmap repainted over the restored backdrop
; (mark bit1 -> rbt_sp_bli at the committed pos in pass 2). Marks chain, so
; a damaged slot's own erase propagates the marks further down.
; ----------------------------------------------------------------------------
rbt_sp_update:
        call    rbt_sfx_drain
        ld      hl,rbt_sp_mark
        ld      b,RBT_NSLOTS
        xor     a
_uc     ld      (hl),a          ; clear damage marks
        inc     hl
        djnz    _uc
        ; pass 1: restore dirty or damage-marked slots, high->low
        ld      a,RBT_NSLOTS-1
_u1     ld      (rbt_sp_i),a
        call    rbt_slot
        ld      a,(ix+0)
        bit     2,a
        jr      nz,_u1e         ; dirty
        ld      a,(rbt_sp_i)
        call    _markp
        bit     0,(hl)
        jp      z,_u1n          ; clean and undamaged
_u1e    ld      a,(ix+15)
        or      a
        jp      z,_u1x          ; nothing committed -> nothing to restore
        ; capture the rect about to be restored (committed pos + size)
        ld      a,(ix+16)
        ld      (rbt_sp_x0),a
        add     a,(ix+3)
        dec     a
        ld      (rbt_sp_x1),a
        ld      a,(ix+17)
        ld      (rbt_sp_y0),a
        add     a,(ix+4)
        dec     a
        ld      (rbt_sp_y1),a
        call    rbt_sp_eraseix
        ; mark committed neighbours overlapping the restored rect
        xor     a
_u1s    ld      (rbt_sp_j),a
        ld      hl,rbt_sp_i
        cp      (hl)
        jr      z,_u1sn         ; self
        call    rbt_slot        ; IX = slot j
        ld      a,(ix+0)
        bit     0,a
        jr      z,_u1sn         ; inactive
        bit     1,a
        jr      nz,_u1sn        ; hidden: the dirty flag erases it anyway
        ld      a,(ix+15)
        or      a
        jr      z,_u1sn         ; not committed
        ld      a,(ix+16)
        add     a,(ix+3)
        dec     a               ; jx1 = jx + jw - 1
        ld      hl,rbt_sp_x0
        cp      (hl)
        jr      c,_u1sn         ; j right edge left of the restored rect
        ld      a,(rbt_sp_x1)
        cp      (ix+16)
        jr      c,_u1sn         ; rect right edge left of j
        ld      a,(ix+17)
        add     a,(ix+4)
        dec     a               ; jy1
        ld      hl,rbt_sp_y0
        cp      (hl)
        jr      c,_u1sn
        ld      a,(rbt_sp_y1)
        cp      (ix+17)
        jr      c,_u1sn
        ld      a,(rbt_sp_j)
        ld      hl,rbt_sp_i
        cp      (hl)
        ld      b,1             ; j < i: erase + recommit later in this pass
        jr      c,_um1
        ld      b,2             ; j > i: repaint only (already erased pass)
_um1    ld      a,(rbt_sp_j)
        call    _markp
        ld      a,(hl)
        or      b
        ld      (hl),a
_u1sn   ld      a,(rbt_sp_j)
        inc     a
        cp      RBT_NSLOTS
        jr      c,_u1s
        jr      _u1n
_u1x    call    rbt_sp_eraseix  ; dirty but uncommitted: no-op, keeps flags
_u1n    ld      a,(rbt_sp_i)
        dec     a
        jp      p,_u1
        ; pass 2: save + draw dirty/marked slots, low->high
        xor     a
_u2     ld      (rbt_sp_i),a
        call    rbt_slot
        ld      a,(rbt_sp_i)
        call    _markp
        ld      a,(ix+0)
        bit     2,a
        jr      nz,_u2d         ; dirty
        bit     0,(hl)
        jr      nz,_u2dn        ; damage-recommit: erased in pass 1
        bit     1,(hl)
        jr      z,_u2n          ; untouched
        ld      b,(ix+16)       ; damage-repaint: bitmap over restored bg
        ld      c,(ix+17)
        call    rbt_sp_bli
        jr      _u2n
_u2d    bit     0,a
        jr      z,_u2c          ; inactive: just clear dirty
        bit     1,a
        jr      nz,_u2c         ; hidden: just clear dirty
_u2dn   call    rbt_sp_donew
        jr      _u2n
_u2c    ld      a,(ix+0)
        and     #fb             ; clear dirty
        ld      (ix+0),a
_u2n    call    rbt_sp_animstep
        ld      a,(rbt_sp_i)
        inc     a
        cp      RBT_NSLOTS
        jr      c,_u2
        ret
_markp  ld      hl,rbt_sp_mark  ; HL = damage-mark byte for slot A
        add     a,l
        ld      l,a
        ret     nc
        inc     h
        ret

; ----------------------------------------------------------------------------
; rbt_sp_drawall - commit every drawable slot (SPRITES DRAW).
; ----------------------------------------------------------------------------
rbt_sp_drawall:
        xor     a
        ld      (rbt_sp_i),a
_dl     ld      a,(rbt_sp_i)
        call    rbt_slot
        ld      a,(ix+0)
        bit     0,a
        jr      z,_dnext
        bit     1,a
        jr      nz,_dnext
        call    rbt_sp_commit
        call    rbt_sp_animstep
_dnext  ld      a,(rbt_sp_i)
        inc     a
        ld      (rbt_sp_i),a
        cp      RBT_NSLOTS
        jr      c,_dl
        ret

; ----------------------------------------------------------------------------
; rbt_spcoll - A = id a, B = id b -> A = 1 if their bboxes overlap.
; ----------------------------------------------------------------------------
rbt_spcoll:
        push    bc
        call    rbt_slot        ; IX = slot a
        pop     bc
        ld      a,(ix+0)
        bit     0,a
        jr      z,_no
        push    iy
        ld      a,b
        and     RBT_NSLOTS-1
        ld      e,a
        add     a,a
        add     a,a
        add     a,a
        add     a,a             ; *16
        add     a,e
        add     a,e             ; *18 (id=15 -> 270: carry!)
        ld      e,a
        ld      d,0
        jr      nc,_sc_nc
        inc     d
_sc_nc  ld      iy,rbt_sprites
        add     iy,de
        ld      a,(iy+0)
        bit     0,a
        jr      z,_noy
        ; x1 < x2 + w2 ?
        ld      a,(iy+3)
        add     a,(iy+1)
        ld      b,a
        ld      a,(ix+1)
        cp      b
        jr      nc,_noy
        ; x2 < x1 + w1 ?
        ld      a,(ix+3)
        add     a,(ix+1)
        ld      b,a
        ld      a,(iy+1)
        cp      b
        jr      nc,_noy
        ; y1 < y2 + h2 ?
        ld      a,(iy+4)
        add     a,(iy+2)
        ld      b,a
        ld      a,(ix+2)
        cp      b
        jr      nc,_noy
        ; y2 < y1 + h1 ?
        ld      a,(ix+4)
        add     a,(ix+2)
        ld      b,a
        ld      a,(iy+2)
        cp      b
        jr      nc,_noy
        pop     iy
        ld      a,1
        ret
_noy    pop     iy
_no     xor     a
        ret

; ----------------------------------------------------------------------------
; rbt_sp_mul - A = x, D = y -> DE = x*y (8x8 -> 16). Preserves BC.
; ----------------------------------------------------------------------------
rbt_sp_mul:
        ld      e,a             ; DE = x
        ld      a,d             ; A = y (bit loop)
        ld      d,0
        ld      hl,0
        ld      b,8
_mdl    add     hl,hl
        rla
        jr      nc,_mdn
        add     hl,de
_mdn    djnz    _mdl
        ex      de,hl           ; DE = product
        ret

; ----------------------------------------------------------------------------
; scratch
; ----------------------------------------------------------------------------
rbt_sp_i        defb 0          ; slot index for update/drawall
rbt_sp_j        defb 0          ; update damage-scan inner index
rbt_sp_x0       defb 0          ; erased rect for damage marking
rbt_sp_x1       defb 0
rbt_sp_y0       defb 0
rbt_sp_y1       defb 0
rbt_sp_mark     defs RBT_NSLOTS ; update marks: bit0 recommit, bit1 repaint
rbt_sp_rc       defb 0          ; row counter
rbt_sp_rh       defb 0          ; clipped rows
rbt_sp_nc       defb 0          ; clipped cols
rbt_sp_bc       defb 0          ; byte col
rbt_sp_ln       defb 0          ; current line
rbt_sp_md       defb 0          ; draw mode
rbt_sp_prev     defb 0          ; mapping save byte for asset-bank guards
rbt_sp_rw       defb 0          ; spare
''',
    'tilemap': r'''
; ============================================================================
; rbt_tilemap_asm - CPC tilemap engine (mode 1).
; Same state machine as the ZX module: a view window of cells (vx,vy,vw,vh)
; over a map at camera (camx,camy). Tiles are 8x8 1bpp expanded to pen1/pen0
; on the fly by rbt_tile8; a cell is 2 bytes wide x 8 lines on screen.
; Attr bytes in the tileset are ignored (CPC has no attribute plane).
; ============================================================================

; ----------------------------------------------------------------------------
; rbt_tm_settiles - HL = tileset data
; ----------------------------------------------------------------------------
rbt_tm_settiles:
        ld      (rbt_tm_tiles),hl
        ld      a,(hl)
        ld      (rbt_tm_n),a
        inc     hl
        ld      (rbt_tm_bmp),hl
        ld      a,(rbt_tm_n)
        add     a,a
        add     a,a
        add     a,a             ; n*8
        ld      e,a
        ld      d,0
        add     hl,de
        ld      (rbt_tm_tattr),hl
        ld      a,(rbt_tm_n)
        ld      e,a
        add     hl,de
        ld      (rbt_tm_tflags),hl
        ret

; ----------------------------------------------------------------------------
; rbt_tm_setmap - HL = tilemap data
; ----------------------------------------------------------------------------
rbt_tm_setmap:
        ld      (rbt_tm_map),hl
        ld      a,1
        ld      (rbt_tm_on),a   ; sprite erase switches to map repainting
        ld      a,(hl)
        ld      (rbt_tm_mw),a
        inc     hl
        ld      a,(hl)
        ld      (rbt_tm_mh),a
        inc     hl
        ld      (rbt_tm_cells),hl
        ; fall through: clamp the camera so the view fits in the map

; cam = 0 when view >= map on that axis, else min(cam, map - view)
rbt_tm_clampcam:
        ld      a,(rbt_tm_vw)
        ld      b,a
        ld      a,(rbt_tm_mw)
        cp      b
        jr      c,_x0           ; mw < vw
        jr      z,_x0
        sub     b               ; mw - vw = max cam
        ld      b,a
        ld      a,(rbt_tm_camx)
        cp      b
        jr      c,_cx
        jr      z,_cx
        ld      a,b
        jr      _cx
_x0     xor     a
_cx     ld      (rbt_tm_camx),a
        ld      a,(rbt_tm_vh)
        ld      b,a
        ld      a,(rbt_tm_mh)
        cp      b
        jr      c,_y0
        jr      z,_y0
        sub     b
        ld      b,a
        ld      a,(rbt_tm_camy)
        cp      b
        jr      c,_cy
        jr      z,_cy
        ld      a,b
        jr      _cy
_y0     xor     a
_cy     ld      (rbt_tm_camy),a
        ret

; ----------------------------------------------------------------------------
; rbt_tm_view - B=x, C=y, D=w, E=h (screen cells, clamped to 32x24)
; ----------------------------------------------------------------------------
rbt_tm_view:
        ld      a,b
        cp      32
        jr      c,_vx
        xor     a
_vx     ld      (rbt_tm_vx),a
        ld      a,c
        cp      24
        jr      c,_vy
        xor     a
_vy     ld      (rbt_tm_vy),a
        ld      a,d
        or      a
        jr      z,_vw1
        cp      33
        jr      c,_vw2
_vw1    ld      a,32
_vw2    ld      (rbt_tm_vw),a
        ld      a,e
        or      a
        jr      z,_vh1
        cp      25
        jr      c,_vh2
_vh1    ld      a,24
_vh2    ld      (rbt_tm_vh),a
        ; band split: smallest raster-aligned row >= vy+vh. The GA int
        ; counter resets 2 lines after vsync (row 30), so raster ints land
        ; inside char rows 4,10,17,23,30,36 and a mid-frame CRTC write can
        ; only take effect at rows 5,11,18,24,31,37 - the usable band
        ; starts are 5,11,18,24 (rbt_split_int = the int index: the first
        ; vsync int is 0, then 34->2, 86->3, 138->4, 190->5).
        ; 0 = no band - the whole screen scrolls.
        ld      a,(rbt_tm_vy)
        ld      b,a
        ld      a,(rbt_tm_vh)
        add     a,b             ; first row below the view
        cp      6
        jr      c,_sp05
        cp      12
        jr      c,_sp11
        cp      19
        jr      c,_sp18
        cp      25
        jr      c,_sp24
        xor     a
        ld      b,a
        jr      _sps
_sp05   ld      a,5
        ld      b,2
        jr      _sps
_sp11   ld      a,11
        ld      b,3
        jr      _sps
_sp18   ld      a,18
        ld      b,4
        jr      _sps
_sp24   ld      a,24
        ld      b,5
_sps    ld      (rbt_scr_split),a
        ld      a,b
        ld      (rbt_split_int),a
        ret                     ; rbt_scr_son arms on the first SCROLL

; ----------------------------------------------------------------------------
; rbt_tm_camera - B=tx, C=ty (map coords, clamped so view fits in map)
; ----------------------------------------------------------------------------
rbt_tm_camera:
        ld      a,b
        ld      (rbt_tm_camx),a
        ld      a,c
        ld      (rbt_tm_camy),a
        jp      rbt_tm_clampcam

; ----------------------------------------------------------------------------
; rbt_tm_blit - draw tile A at screen cell B=x, C=y. Clobbers everything.
; ----------------------------------------------------------------------------
rbt_tm_blit:
        push    bc
        ; src = bmp + id*8
        ld      e,a
        ld      d,0
        sla     e
        rl      d
        sla     e
        rl      d
        sla     e
        rl      d               ; DE = id*8
        ld      hl,(rbt_tm_bmp)
        add     hl,de
        ex      de,hl           ; DE = src
        ld      a,(rbt_tm_tbank)
        ld      hl,rbt_tm_tprev
        call    rbt_pg_in       ; page tileset bank (no-op when resident)
        call    rbt_tile8       ; B=cell x, C=cell y
        ld      hl,rbt_tm_tprev
        call    rbt_pg_out
        pop     bc
        ret

; ----------------------------------------------------------------------------
; rbt_tm_draw - draw the whole view window
; ----------------------------------------------------------------------------
rbt_tm_draw:
        xor     a
        ld      (rbt_tm_r),a
_dr     ld      a,(rbt_tm_vh)
        ld      b,a
        ld      a,(rbt_tm_r)
        cp      b
        ret     nc
        xor     a
        ld      (rbt_tm_c),a
_dc     ld      a,(rbt_tm_vw)
        ld      b,a
        ld      a,(rbt_tm_c)
        cp      b
        jp      nc,_dnext
        ; map coords
        ld      a,(rbt_tm_camx)
        ld      b,a
        ld      a,(rbt_tm_c)
        add     a,b
        ld      b,a             ; mx = camx + c
        ld      a,(rbt_tm_camy)
        ld      c,a
        ld      a,(rbt_tm_r)
        add     a,c
        ld      c,a             ; my = camy + r
        call    rbt_tm_mapat          ; A = tile id
        push    af
        ; screen cell = (vx+c, vy+r)
        ld      a,(rbt_tm_vx)
        ld      b,a
        ld      a,(rbt_tm_c)
        add     a,b
        ld      b,a
        ld      a,(rbt_tm_vy)
        ld      c,a
        ld      a,(rbt_tm_r)
        add     a,c
        ld      c,a
        pop     af
        call    rbt_tm_blit
        ld      a,(rbt_tm_c)
        inc     a
        ld      (rbt_tm_c),a
        jp      _dc
_dnext  ld      a,(rbt_tm_r)
        inc     a
        ld      (rbt_tm_r),a
        jp      _dr

; ----------------------------------------------------------------------------
; rbt_tm_redraw - B=x, C=y, D=w, E=h: repair a screen-cell region from the map
; ----------------------------------------------------------------------------
rbt_tm_redraw:
        ld      a,e
        ld      (rbt_ct_r1),a   ; rows remaining
        ld      a,d
        ld      (rbt_tm_dir),a  ; spare var: original col count
        ld      a,c
        ld      (rbt_ct_r),a    ; current row
        ld      a,b
        ld      (rbt_ct_c0),a   ; start col
_rr     ld      a,(rbt_ct_r1)
        or      a
        ret     z
        ld      a,(rbt_tm_dir)
        ld      (rbt_ct_c1),a   ; cols remaining this row
        ld      a,(rbt_ct_c0)
        ld      (rbt_ct_c),a
_rc     ld      a,(rbt_ct_c1)
        or      a
        jp      z,_rnext
        ; inside view? c in [vx,vx+vw), r in [vy,vy+vh)
        ld      a,(rbt_tm_vx)
        ld      b,a
        ld      a,(rbt_ct_c)
        cp      b
        jp      c,_rskip
        ld      a,(rbt_tm_vw)
        add     a,b
        ld      b,a
        ld      a,(rbt_ct_c)
        cp      b
        jp      nc,_rskip
        ld      a,(rbt_tm_vy)
        ld      b,a
        ld      a,(rbt_ct_r)
        cp      b
        jp      c,_rskip
        ld      a,(rbt_tm_vh)
        add     a,b
        ld      b,a
        ld      a,(rbt_ct_r)
        cp      b
        jp      nc,_rskip
        ; map coords = cell - view origin + camera
        ld      a,(rbt_ct_c)
        ld      b,a
        ld      a,(rbt_tm_vx)
        ld      c,a
        ld      a,b
        sub     c
        ld      b,a
        ld      a,(rbt_tm_camx)
        add     a,b
        ld      b,a             ; mx
        ld      a,(rbt_ct_r)
        ld      c,a
        ld      a,(rbt_tm_vy)
        ld      d,a
        ld      a,c
        sub     d
        ld      c,a
        ld      a,(rbt_tm_camy)
        add     a,c
        ld      c,a             ; my
        call    rbt_tm_mapat
        push    af
        ld      a,(rbt_ct_c)
        ld      b,a
        ld      a,(rbt_ct_r)
        ld      c,a
        pop     af
        call    rbt_tm_blit
_rskip  ld      a,(rbt_ct_c1)
        dec     a
        ld      (rbt_ct_c1),a
        ld      a,(rbt_ct_c)
        inc     a
        ld      (rbt_ct_c),a
        jp      _rc
_rnext  ld      a,(rbt_ct_r1)
        dec     a
        ld      (rbt_ct_r1),a
        ld      a,(rbt_ct_r)
        inc     a
        ld      (rbt_ct_r),a
        jp      _rr

; ----------------------------------------------------------------------------
; rbt_tm_soff - add signed byte delta A to the CRTC scroll offset (rbt_scr_soff,
; bytes, mod 2048) and push it to the display-start registers. One cell = 2
; bytes horizontal, 80 bytes vertical. di/ei keeps the split ticker from
; interleaving a register select mid-pair.
; ----------------------------------------------------------------------------
rbt_tm_soff:
        ld      e,a
        rla
        sbc     a,a
        ld      d,a             ; DE = sign-extended delta
        ld      hl,(rbt_scr_soff)
        add     hl,de
        ld      a,h
        and     #07
        ld      h,a             ; wrap the 2048-byte band
        ld      (rbt_scr_soff),hl
        srl     h
        rr      l               ; CRTC units = bytes/2
        if      RBT_CART
        call    rbt_crtc_r1213  ; no ISR on cart - nothing to race
        else
        di                      ; keep the split ticker out of the pair
        call    rbt_crtc_r1213
        ei
        endif
        ret

; ----------------------------------------------------------------------------
; rbt_tm_colid - draw view column B=screen cell x from map column C, all rows.
; rbt_tm_rowid - draw view row B=screen cell y from map row C, all cols.
; ----------------------------------------------------------------------------
rbt_tm_colid:
        ld      a,b
        ld      (rbt_ct_c),a
        ld      a,c
        ld      (rbt_ct_c0),a
        xor     a
        ld      (rbt_ct_r),a
_ccl    ld      a,(rbt_tm_vh)
        ld      b,a
        ld      a,(rbt_ct_r)
        cp      b
        ret     nc
        ld      a,(rbt_ct_c0)
        ld      b,a             ; mx
        ld      a,(rbt_tm_camy)
        ld      c,a
        ld      a,(rbt_ct_r)
        add     a,c
        ld      c,a             ; my = camy + r
        call    rbt_tm_mapat
        push    af
        ld      a,(rbt_ct_c)
        ld      b,a
        ld      a,(rbt_tm_vy)
        ld      c,a
        ld      a,(rbt_ct_r)
        add     a,c
        ld      c,a
        pop     af
        call    rbt_tm_blit
        ld      a,(rbt_ct_r)
        inc     a
        ld      (rbt_ct_r),a
        jp      _ccl

rbt_tm_rowid:
        ld      a,b
        ld      (rbt_ct_r),a
        ld      a,c
        ld      (rbt_ct_r0),a
        xor     a
        ld      (rbt_ct_c),a
_crl    ld      a,(rbt_tm_vw)
        ld      b,a
        ld      a,(rbt_ct_c)
        cp      b
        ret     nc
        ld      a,(rbt_tm_camx)
        ld      b,a
        ld      a,(rbt_ct_c)
        add     a,b
        ld      b,a             ; mx = camx + c
        ld      a,(rbt_ct_r0)
        ld      c,a             ; my
        call    rbt_tm_mapat
        push    af
        ld      a,(rbt_tm_vx)
        ld      b,a
        ld      a,(rbt_ct_c)
        add     a,b
        ld      b,a
        ld      a,(rbt_ct_r)
        ld      c,a
        pop     af
        call    rbt_tm_blit
        ld      a,(rbt_ct_c)
        inc     a
        ld      (rbt_ct_c),a
        jp      _crl

; ----------------------------------------------------------------------------
; rbt_tm_scroll - A = dir (0=left,1=right,2=up,3=down), B = steps.
; Hardware scroll: per step the CRTC display start moves one cell around the
; circular 2048-byte band (2 bytes horizontal, 80 vertical) and only the
; newly exposed edge column/row is drawn. Rows >= rbt_scr_split stay static
; via the raster-split restore in rbt_split_isr.
; ----------------------------------------------------------------------------
rbt_tm_scroll:
        and     3
        ld      (rbt_tm_dir),a
        ld      a,b
        or      a
        ret     z
        ld      (rbt_tm_steps),a
        ld      a,(rbt_tm_on)
        ld      (rbt_scr_son),a ; scrolled addressing once a scroll happens
        call    rbt_split_install       ; arm the static band (fw builds)
_slp    ld      a,(rbt_tm_dir)
        or      a
        jr      nz,_sr
        ; left: camx--
        ld      a,(rbt_tm_camx)
        or      a
        jp      z,_sdone
        dec     a
        ld      (rbt_tm_camx),a
        ld      a,-2
        call    rbt_tm_soff
        ld      a,(rbt_tm_vx)
        ld      b,a
        ld      a,(rbt_tm_camx)
        ld      c,a
        call    rbt_tm_colid            ; draw left edge column
        jp      _snext
_sr     cp      1
        jr      nz,_su
        ; right: camx++ iff camx+vw < mw
        ld      a,(rbt_tm_camx)
        ld      b,a
        ld      a,(rbt_tm_vw)
        add     a,b
        ld      b,a
        ld      a,(rbt_tm_mw)
        cp      b
        jp      c,_sdone
        jp      z,_sdone
        ld      a,(rbt_tm_camx)
        inc     a
        ld      (rbt_tm_camx),a
        ld      a,2
        call    rbt_tm_soff
        ld      a,(rbt_tm_vx)
        ld      b,a
        ld      a,(rbt_tm_vw)
        add     a,b
        dec     a
        ld      b,a                     ; screen col vx+vw-1
        ld      a,(rbt_tm_camx)
        ld      c,a
        ld      a,(rbt_tm_vw)
        add     a,c
        dec     a
        ld      c,a                     ; map col camx+vw-1
        call    rbt_tm_colid            ; draw right edge column
        jp      _snext
_su     cp      2
        jr      nz,_sdn
        ; up: camy--
        ld      a,(rbt_tm_camy)
        or      a
        jp      z,_sdone
        dec     a
        ld      (rbt_tm_camy),a
        ld      a,-80
        call    rbt_tm_soff
        ld      a,(rbt_tm_vy)
        ld      b,a
        ld      a,(rbt_tm_camy)
        ld      c,a
        call    rbt_tm_rowid            ; draw top edge row
        jp      _snext
_sdn    ; down: camy++ iff camy+vh < mh
        ld      a,(rbt_tm_camy)
        ld      b,a
        ld      a,(rbt_tm_vh)
        add     a,b
        ld      b,a
        ld      a,(rbt_tm_mh)
        cp      b
        jp      c,_sdone
        jp      z,_sdone
        ld      a,(rbt_tm_camy)
        inc     a
        ld      (rbt_tm_camy),a
        ld      a,80
        call    rbt_tm_soff
        ld      a,(rbt_tm_vy)
        ld      b,a
        ld      a,(rbt_tm_vh)
        add     a,b
        dec     a
        ld      b,a                     ; screen row vy+vh-1
        ld      a,(rbt_tm_camy)
        ld      c,a
        ld      a,(rbt_tm_vh)
        add     a,c
        dec     a
        ld      c,a                     ; map row camy+vh-1
        call    rbt_tm_rowid            ; draw bottom edge row
_snext  ld      a,(rbt_tm_steps)
        dec     a
        ld      (rbt_tm_steps),a
        jp      nz,_slp
_sdone  ret

; ----------------------------------------------------------------------------
; rbt_tileat - B=tx, C=ty (map coords) -> A = tile id (255 = out of bounds)
; ----------------------------------------------------------------------------
rbt_tileat:
        ld      a,(rbt_tm_mw)
        cp      b
        jr      c,_ta0
        jr      z,_ta0
        ld      a,(rbt_tm_mh)
        cp      c
        jr      c,_ta0
        jr      z,_ta0
        call    rbt_tm_mapat
        ret
_ta0    ld      a,255
        ret

; ----------------------------------------------------------------------------
; rbt_tileatset - B=tx, C=ty, D=id : write map cell if in bounds
; ----------------------------------------------------------------------------
rbt_tileatset:
        ld      a,(rbt_tm_mw)
        cp      b
        ret     c
        ret     z
        ld      a,(rbt_tm_mh)
        cp      c
        ret     c
        ret     z
        ld      a,(rbt_tm_mbank)
        ld      hl,rbt_tm_mprev
        call    rbt_pg_in       ; page map bank for the cell write
        push    de
        push    bc
        ld      hl,(rbt_tm_cells)
        ld      a,c
        or      a
        jr      z,_tax
        ld      b,a
        ld      a,(rbt_tm_mw)
        ld      e,a
        ld      d,0
_tal    add     hl,de
        djnz    _tal
_tax    pop     bc
        ld      e,b
        ld      d,0
        add     hl,de
        pop     de
        ld      (hl),d
        ld      hl,rbt_tm_mprev
        jp      rbt_pg_out

; ----------------------------------------------------------------------------
; rbt_tileflags - A = tile id -> A = flags byte (0 if out of range)
; ----------------------------------------------------------------------------
rbt_tileflags:
        ld      b,a
        ld      a,(rbt_tm_n)
        cp      b
        jr      c,_tf0
        jr      z,_tf0
        ld      a,(rbt_tm_tbank)
        ld      hl,rbt_tm_tprev
        call    rbt_pg_in       ; page tileset bank for the flag read
        ld      a,b
        ld      e,a
        ld      d,0
        ld      hl,(rbt_tm_tflags)
        add     hl,de
        ld      a,(hl)
        ld      hl,rbt_tm_tprev
        jp      rbt_pg_out
_tf0    xor     a
        ret
''',
    'tmdata': r'''
; ============================================================================
; rbt_tmdata_asm - tilemap state + map query (CPC: no bank paging).
; Var layouts match the ZX module so codegen emits the same stores.
; ============================================================================

rbt_tm_tiles    defw 0          ; tileset base
rbt_tm_bmp      defw 0          ; bitmaps (tiles+1)
rbt_tm_tattr    defw 0          ; attr table (tiles+1+8n)
rbt_tm_tflags   defw 0          ; flag table (tiles+1+9n)
rbt_tm_n        defb 0          ; tile count
rbt_tm_tbank    defb #ff        ; unused on CPC (kept for ABI)
rbt_tm_map      defw 0          ; map base
rbt_tm_mbank    defb #ff        ; unused on CPC (codegen writes it)
rbt_tm_tprev    defb 0          ; unused on CPC
rbt_tm_mprev    defb 0          ; unused on CPC
rbt_tm_cells    defw 0          ; map cells (map+2)
rbt_tm_mw       defb 0          ; map width
rbt_tm_mh       defb 0          ; map height
rbt_tm_vx       defb 0
rbt_tm_vy       defb 0
rbt_tm_vw       defb 32
rbt_tm_vh       defb 24
rbt_tm_camx     defb 0
rbt_tm_camy     defb 0
rbt_tm_on       defb 0          ; 1 once a map is set (sprites erase via map)
rbt_tm_r        defb 0
rbt_tm_c        defb 0
rbt_tm_dir      defb 0
rbt_tm_steps    defb 0
rbt_tm_cnt      defb 0
rbt_tm_tid      defb 0
rbt_ct_c0       defb 0
rbt_ct_c1       defb 0
rbt_ct_r0       defb 0
rbt_ct_r1       defb 0
rbt_ct_r        defb 0
rbt_ct_c        defb 0

; ----------------------------------------------------------------------------
; rbt_tm_mapat - B=mx, C=my -> A = tile id (0 when out of bounds). Clobbers DE,HL.
; ----------------------------------------------------------------------------
rbt_tm_mapat:
        ld      hl,rbt_tm_mprev
        ld      a,(rbt_tm_mbank)
        call    rbt_pg_in       ; page map bank (no-op when resident)
        call    _mab
        ld      hl,rbt_tm_mprev
        jp      rbt_pg_out      ; restores mapping; preserves A = tile id
_mab    push    bc
        ld      a,(rbt_tm_mw)
        cp      b
        jr      c,_ma0
        jr      z,_ma0          ; mx >= w
        ld      a,(rbt_tm_mh)
        cp      c
        jr      c,_ma0
        jr      z,_ma0          ; my >= h
        ld      hl,(rbt_tm_cells)
        ld      a,c
        or      a
        jr      z,_addx
        ld      b,a             ; loop my times
        ld      a,(rbt_tm_mw)
        ld      e,a
        ld      d,0             ; DE = w
_mal    add     hl,de
        djnz    _mal
_addx   pop     bc
        ld      e,b
        ld      d,0
        add     hl,de
        ld      a,(hl)
        ret
_ma0    pop     bc
        xor     a
        ret
''',
  },
  'cbm': {
    'charset': r'''
; ============================================================================
; rbt_charset - text engine (Commodore 64, ca65)
; 40x25 screen RAM at $0400 + colour RAM at $D800. Chars are written as VIC
; screen codes (ASCII converted by rbt_a2sc); the colour byte is rbt_attr's
; low nibble, its bit7 (FLASH) selects reverse video per char.
; (rbt_col/rbt_row cursor vars live in core)
; ============================================================================

        .code

rbt_font:        .word 0         ; font asset ptr (CHARSET); 0 = ROM chargen
rbt_fontbank:    .byte $ff       ; unused (no banked RAM) — kept for parity

; ----------------------------------------------------------------------------
; rbt_fset - apply rbt_font: copy .rbf glyphs into charset RAM (base $3800)
; at their *screen-code* slots — rbt_a2sc folds ASCII to codes 0-63, so a
; linear copy would leave codes 0-31 ('@'-'_' + folded lowercase) reading
; garbage RAM (letters rendered as solid blocks):
;   font idx  0-31 (ASCII 32-63) -> codes 32-63   $3900-$39FF
;   font idx 32-63 (ASCII 64-95) -> codes 0-31    $3800-$38FF
; font idx 64-95 (ASCII 96-127 lowercase) is unused — a2sc folds it onto
; codes 0-31, so 'a' shows the 'A' glyph. Then point the VIC at charset
; RAM: $D018 = screen $0400 + charset $3800.
; ----------------------------------------------------------------------------
rbt_fset:
        ; font+$000 (idx 0-31) -> $3900 (codes 32-63)
        lda     rbt_font
        sta     rbt_ptr
        lda     rbt_font+1
        sta     rbt_ptr+1       ; rbt_ptr = src
        lda     #$00
        sta     rbt_hl
        lda     #>(RBT_CSET+$100)
        sta     rbt_hl+1        ; rbt_hl = dst charset+$100 (codes 32-63)
        jsr     _fpage
        ; font+$100 (idx 32-63) -> charset+$000 (codes 0-31); rbt_ptr has
        ; rolled on to font+$100 inside _fpage
        lda     #>RBT_CSET
        sta     rbt_hl+1
        jsr     _fpage
        lda     #RBT_D018T      ; screen + charset in the active VIC bank
        jsr     rbt_mapio       ; preserves A
        sta     $d018
        jsr     rbt_maprun
        sta     rbt_d018        ; text-mode shadow (rbt_scrmode restores it)
        rts

; _fpage - copy 256 bytes rbt_ptr -> rbt_hl, advancing both src/dst a page.
_fpage: ldy     #0
@cp:    lda     (rbt_ptr),y
        sta     (rbt_hl),y
        iny
        bne     @cp
        inc     rbt_ptr+1
        inc     rbt_hl+1
        rts

; ----------------------------------------------------------------------------
; rbt_locate - set cursor. In: rbt_b = column (0-39), rbt_c = row (0-24)
; ----------------------------------------------------------------------------
rbt_locate:
        lda     rbt_b
        cmp     #40
        bcc     @cok
        lda     #39
@cok:   sta     rbt_col
        lda     rbt_c
        cmp     #25
        bcc     @rok
        lda     #24
@rok:   sta     rbt_row
        rts

; ----------------------------------------------------------------------------
; rbt_a2sc - ASCII in A -> VIC screen code in A.
;   '@'-$5F map to 0-31 by subtracting $40; lowercase folds to upper.
;   32-63 (space, digits, most punctuation) are already screen codes.
; ----------------------------------------------------------------------------
rbt_a2sc:
        cmp     #$60
        bcc     @nolc
        and     #$5f            ; fold a-z (and `,{,|,},~) onto @,A-Z,[...
@nolc:  cmp     #$40
        bcc     @done
        sec
        sbc     #$40
@done:  rts

; ----------------------------------------------------------------------------
; rbt_putchar - print char A at cursor, advance cursor.
; Writes the screen code + current colour. Preserves X.
; ----------------------------------------------------------------------------
rbt_putchar:
        sta     rbt_t0          ; char
        ; rbt_ptr = $0400 + row*40 + col  (row*40 = row*32 + row*8)
        lda     rbt_row
        sta     rbt_ptr
        lda     #0
        sta     rbt_ptr+1
        asl     rbt_ptr         ; *2
        rol     rbt_ptr+1
        asl     rbt_ptr         ; *4
        rol     rbt_ptr+1
        asl     rbt_ptr         ; *8
        rol     rbt_ptr+1
        lda     rbt_ptr         ; stash row*8
        sta     rbt_t2
        lda     rbt_ptr+1
        sta     rbt_t2+1
        asl     rbt_ptr         ; *16
        rol     rbt_ptr+1
        asl     rbt_ptr         ; *32
        rol     rbt_ptr+1
        clc
        lda     rbt_ptr         ; + row*8 -> row*40
        adc     rbt_t2
        sta     rbt_ptr
        lda     rbt_ptr+1
        adc     rbt_t2+1
        sta     rbt_ptr+1
        clc
        lda     rbt_ptr         ; + col + RBT_SCRN
        adc     rbt_col
        sta     rbt_ptr
        lda     rbt_ptr+1
        adc     #>RBT_SCRN
        sta     rbt_ptr+1
        ; screen code (+ reverse bit when OVER or FLASH is set)
        lda     rbt_t0
        jsr     rbt_a2sc
        ldx     rbt_over
        beq     @nrev
        ora     #$80
@nrev:  ldx     rbt_attr
        bpl     @nfl
        ora     #$80
@nfl:   ldy     #0
        sta     (rbt_ptr),y
        ; colour RAM = screen + RBT_CDELTA (lives in the I/O window on c128)
        lda     rbt_ptr+1
        clc
        adc     #>RBT_CDELTA
        sta     rbt_ptr+1
        jsr     rbt_mapio
        lda     rbt_attr
        and     #$0f
        sta     (rbt_ptr),y
        jsr     rbt_maprun
        ; advance cursor: col++, wrap -> row++ (wraps to 0 at bottom)
        inc     rbt_col
        lda     rbt_col
        cmp     #40
        bcc     @done
        lda     #0
        sta     rbt_col
        inc     rbt_row
        lda     rbt_row
        cmp     #25
        bcc     @done
        lda     #0
        sta     rbt_row
@done:  rts

; ----------------------------------------------------------------------------
; rbt_newline - move cursor to start of next row (wraps to 0 at bottom)
; ----------------------------------------------------------------------------
rbt_newline:
        lda     #0
        sta     rbt_col
        inc     rbt_row
        lda     rbt_row
        cmp     #25
        bcc     @ok
        lda     #0
        sta     rbt_row
@ok:    rts

; ----------------------------------------------------------------------------
; rbt_print_str - print length-prefixed string at rbt_hl: .byte len,"text"
; ----------------------------------------------------------------------------
rbt_print_str:
        ldy     #0
        lda     (rbt_hl),y
        sta     rbt_slen
        beq     @done
        inc     rbt_hl          ; skip len byte
        bne     @s
        inc     rbt_hl+1
@s:     lda     #0
        sta     rbt_sidx
@loop:  ldy     rbt_sidx
        lda     (rbt_hl),y
        jsr     rbt_putchar
        inc     rbt_sidx
        lda     rbt_sidx
        cmp     rbt_slen
        bcc     @loop
@done:  rts

; ----------------------------------------------------------------------------
; rbt_print_u8 / rbt_print_u16 - print A / rbt_hl as decimal (no leading zeros)
; ----------------------------------------------------------------------------
rbt_print_u8:
        sta     rbt_hl
        lda     #0
        sta     rbt_hl+1
rbt_print_u16:
        lda     #0
        sta     rbt_pstart      ; bit7 = printing has started
        lda     #<10000
        sta     rbt_de
        lda     #>10000
        sta     rbt_de+1
        jsr     rbt_prdiv
        lda     #<1000
        sta     rbt_de
        lda     #>1000
        sta     rbt_de+1
        jsr     rbt_prdiv
        lda     #<100
        sta     rbt_de
        lda     #>100
        sta     rbt_de+1
        jsr     rbt_prdiv
        lda     #<10
        sta     rbt_de
        lda     #>10
        sta     rbt_de+1
        jsr     rbt_prdiv
        lda     #1
        sta     rbt_de
        lda     #0
        sta     rbt_de+1
        lda     #$80            ; units digit always prints
        sta     rbt_pstart
        jsr     rbt_prdiv
        rts

; rbt_prdiv - one decimal digit: count rbt_de subtractions from rbt_hl.
rbt_prdiv:
        ldx     #0
@dl:    jsr     rbt_cmp16       ; C = 1 iff hl >= de
        bcc     @show
        jsr     rbt_sub16
        inx
        jmp     @dl
@show:  txa
        bne     @dig
        bit     rbt_pstart
        bpl     @done           ; leading zero, suppress
@dig:   lda     #$80
        sta     rbt_pstart
        txa
        ora     #'0'
        jsr     rbt_putchar
@done:  rts

; ----------------------------------------------------------------------------
; rbt_ink / rbt_paper / rbt_bright / rbt_flash - modify rbt_attr / $D021.
; A = value. C64 colour RAM is a nibble per cell: INK picks the nibble,
; BRIGHT adds 8 (lighter variant), FLASH sets bit7 -> reverse video.
; PAPER is the global background $D021 — C64 text cells have no per-cell
; background, so it takes effect immediately.
; ----------------------------------------------------------------------------
rbt_ink:
        and     #$0f
        sta     rbt_t0
        lda     rbt_attr
        and     #$f0
        ora     rbt_t0
        sta     rbt_attr
        rts

rbt_paper:
        and     #$0f
        jsr     rbt_mapio       ; preserves A
        sta     $d021
        jsr     rbt_maprun
        sta     rbt_papn        ; bitmap matrix pairs ink<<4 with this
        rts

rbt_bright:
        and     #1
        beq     @off
        lda     rbt_attr
        ora     #$08
        bne     @set            ; always taken
@off:   lda     rbt_attr
        and     #$f7
@set:   sta     rbt_attr
        rts

rbt_flash:
        and     #1
        beq     @off
        lda     rbt_attr
        ora     #$80
        bne     @set            ; always taken
@off:   lda     rbt_attr
        and     #$7f
@set:   sta     rbt_attr
        rts

; ----------------------------------------------------------------------------
; rbt_fillattr - fill a cell rectangle with the current colours.
; Text mode: colour RAM nibbles at $D800. Bitmap mode: the hires colour
; matrix at $7C00 holds ink<<4|paper per cell. In: B=x, C=y, D=w, E=h.
; ----------------------------------------------------------------------------
rbt_fillattr:
        lda     rbt_e
        beq     @done
        ; base hi + fill byte by screen mode
        ldx     #$d8
        lda     rbt_attr
        and     #$0f
        ldy     rbt_smode
        beq     @cfg
        ldx     #$7c            ; hires matrix at $7C00
        asl                     ; ink nibble -> hi nibble
        asl
        asl
        asl
        ora     rbt_papn
@cfg:   stx     rbt_t1          ; base hi ($D8/$7C)
        sta     rbt_t0          ; fill byte
        lda     rbt_t1
        cmp     #$d8
        bne     @row            ; $7C00 hires matrix is ordinary RAM
        jsr     rbt_mapio       ; $D800 colour RAM is in the I/O window
@row:   ; rbt_ptr = base + y*40 + x
        lda     rbt_c
        sta     rbt_ptr
        lda     #0
        sta     rbt_ptr+1
        asl     rbt_ptr         ; y*2
        rol     rbt_ptr+1
        asl     rbt_ptr         ; y*4
        rol     rbt_ptr+1
        asl     rbt_ptr         ; y*8
        rol     rbt_ptr+1
        lda     rbt_ptr
        sta     rbt_t2          ; stash y*8
        lda     rbt_ptr+1
        sta     rbt_t2+1
        asl     rbt_ptr         ; y*16
        rol     rbt_ptr+1
        asl     rbt_ptr         ; y*32
        rol     rbt_ptr+1
        clc
        lda     rbt_ptr         ; y*40
        adc     rbt_t2
        sta     rbt_ptr
        lda     rbt_ptr+1
        adc     rbt_t2+1
        sta     rbt_ptr+1
        clc
        lda     rbt_ptr
        adc     rbt_b
        sta     rbt_ptr
        lda     rbt_ptr+1
        adc     rbt_t1          ; base hi ($D8/$7C)
        sta     rbt_ptr+1
        ; fill rbt_d cells
        lda     rbt_t0
        ldy     #0
@fc:    sta     (rbt_ptr),y
        iny
        cpy     rbt_d
        bcc     @fc
        inc     rbt_c
        dec     rbt_e
        bne     @row
        lda     rbt_t1
        cmp     #$d8
        bne     @done
        jsr     rbt_maprun
@done:  rts
''',
    'core': r'''
; ============================================================================
; rbt_core - Rainbow runtime core (Commodore 64, ca65)
; Entry point, frame sync, pause, border, cls, RNG, waitkey, 16-bit helpers.
;
; Virtual-register convention (zero page): rbt_hl/rbt_de/rbt_bc are the
; 16-bit pairs the Z80 runtime uses HL/DE/BC for; rbt_b..rbt_e are the byte
; argument registers. BYTE expressions evaluate into A, UINT/INT into rbt_hl.
; The kernal IRQ stays enabled (keyboard scan + jiffy clock); nothing below
; may install its own IRQ yet — the SID/multiplexer modules will take it over.
; ============================================================================
;
; Text-mode VIC layout. C64: bank 3 ($C000-$CFFF) — plain RAM for both CPU
; and VIC with no chargen-ROM window and no BASIC-ROM shadow, so it works
; for every media type (PRG, tape, disk and a 16K cart at $8000) and can
; never collide with a program image at $0801+: screen $C400, SPRPTR $C7F8,
; charset $C800 (tile glyphs $CC00+), sprite pool $CA00. Bank 3 has no
; chargen window so rbt_start seeds charset RAM from the ROM at $D000.
; C128 keeps bank 0 — its programs link at $4000+ so $0400/$3800/$3A00
; can never collide, and BASIC-hi lives in bank 3's window.
.if RBT_C128
RBT_SCRN        = $0400         ; screen matrix base
RBT_CSET        = $3800         ; charset RAM base
RBT_SPPT        = $07f8         ; sprite-pointer table (screen + $3f8)
RBT_D018T       = $1e           ; $D018: screen $0400 + charset $3800
RBT_D018I       = $14           ; boot value: charset = ROM chargen $1000
RBT_POOLH       = $3a           ; sprite pool page (inside charset tail)
RBT_POOLP       = $e8           ; its SPRPTR value
RBT_BANK        = $03           ; $DD00 bits: VIC bank 0
.else
RBT_SCRN        = $c400
RBT_CSET        = $c800
RBT_SPPT        = $c7f8
RBT_D018T       = $12           ; $D018: screen $C400 + charset $C800
RBT_D018I       = $12           ; bank 3 has no chargen window — same value
RBT_POOLH       = $ca
RBT_POOLP       = $28           ; $CA00>>6
RBT_BANK        = $00           ; VIC bank 3
.endif
RBT_CDELTA      = $d800-RBT_SCRN ; screen -> colour RAM offset

        .zeropage

rbt_hl:         .res 2          ; virtual HL (16-bit exprs / pointers)
rbt_de:         .res 2          ; virtual DE
rbt_bc:         .res 2          ; virtual BC (div args, IN/OUT addresses)
rbt_b:          .res 1          ; byte arg/scratch regs (Z80 B,C,D,E roles)
rbt_c:          .res 1
rbt_d:          .res 1
rbt_e:          .res 1
rbt_t0:         .res 1          ; scratch temps
rbt_t1:         .res 1
rbt_t2:         .res 2          ; scratch word (putchar/fillattr row math —
                                ;  must NOT alias pstart/slen: print_u16
                                ;  and print_str hold those across calls)
rbt_ptr:        .res 2          ; scratch pointer
rbt_pstart:     .res 1          ; print leading-zero flag
rbt_slen:       .res 1          ; string length temp
rbt_sidx:       .res 1          ; string index temp

        .code

; ----------------------------------------------------------------------------
; c128 MMU windows. The C128 can't map I/O and RAM at $4000+ together:
;   $0F = RAM $4000-$BFFF + kernal (mainline map; no I/O)
;   $0E = I/O + kernal (ROM at $4000; the $FF17 IRQ trampoline stays
;        mapped, so these windows need no SEI)
;   $3E = I/O + RAM $4000+ but no kernal (IRQ vector trampoline is gone —
;        only safe inside SEI or the IRQ handler itself)
;   $00 = all ROM + I/O (kernal service calls)
; ----------------------------------------------------------------------------
rbt_mapio:
        .if RBT_C128
        pha
        lda     #$0e
        sta     $ff00
        pla
        .endif
        rts

rbt_maprun:
        .if RBT_C128
        pha
        lda     #$0f
        sta     $ff00
        pla
        .endif
        rts

; ----------------------------------------------------------------------------
; rbt_start - entry (the BASIC SYS stub jumps here)
; ----------------------------------------------------------------------------
rbt_start:
        .if RBT_C128
        lda     #$0f
        sta     $ff00           ; mainline map: RAM $4000-$BFFF + kernal
        jsr     rbt_mapio       ; $d018 write needs the I/O window
        ; screen matrix $0400 + ROM chargen $1000 (VIC always sees the
        ; character ROM at $1000 in bank 0) — $D018 = screen<<4 | charset<<1
        lda     #$14
        sta     $d018
        sta     rbt_d018        ; keep the text-mode shadow in sync
        .else
        ; VIC bank 3 — the whole text layout lives above the program.
        ; Bank 3 has no chargen-ROM window, so seed charset RAM from the
        ; ROM at $D000 before any text is drawn. A cart boot can reach
        ; us before the kernal's IOINIT ran: force the 6510 DDR ($00)
        ; and map ($01) to the runtime's expected state first, or the
        ; I/O writes below may land in RAM instead of the chips.
        lda     $00
        ora     #$2f            ; kernal RAMTAS default: cfg+cassette out
        sta     $00
        lda     #$37            ; kernal+BASIC in, I/O mapped
        sta     $01
        lda     $dd02
        ora     #$03
        sta     $dd02
        lda     #$ff            ; CIA1 too: port A drives the keyboard
        sta     $dc02           ; columns, port B reads the rows —
        lda     #$00            ; without IOINIT both are inputs and no
        sta     $dc03           ; key ever registers.
        lda     $dd00
        and     #$fc
        ora     #RBT_BANK
        sta     $dd00
        lda     #RBT_D018T
        sta     $d018
        sta     rbt_d018        ; keep the text-mode shadow in sync
        jsr     rbt_chargen
        .endif
        ; DEN on / 25 rows / text yscroll, 40 cols / MCM off — cartridge
        ; boot can reach us before the kernal's video init ran, so the
        ; display may still be blanked.
        lda     #$1b
        sta     $d011
        lda     #$c8
        sta     $d016
        .if RBT_C128
        jsr     rbt_maprun
        .endif
        jsr     rb_main         ; user program entry (MAIN:)
rbt_end:
        jsr     rbt_sfx_drain
        jsr     rbt_rwait
        jsr     rbt_hook_frame
        jmp     rbt_end         ; program end: idle forever

.if !RBT_C128
; ----------------------------------------------------------------------------
; rbt_chargen - copy the chargen ROM ($D000-$D7FF) into charset RAM at
; RBT_CSET. Bank 3 has no chargen window, so text can't render until this
; runs — rbt_start does it once at boot.
; ----------------------------------------------------------------------------
rbt_chargen:
        sei
        lda     #$33            ; CHAREN=0 with LORAM+HIRAM held: chargen
        sta     $01             ; ROM visible at $D000 (saved $01 may be
                                ; a non-ROM map on a pre-kernal boot)
        lda     #$00
        sta     rbt_ptr
        sta     rbt_hl
        lda     #$d0
        sta     rbt_ptr+1
        lda     #>RBT_CSET
        sta     rbt_hl+1
        ldx     #8              ; 8 pages = full 256-glyph upper-case set
@pg:    ldy     #0
@cp:    lda     (rbt_ptr),y
        sta     (rbt_hl),y
        iny
        bne     @cp
        inc     rbt_ptr+1
        inc     rbt_hl+1
        dex
        bne     @pg
        lda     #$37            ; runtime map: kernal+BASIC in, I/O on
        sta     $01
        cli
        rts
.endif

; ----------------------------------------------------------------------------
; rbt_rwait - wait for raster line 250 (once per frame, edge-safe)
; ----------------------------------------------------------------------------
rbt_rwait:
        jsr     rbt_mapio       ; $d012 lives in the I/O window
@w1:    lda     $d012
        cmp     #$fa
        beq     @w1             ; already on it — wait for it to pass
@w2:    lda     $d012
        cmp     #$fa
        bne     @w2
        jmp     rbt_maprun      ; tail: restores the mainline map, rts

; ----------------------------------------------------------------------------
; rbt_vsync - wait one frame
; ----------------------------------------------------------------------------
rbt_vsync:
        jsr     rbt_sfx_drain
        jsr     rbt_rwait
        jsr     rbt_hook_frame
        rts

; ----------------------------------------------------------------------------
; rbt_pause - pause for rbt_b frames (0 waits for a keypress)
; ----------------------------------------------------------------------------
rbt_pause:
        jsr     rbt_sfx_drain
        lda     rbt_b
        beq     rbt_waitkey
        tax
@ploop: jsr     rbt_rwait
        jsr     rbt_hook_frame
        dex
        bne     @ploop
        rts

; ----------------------------------------------------------------------------
; rbt_waitkey - block until any key is pressed (frame-paced so the music
; hook keeps ticking). The matrix probe is SEI-guarded because the kernal
; IRQ writes $DC00 for its own scan.
; ----------------------------------------------------------------------------
rbt_waitkey:
        jsr     rbt_sfx_drain
@wk:    jsr     rbt_rwait
        jsr     rbt_hook_frame
        sei
        jsr     rbt_mapio
        lda     #0
        sta     $dc00           ; select all columns
        lda     $dc01
        jsr     rbt_maprun
        cli
        eor     #$ff
        beq     @wk
@rel:   sei                     ; wait for release
        jsr     rbt_mapio
        lda     #0
        sta     $dc00
        lda     $dc01
        jsr     rbt_maprun
        cli
        eor     #$ff
        bne     @rel
        rts

; ----------------------------------------------------------------------------
; rbt_border - set border to A (0-15)
; ----------------------------------------------------------------------------
rbt_border:
        and     #$0f
        jsr     rbt_mapio       ; preserves A
        sta     $d020
        jmp     rbt_maprun      ; tail: restore map + rts

; ----------------------------------------------------------------------------
; rbt_scrmode - screen mode select (A = mode).
;   0 = text: VIC bank 0, matrix $0400, charset per rbt_d018
;   1 = hires bitmap: VIC bank 1 ($4000), 8KB bitmap at $4000, colour
;       matrix at $7C00 (fg<<4|bg per cell), sprite pool moves to $7800
; Lives in core so MODE works without the pixel module; the sprite mux
; picks the pool base up from rbt_sppool/rbt_spptrb and PLOT/SHOWPIC
; come with the pixel module.
; ----------------------------------------------------------------------------
rbt_scrmode:
        and     #1
        cmp     rbt_smode
        beq     @done
        sta     rbt_smode
        tax                     ; flags don't survive sta; test A via X
        bne     @bmp
        ; mode 0: text screen
        sei
        jsr     rbt_mapio
        lda     $dd00
        and     #$fc
        ora     #RBT_BANK       ; C64 %00 = bank 3, C128 %11 = bank 0
        sta     $dd00
        lda     $d011
        and     #$df            ; bitmap off
        sta     $d011
        lda     rbt_d018
        sta     $d018
        jsr     rbt_maprun
        lda     #RBT_POOLH
        sta     rbt_sppool
        lda     #RBT_POOLP
        sta     rbt_spptrb
        cli
        rts
@bmp:   ; mode 1: hires bitmap in bank 1
        sei
        jsr     rbt_mapio
        lda     $dd00
        and     #$fc
        ora     #$02            ; %10 = VIC bank 1 ($4000-$7FFF)
        sta     $dd00
        lda     $d011
        ora     #$20            ; bitmap on
        sta     $d011
        lda     #$f0            ; matrix offset $3C00 ($7C00), bitmap at
        sta     $d018           ;  bank offset 0 ($4000)
        jsr     rbt_maprun
        lda     #$78
        sta     rbt_sppool
        lda     #$e0
        sta     rbt_spptrb
        cli
@done:  rts

; ----------------------------------------------------------------------------
; rbt_cls - clear screen. Text mode: spaces + colour RAM, home cursor.
; Bitmap mode: 8000B bitmap to 0, matrix to (ink<<4)|paper.
; ----------------------------------------------------------------------------
rbt_cls:
        lda     rbt_smode
        beq     @text
        jmp     _cls_bmp
@text:  lda     #$20
        ldx     #0
@l1:    sta     RBT_SCRN,x
        sta     RBT_SCRN+$100,x
        sta     RBT_SCRN+$200,x
        inx
        bne     @l1
        ldx     #0
@l2:    sta     RBT_SCRN+$300,x ; last partial page (the sprite pointers
        inx                     ; at RBT_SPPT are left alone)
        cpx     #232
        bcc     @l2
        jsr     rbt_mapio       ; colour RAM $d800+ is in the I/O window
        lda     rbt_attr
        and     #$0f
        ldx     #0
@c1:    sta     $d800,x
        sta     $d900,x
        sta     $da00,x
        inx
        bne     @c1
        ldx     #0
@c2:    sta     $db00,x
        inx
        cpx     #232
        bcc     @c2
        jsr     rbt_maprun
        lda     #0
        sta     rbt_col
        sta     rbt_row
        rts

; _cls_bmp - bitmap-mode clear: bitmap $4000-$5F3F to 0, matrix $7C00 to
; (ink<<4)|paper, home cursor.
_cls_bmp:
        lda     #0
        ldx     #$40
        sta     rbt_ptr
        stx     rbt_ptr+1       ; ptr = $4000
        ldx     #$1f            ; 31 full pages + 64 bytes = 8000
        ldy     #0
@p:     sta     (rbt_ptr),y
        iny
        bne     @p
        inc     rbt_ptr+1
        dex
        bne     @p
        ldy     #63
@t:     sta     (rbt_ptr),y
        dey
        bpl     @t
        lda     rbt_attr        ; matrix byte = ink nibble<<4 | paper
        and     #$0f
        asl
        asl
        asl
        asl
        ora     rbt_papn
        ldx     #0
        stx     rbt_ptr
        ldx     #$7c
        stx     rbt_ptr+1       ; ptr = $7C00 matrix
        ldx     #3              ; 3 pages + 232 = 1000
        ldy     #0
@p2:    sta     (rbt_ptr),y
        iny
        bne     @p2
        inc     rbt_ptr+1
        dex
        bne     @p2
        ldy     #0
@t2:    sta     (rbt_ptr),y
        iny
        cpy     #232
        bne     @t2
        lda     #0
        sta     rbt_col
        sta     rbt_row
        rts

; ----------------------------------------------------------------------------
; rbt_rnd8 - 8-bit Galois LFSR (same tap as the ZX runtime). Out: A
; ----------------------------------------------------------------------------
rbt_rnd8:
        lda     rbt_seed
        asl     a
        bcc     @no_xor
        eor     #$1d
@no_xor:
        sta     rbt_seed
        rts

; ----------------------------------------------------------------------------
; rbt_mod8 - A = A mod rbt_b (unsigned)
; ----------------------------------------------------------------------------
rbt_mod8:
@dl:    cmp     rbt_b
        bcc     @done
        sbc     rbt_b           ; carry known set: cmp left A >= rbt_b
        jmp     @dl
@done:  rts

; ----------------------------------------------------------------------------
; 16-bit virtual-register helpers
; (rbt_hl pushes/pops are emitted inline by the compiler — a subroutine
; can't push data and RTS: the pushed bytes would sit above the return
; address and rts would pop the data as PC)
; ----------------------------------------------------------------------------

; rbt_xhlde - swap rbt_hl <-> rbt_de (the Z80 `ex de,hl` idiom)
rbt_xhlde:
        ldx     rbt_hl
        lda     rbt_de
        sta     rbt_hl
        stx     rbt_de
        ldx     rbt_hl+1
        lda     rbt_de+1
        sta     rbt_hl+1
        stx     rbt_de+1
        rts

; rbt_cmp16 - compare rbt_hl (left) vs rbt_de (right).
; Out flags: C = 1 iff hl >= de, Z = 1 iff equal — the same contract a
; Z80 `sbc hl,de` gives the conditional-jump code (with carry inverted,
; which the emitter accounts for).
; ----------------------------------------------------------------------------
rbt_cmp16:
        lda     rbt_hl+1
        cmp     rbt_de+1
        bne     @done           ; high bytes decide
        lda     rbt_hl
        cmp     rbt_de
@done:  rts

; rbt_sub16 - rbt_hl = rbt_hl - rbt_de
; ----------------------------------------------------------------------------
rbt_sub16:
        sec
        lda     rbt_hl
        sbc     rbt_de
        sta     rbt_hl
        lda     rbt_hl+1
        sbc     rbt_de+1
        sta     rbt_hl+1
        rts

; ----------------------------------------------------------------------------
; data
; ----------------------------------------------------------------------------
rbt_seed:        .word $ace1
rbt_dataptr:     .word 0         ; READ pointer (set to rbd_data by compiler)
rbt_col:         .byte 0         ; PRINT cursor column (charset)
rbt_row:         .byte 0         ; PRINT cursor row (charset)
rbt_over:        .byte 0         ; 0 = normal, 1 = reverse-video print
rbt_attr:        .byte $01       ; current colour nibble (white); bit7 = flash
                                ; (rbt_cls fills colour RAM with the nibble;
                                ;  INK/PAPER/BRIGHT/FLASH update it)
rbt_papn:        .byte $00       ; paper colour nibble (bitmap matrix /
                                ;  border colour pair for hires cells)
rbt_smode:       .byte 0         ; 0 = text, 1 = hires bitmap (rbt_scrmode)
rbt_d018:        .byte RBT_D018I ; shadow of $D018 in text mode — rbt_scrmode
                                ;  restores it on MODE 0 (fset/TILESET keep it
                                ;  in sync with their charset choice)
rbt_sppool:      .byte RBT_POOLH ; hi byte of the sprite pool in the active
                                ;  VIC bank ($CA00 text / $7800 bitmap)
rbt_spptrb:      .byte RBT_POOLP ; SPRPTR base for that pool ($28 / $1E0)
''',
    'diskload': r'''
; rbt_diskload - stream an asset file off disk into RAM via the kernal.
; COPYBANK "name", dest lowers to this on cbm: the 1541 file's first two
; bytes (its stored load address) are skipped because the secondary
; address is 0, so the payload lands at the caller's dest.
;
; in:  rbt_hl = ptr to a length-prefixed PETSCII filename
;      rbt_de = load address
; out: carry clear = ok, carry set = kernal/device error
; clobbers a,x,y (and anything the kernal uses)

rbt_diskload:
        sei                     ; c128: an IRQ mid-LOAD can land in the
                                ; monitor under the kernal's transient
                                ; MMU configs — hold interrupts off for
                                ; the whole kernal call
        .if RBT_C128
        lda     #$00
        sta     $ff00           ; kernal needs its all-ROM + I/O map; our
                                ; $0F mainline map hides I/O entirely
        .endif
        lda     #1              ; logical file number
        ldx     #8              ; device 8
        ldy     #0              ; secondary 0: LOAD uses the X/Y address
        jsr     $ffba           ; SETLFS
        ldy     #0
        lda     (rbt_hl),y      ; name length
        ldx     rbt_hl          ; name ptr = rbt_hl + 1
        inx
        bne     @hi
        ldy     rbt_hl+1
        iny
        jmp     @setnam
@hi:    ldy     rbt_hl+1
@setnam:
        jsr     $ffbd           ; SETNAM (a=len, x/y=name ptr)
        lda     #0              ; LOAD (not VERIFY)
        ldx     rbt_de
        ldy     rbt_de+1
        jsr     $ffd5           ; kernal LOAD
        .if RBT_C128
        lda     #$0f
        sta     $ff00           ; back to the mainline map
        .endif
        cli
        rts
''',
    'input': r'''
; ============================================================================
; rbt_input - CIA1 keyboard matrix + joystick (Commodore 64, ca65)
;
; KEY(n)/INKEY codes are ZX-layout codes (row*8 + bit, same numbers the
; Spectrum runtime uses) so sources port unchanged — rbt_key maps them
; onto the C64 matrix via rbt_zx2cbm. Matrix: driving ~(1<<col) onto
; $DC00 (port A) grounds that column; $DC01 (port B) reads the 8 row
; lines active-low:
;   col 0: DEL RETURN CUR-RL F7 F1 F3 F5 CUR-UD
;   col 1: 3 W A 4 Z S E LSHIFT
;   col 2: 5 R D 6 C F T X
;   col 3: 7 Y G 8 B H U V
;   col 4: 9 I J 0 M K O N
;   col 5: + P L - . : @ ,
;   col 6: £ * ; HOME RSHIFT = ^ /
;   col 7: 1 <- CTRL 2 SPACE C= Q STOP
;
; Port pokes are SEI-guarded: the kernal IRQ drives $DC00 for its own scan.
; ============================================================================

        .code

rbt_joymode:     .byte 0         ; kept for source compat; C64 JOY always
                                ; reads port 2 ($DC00) regardless of mode

; ----------------------------------------------------------------------------
; rbt_anykey - A = 1 if any matrix key is pressed
; ----------------------------------------------------------------------------
rbt_anykey:
        sei
        jsr     rbt_mapio
        lda     #0
        sta     $dc00           ; all columns selected
        lda     $dc01
        jsr     rbt_maprun
        cli
        eor     #$ff
        beq     @no
        lda     #1
@no:    rts

; ----------------------------------------------------------------------------
; rbt_key - test one key. In: A = ZX code (row<<3 | bit). Out: A = 1/0.
; ----------------------------------------------------------------------------
rbt_key:
        tax
        lda     rbt_zx2cbm,x
        bmi     @no             ; no C64 equivalent -> never pressed
        sta     rbt_t0          ; C64 matrix code (col<<3 | rowbit)
        and     #7
        sta     rbt_t1          ; row bit index
        lda     rbt_t0
        lsr     a
        lsr     a
        lsr     a               ; column 0-7
        tax
        lda     #1
@m:     dex
        bmi     @sel
        asl     a
        jmp     @m
@sel:   eor     #$ff            ; active-low column mask
        sei
        jsr     rbt_mapio
        sta     $dc00
        lda     $dc01
        jsr     rbt_maprun
        cli
        ; shift bit (row index) into carry
        ldx     rbt_t1
        inx
@sh:    lsr     a
        dex
        bne     @sh
        lda     #0
        bcs     @np             ; bit was 1 -> not pressed
        lda     #1
@np:    rts
@no:    lda     #0
        rts

; ----------------------------------------------------------------------------
; rbt_inkey - scan matrix, return ASCII of first pressed key (or 0)
; ----------------------------------------------------------------------------
rbt_inkey:
        lda     #0
        sta     rbt_t1          ; code
@scan:  lda     rbt_t1
        jsr     rbt_key
        bne     @found
        inc     rbt_t1
        lda     rbt_t1
        cmp     #64
        bcc     @scan
        lda     #0
        rts
@found: ldx     rbt_t1
        lda     rbt_keymap,x
        rts

; ----------------------------------------------------------------------------
; rbt_joy - read joystick port 2 ($DC00). Port A is normally an output for
; the keyboard scan, so DDRA is switched to input, read, restored.
; Out: A = bitmask %000FUDLR (fire,up,down,left,right)
; ----------------------------------------------------------------------------
rbt_joy:
        sei
        jsr     rbt_mapio
        lda     $dc02           ; DDRA
        pha
        lda     #0
        sta     $dc02           ; port A -> input
        lda     $dc00           ; bits: 0=up 1=down 2=left 3=right 4=fire
        tax                     ; stash in X via stack
        pla
        sta     $dc02
        jsr     rbt_maprun
        cli
        txa
        eor     #$ff
        and     #$1f            ; raw: %000FRLDU (active bits now 1)
        ; rearrange to %000FUDLR: up bit0->3, down bit1->2 (stays),
        ; left bit2->1, right bit3->0, fire bit4 stays
        sta     rbt_t0
        and     #$10            ; fire already in place
        sta     rbt_t1
        lda     rbt_t0
        and     #1              ; up -> bit3
        asl     a
        asl     a
        asl     a
        ora     rbt_t1
        sta     rbt_t1
        lda     rbt_t0
        and     #2              ; down -> bit2 (already right)
        ora     rbt_t1
        sta     rbt_t1
        lda     rbt_t0
        and     #4              ; left -> bit1
        lsr     a
        ora     rbt_t1
        sta     rbt_t1
        lda     rbt_t0
        and     #8              ; right -> bit0
        lsr     a
        lsr     a
        lsr     a
        ora     rbt_t1
        rts

; ----------------------------------------------------------------------------
; ZX code -> C64 matrix code (col*8 + rowbit; $ff = no such key).
; ZX codes are row*8+bit over the Spectrum layout: row0 SHIFT-ZXCV,
; row1 A-G, row2 Q-T, row3 1-5, row4 0/9/8/7/6, row5 P-O-I-U-Y,
; row6 ENTER-L-K-J-H, row7 SPACE-SYM-M-N-B. ZX SYMBOL SHIFT maps to C=.
; ----------------------------------------------------------------------------
rbt_zx2cbm:
        .byte   15,12,23,20,31,$ff,$ff,$ff    ; row 0: SHIFT Z X C V
        .byte   10,13,18,21,26,$ff,$ff,$ff    ; row 1: A S D F G
        .byte   62,9,14,17,22,$ff,$ff,$ff     ; row 2: Q W E R T
        .byte   56,59,8,11,16,$ff,$ff,$ff     ; row 3: 1 2 3 4 5
        .byte   35,32,27,24,19,$ff,$ff,$ff    ; row 4: 0 9 8 7 6
        .byte   41,38,33,30,25,$ff,$ff,$ff    ; row 5: P O I U Y
        .byte   1,42,37,34,29,$ff,$ff,$ff     ; row 6: ENTER L K J H
        .byte   60,61,36,39,28,$ff,$ff,$ff    ; row 7: SPACE SYM M N B

; ----------------------------------------------------------------------------
; ZX code -> ASCII map (0 = no ascii) — same layout as the ZX runtime's
; so INKEY returns identical values on every platform.
; ----------------------------------------------------------------------------
rbt_keymap:
        .byte   0,'z','x','c','v',0,0,0       ; row 0
        .byte   'a','s','d','f','g',0,0,0     ; row 1
        .byte   'q','w','e','r','t',0,0,0     ; row 2
        .byte   '1','2','3','4','5',0,0,0     ; row 3
        .byte   '0','9','8','7','6',0,0,0     ; row 4
        .byte   'p','o','i','u','y',0,0,0     ; row 5
        .byte   13,'l','k','j','h',0,0,0      ; row 6
        .byte   ' ',0,'m','n','b',0,0,0       ; row 7
''',
    'math': r'''
; ============================================================================
; rbt_math - arithmetic helpers for 8/16-bit ops (Commodore 64, ca65)
; Same contracts as the shared Z80 module, on the virtual registers.
; ============================================================================

        .code

; ----------------------------------------------------------------------------
; rbt_mul8 - rbt_hl = rbt_d * rbt_e (unsigned, low 16 bits)
; ----------------------------------------------------------------------------
rbt_mul8:
        lda     #0
        sta     rbt_hl
        sta     rbt_hl+1
        ldx     #8
@ml:    asl     rbt_hl          ; hl <<= 1
        rol     rbt_hl+1
        asl     rbt_d           ; multiplier bit -> C
        bcc     @m0
        clc
        lda     rbt_hl
        adc     rbt_e
        sta     rbt_hl
        bcc     @m0
        inc     rbt_hl+1
@m0:    dex
        bne     @ml
        rts

; ----------------------------------------------------------------------------
; rbt_divmod8 - in: A = dividend, rbt_b = divisor.
; out: A = quotient, rbt_b = remainder
; ----------------------------------------------------------------------------
rbt_divmod8:
        sta     rbt_t0          ; dividend
        lda     rbt_b
        beq     @dz             ; divisor 0: return q=0, r=0
        lda     #0
        sta     rbt_t1          ; quotient
        lda     rbt_t0
@dl:    cmp     rbt_b
        bcc     @done
        sbc     rbt_b           ; carry known set here
        inc     rbt_t1
        jmp     @dl
@done:  sta     rbt_b           ; remainder
        lda     rbt_t1          ; quotient
        rts
@dz:    lda     #0
        sta     rbt_b
        rts                     ; A = 0

; ----------------------------------------------------------------------------
; rbt_mul16 - rbt_hl = rbt_de * rbt_hl (low 16 bits; signed-safe)
; ----------------------------------------------------------------------------
rbt_mul16:
        lda     rbt_hl
        sta     rbt_bc
        lda     rbt_hl+1
        sta     rbt_bc+1        ; rbt_bc = multiplier
        lda     #0
        sta     rbt_hl
        sta     rbt_hl+1
        ldx     #16
@ml:    asl     rbt_hl
        rol     rbt_hl+1        ; product <<= 1
        asl     rbt_bc
        rol     rbt_bc+1        ; multiplier top bit -> C
        bcc     @m0
        clc
        lda     rbt_hl
        adc     rbt_de
        sta     rbt_hl
        lda     rbt_hl+1
        adc     rbt_de+1
        sta     rbt_hl+1
@m0:    dex
        bne     @ml
        rts

; ----------------------------------------------------------------------------
; rbt_divmod16 - unsigned: rbt_bc / rbt_de -> rbt_bc = quotient,
; rbt_hl = remainder
; ----------------------------------------------------------------------------
rbt_divmod16:
        lda     rbt_de
        ora     rbt_de+1
        bne     @go
        lda     #0              ; divisor 0: q=0, r=0
        sta     rbt_bc
        sta     rbt_bc+1
        sta     rbt_hl
        sta     rbt_hl+1
        rts
@go:    lda     #0
        sta     rbt_hl          ; remainder
        sta     rbt_hl+1
        ldx     #16
@dl:    asl     rbt_bc          ; dividend <<= 1, top bit -> C
        rol     rbt_bc+1
        rol     rbt_hl          ; rem <<= 1 + C
        rol     rbt_hl+1
        ; rem >= divisor? (compare rbt_hl vs rbt_de)
        lda     rbt_hl+1
        cmp     rbt_de+1
        bne     @cmp
        lda     rbt_hl
        cmp     rbt_de
@cmp:   bcc     @nxt            ; rem < de -> quotient bit 0
        sec
        lda     rbt_hl
        sbc     rbt_de
        sta     rbt_hl
        lda     rbt_hl+1
        sbc     rbt_de+1
        sta     rbt_hl+1
        inc     rbt_bc          ; quotient bit 1 (bit0 was just shifted 0)
@nxt:   dex
        bne     @dl
        rts

; ----------------------------------------------------------------------------
; rbt_sdivmod16 - signed: rbt_bc / rbt_de -> rbt_bc = quotient,
; rbt_hl = remainder. Quotient truncates toward zero; remainder takes
; the dividend's sign (same as the Z80 version).
; ----------------------------------------------------------------------------
rbt_sdivmod16:
        lda     #0
        sta     rbt_divsign     ; bit0: result negative
        bit     rbt_bc+1
        bpl     @nnum
        jsr     rbt_negbc
        lda     rbt_divsign
        eor     #1
        sta     rbt_divsign
@nnum:  bit     rbt_de+1
        bpl     @ndiv
        jsr     rbt_negde
        lda     rbt_divsign
        eor     #1
        sta     rbt_divsign
@ndiv:  jsr     rbt_divmod16
        lda     rbt_divsign
        beq     @done
        jsr     rbt_negbc       ; negate quotient
@done:  rts

rbt_divsign:     .byte 0

rbt_negbc:
        sec
        lda     #0
        sbc     rbt_bc
        sta     rbt_bc
        lda     #0
        sbc     rbt_bc+1
        sta     rbt_bc+1
        rts

rbt_negde:
        sec
        lda     #0
        sbc     rbt_de
        sta     rbt_de
        lda     #0
        sbc     rbt_de+1
        sta     rbt_de+1
        rts

; ----------------------------------------------------------------------------
; rbt_neg16 - rbt_hl = -rbt_hl (two's complement)
; ----------------------------------------------------------------------------
rbt_neg16:
        sec
        lda     #0
        sbc     rbt_hl
        sta     rbt_hl
        lda     #0
        sbc     rbt_hl+1
        sta     rbt_hl+1
        rts

; ----------------------------------------------------------------------------
; rbt_abs16 - rbt_hl = |rbt_hl|
; ----------------------------------------------------------------------------
rbt_abs16:
        bit     rbt_hl+1
        bpl     @pos
        jmp     rbt_neg16
@pos:   rts
''',
    'pixel': r'''
; ============================================================================
; rbt_pixel - hires bitmap pixel ops + SHOWPIC (Commodore 64, ca65)
;
; MODE 1 (rbt_scrmode, in core) switches the VIC to bank 1 and hires
; bitmap mode:
;   bitmap        $4000 (8000 bytes, 320x200, 1bpp)
;   colour matrix $7C00 (1000 bytes, fg<<4|bg per 8x8 cell)
;   sprite pool   $7800 (mux relocates automatically via rbt_sppool)
;   sprite ptrs   $7FF8 (matrix+$3F8 — the mux writes both tables)
;
; Logical coords match the other targets: x 0-255, y 0-191, top-left of
; the 320x200 hires area (the CPC port makes the same choice). PLOT/
; POINT/LINE write the bitmap regardless of mode — they're only visible
; in MODE 1.
;
; SHOWPIC "name": .rbc assets are re-encoded by the build to the cbm
; layout — 8000 bitmap bytes (hires y-linear) then 1000 matrix bytes —
; and rbt_showpic switches to bitmap mode and blits them.
; ============================================================================

        .zeropage
rbt_lx:         .res 1          ; LINE endpoint x
rbt_ly:         .res 1          ; LINE endpoint y
rbt_ldx:        .res 1          ; |dx|
rbt_ldy:        .res 1          ; |dy|
rbt_lsx:        .res 1          ; x step (+1/-1)
rbt_lsy:        .res 1          ; y step (+1/-1)
rbt_lerr:       .res 1          ; Bresenham error (signed 8-bit)
rbt_le2:        .res 1          ; 2*err
        .code

; ----------------------------------------------------------------------------
; rbt_pix - pixel address. In: rbt_c = x, rbt_b = y. Out: rbt_ptr =
; bitmap byte, rbt_t1 = bit mask ($80 >> x&7).
; Clobbers A/X, rbt_ptr, rbt_t1, rbt_t2.
;
; addr = $4000 + (y&$F8)*40 + (x&$F8) + (y&7)
; ----------------------------------------------------------------------------
rbt_bitmask:    .byte $80,$40,$20,$10,$08,$04,$02,$01

rbt_pix:
        lda     rbt_b
        and     #$f8            ; t = y&$F8 (0..184)
        sta     rbt_ptr
        lda     #0
        sta     rbt_ptr+1
        asl     rbt_ptr         ; t*8
        rol     rbt_ptr+1
        asl     rbt_ptr
        rol     rbt_ptr+1
        asl     rbt_ptr
        rol     rbt_ptr+1
        lda     rbt_ptr         ; stash t*8
        sta     rbt_t2
        lda     rbt_ptr+1
        sta     rbt_t2+1
        asl     rbt_ptr         ; t*32
        rol     rbt_ptr+1
        asl     rbt_ptr
        rol     rbt_ptr+1
        clc
        lda     rbt_ptr         ; t*32 + t*8 = t*40
        adc     rbt_t2
        sta     rbt_ptr
        lda     rbt_ptr+1
        adc     rbt_t2+1
        sta     rbt_ptr+1
        lda     rbt_c
        and     #$f8            ; + x&$F8
        clc
        adc     rbt_ptr
        sta     rbt_ptr
        bcc     @n1
        inc     rbt_ptr+1
@n1:    lda     rbt_b
        and     #$07            ; + y&7
        clc
        adc     rbt_ptr
        sta     rbt_ptr
        lda     rbt_ptr+1
        adc     #$40            ; + $4000 (carry in from the add)
        sta     rbt_ptr+1
        lda     rbt_c
        and     #$07
        tax
        lda     rbt_bitmask,x
        sta     rbt_t1          ; bit mask
        rts

; ----------------------------------------------------------------------------
; rbt_plot - plot pixel (x=C, y=B). Honours rbt_over (nonzero = invert).
; ----------------------------------------------------------------------------
rbt_plot:
        jsr     rbt_pix
        ldy     #0
        ldx     rbt_over
        beq     @set
        lda     (rbt_ptr),y
        eor     rbt_t1
        jmp     @wr
@set:   lda     (rbt_ptr),y
        ora     rbt_t1
@wr:    sta     (rbt_ptr),y
        rts

; ----------------------------------------------------------------------------
; rbt_point - test pixel (x=C, y=B). Out: A = 1 set, 0 clear
; ----------------------------------------------------------------------------
rbt_point:
        jsr     rbt_pix
        ldy     #0
        lda     (rbt_ptr),y
        and     rbt_t1
        beq     @no
        lda     #1
        rts
@no:    lda     #0
        rts

; ----------------------------------------------------------------------------
; rbt_line - draw a line from (C,B) to (rbt_lx,rbt_ly), Bresenham.
; rbt_over honoured via rbt_plot. err is a signed byte: runs over ~127px
; can quantise but the loop still terminates.
; ----------------------------------------------------------------------------
rbt_line:
        ; dx = |lx - x|, sx = sign
        lda     rbt_lx
        sec
        sbc     rbt_c
        bpl     @dxp
        eor     #$ff
        clc
        adc     #1
@dxp:   sta     rbt_ldx
        lda     rbt_lx
        cmp     rbt_c
        lda     #1
        bcs     @sx
        lda     #$ff
@sx:    sta     rbt_lsx
        ; dy = |ly - y|, sy = sign
        lda     rbt_ly
        sec
        sbc     rbt_b
        bpl     @dyp
        eor     #$ff
        clc
        adc     #1
@dyp:   sta     rbt_ldy
        lda     rbt_ly
        cmp     rbt_b
        lda     #1
        bcs     @sy
        lda     #$ff
@sy:    sta     rbt_lsy
        ; err = dx - dy
        lda     rbt_ldx
        sec
        sbc     rbt_ldy
        sta     rbt_lerr
@loop:  jsr     rbt_plot        ; plot (C,B)
        lda     rbt_lx
        cmp     rbt_c
        bne     @step
        lda     rbt_ly
        cmp     rbt_b
        beq     @done
@step:  lda     rbt_lerr
        asl                     ; e2 = 2*err (signed)
        sta     rbt_le2
        ; x step iff e2 > -dy: skip iff -dy >= e2. Signed compares via
        ; the eor #$80 bias (signed(a)>=signed(b) <=> a^$80 >= b^$80).
        lda     rbt_le2
        eor     #$80
        sta     rbt_t0          ; mem = biased e2
        lda     rbt_ldy
        eor     #$ff
        clc
        adc     #1              ; -dy
        eor     #$80            ; A = biased -dy
        cmp     rbt_t0          ; C iff -dy >= e2
        bcs     @skipx
        lda     rbt_lerr
        sec
        sbc     rbt_ldy         ; err -= dy
        sta     rbt_lerr
        lda     rbt_c
        clc
        adc     rbt_lsx         ; x += sx
        sta     rbt_c
@skipx: ; y step iff e2 < dx: skip iff e2 >= dx (signed)
        lda     rbt_ldx
        eor     #$80
        sta     rbt_t0          ; mem = biased dx
        lda     rbt_le2
        eor     #$80            ; A = biased e2
        cmp     rbt_t0          ; C iff e2 >= dx
        bcs     @skipy
        lda     rbt_lerr
        clc
        adc     rbt_ldx         ; err += dx
        sta     rbt_lerr
        lda     rbt_b
        clc
        adc     rbt_lsy         ; y += sy
        sta     rbt_b
@skipy: jmp     @loop
@done:  rts

; ----------------------------------------------------------------------------
; rbt_showpic - rbt_hl -> cbm screen payload (8000 bitmap + 1000 matrix).
; Switches to hires bitmap mode and blits.
; ----------------------------------------------------------------------------
rbt_showpic:
        lda     #1
        jsr     rbt_scrmode
        ; src -> rbt_ptr, dst $4000 -> rbt_hl
        lda     rbt_hl
        sta     rbt_ptr
        lda     rbt_hl+1
        sta     rbt_ptr+1
        lda     #$00
        sta     rbt_hl
        lda     #$40
        sta     rbt_hl+1
        ldx     #31             ; 31 pages + 64 bytes = 8000
        ldy     #0
@p:     lda     (rbt_ptr),y
        sta     (rbt_hl),y
        iny
        bne     @p
        inc     rbt_ptr+1
        inc     rbt_hl+1
        dex
        bne     @p
        ldy     #63
@t:     lda     (rbt_ptr),y
        sta     (rbt_hl),y
        dey
        bpl     @t
        lda     rbt_ptr         ; src -> matrix bytes (7936 + 64 = 8000)
        clc
        adc     #64
        sta     rbt_ptr
        bcc     @nm
        inc     rbt_ptr+1
@nm:    lda     #$00
        sta     rbt_hl
        lda     #$7c
        sta     rbt_hl+1        ; dst = $7C00 matrix
        ldx     #3              ; 3 pages + 232 = 1000
        ldy     #0
@p2:    lda     (rbt_ptr),y
        sta     (rbt_hl),y
        iny
        bne     @p2
        inc     rbt_ptr+1
        inc     rbt_hl+1
        dex
        bne     @p2
        ldy     #0
@t2:    lda     (rbt_ptr),y
        sta     (rbt_hl),y
        iny
        cpy     #232
        bne     @t2
        rts
''',
    'sfx': r'''
; ============================================================================
; rbt_sfx - Rainbow sound effects via the SID (Commodore 64)
;
; Same queue/drain model as the ZX/CPC engines: SFX queues an effect,
; the next idle point (vsync/pause/waitkey/end via rbt_sfx_drain) plays
; it blocking, so effects land in dead frame time. The effect drives
; SID voice 3 — the "channel steal": if music is running the next .ray
; row simply reasserts the voice's registers.
;
; rbt_sfx       - queue an effect: rbt_hl = step data
; rbt_sfx_drain - play the pending effect now if one is queued
;
; Step format (6 bytes, from encodeRsfCbm):
;   defb len    ; update iterations (0 = end of effect)
;   defb dur    ; delay units between updates (~5 cycles each @ ~1 MHz)
;   defw freq   ; SID frequency register, 16-bit
;   defw slide  ; signed per-iteration delta, 16.8 fixed point
; ============================================================================

        .code

; ----------------------------------------------------------------------------
; rbt_sfx - queue an effect (rbt_hl = step data). Drains a previously
; queued effect first so effects keep call order.
; ----------------------------------------------------------------------------
rbt_sfx:
        lda     rbt_hl
        sta     rbt_sfx_in
        lda     rbt_hl+1
        sta     rbt_sfx_in+1
        jsr     rbt_sfx_drain
        lda     rbt_sfx_in
        sta     rbt_sfx_pending
        lda     rbt_sfx_in+1
        sta     rbt_sfx_pending+1
        rts

; ----------------------------------------------------------------------------
; rbt_sfx_drain - play the queued effect now (blocking); no-op when none
; ----------------------------------------------------------------------------
rbt_sfx_drain:
        lda     rbt_sfx_pending
        ora     rbt_sfx_pending+1
        bne     @have
        jmp     @none
@have:
        ; move pending -> play pointer, clear queue
        lda     rbt_sfx_pending
        sta     z:rbt_sfx_ptr
        lda     rbt_sfx_pending+1
        sta     z:rbt_sfx_ptr+1
        lda     #0
        sta     rbt_sfx_pending
        sta     rbt_sfx_pending+1
        jsr     rbt_mapio               ; SID regs live in the I/O window
        ; voice 3 setup: 50% pulse ($800), fast attack, full sustain
        ; PW hi registers are 4-bit, so $800 needs #$08 not #$80
        lda     #$08
        sta     $d411                   ; PW hi voice 3
        lda     #$09
        sta     $d413                   ; A=0, D=9
        lda     #$f0
        sta     $d414                   ; S=15, R=0
        lda     #$0f
        sta     $d418                   ; master vol: rbt_sid_stop zeroes it
                                        ; when a tune ends — reassert or
                                        ; every effect after it is silent
        lda     #$41                    ; pulse + gate
        sta     $d412
@step:
        ldy     #0
        lda     (rbt_sfx_ptr),y         ; len (0 = end)
        bne     @more
        jmp     @done
@more:
        sta     rbt_sfx_len
        iny
        lda     (rbt_sfx_ptr),y
        sta     rbt_sfx_dur             ; dur
        iny
        lda     (rbt_sfx_ptr),y
        sta     rbt_sfx_fq              ; freq lo
        iny
        lda     (rbt_sfx_ptr),y
        sta     rbt_sfx_fq+1            ; freq hi
        iny
        lda     (rbt_sfx_ptr),y
        sta     rbt_sfx_sl              ; slide frac (16.8, signed)
        iny
        lda     (rbt_sfx_ptr),y
        sta     rbt_sfx_sl+1            ; slide int
        lda     #0
        sta     rbt_sfx_frc             ; freq frac accumulator
        ; ptr += 6
        clc
        lda     z:rbt_sfx_ptr
        adc     #6
        sta     z:rbt_sfx_ptr
        bcc     @iter
        inc     z:rbt_sfx_ptr+1
@iter:
        lda     rbt_sfx_fq              ; freq reg direct (16-bit)
        sta     $d40e                   ; voice 3 freq lo
        lda     rbt_sfx_fq+1
        sta     $d40f
        ; delay: dur x ~5 cycle loop
        ldx     rbt_sfx_dur
@wait:  dex
        bne     @wait
        ; frq:frc += slide (signed 16.8 fixed point, clamp at 0)
        clc
        lda     rbt_sfx_frc
        adc     rbt_sfx_sl
        sta     rbt_sfx_frc
        lda     rbt_sfx_fq
        adc     rbt_sfx_sl+1
        sta     rbt_sfx_fq
        lda     rbt_sfx_fq+1
        bit     rbt_sfx_sl+1
        bpl     @hi
        adc     #$ff                    ; sign-extend negative slide
        jmp     @st
@hi:    adc     #0
@st:    sta     rbt_sfx_fq+1
        bpl     @plen
        lda     #0                      ; undershot -> silence
        sta     rbt_sfx_frc
        sta     rbt_sfx_fq
        sta     rbt_sfx_fq+1
@plen:
        dec     rbt_sfx_len
        bne     @iter
        jmp     @step
@done:
        lda     #0
        sta     $d412                   ; voice 3 gate off
        jsr     rbt_maprun
@none:
        rts

        .zeropage
rbt_sfx_ptr:     .res   2               ; play pointer (indirect)

        .code
rbt_sfx_pending: .res   2               ; queued effect step ptr (0 = none)
rbt_sfx_in:      .res   2               ; incoming ptr across the drain
rbt_sfx_len:     .res   1
rbt_sfx_dur:     .res   1
rbt_sfx_fq:      .res   2               ; current freq reg
rbt_sfx_frc:     .res   1               ; freq fraction accumulator
rbt_sfx_sl:      .res   2               ; slide delta, 16.8 signed
''',
    'sid': r'''
; ============================================================================
; rbt_sid - Rainbow SID music player (Commodore 64)
;
; rbt_sid_start - rbt_hl = song data; starts playback (non-blocking).
; rbt_sid_tick  - advance one frame (auto-called from rbt_rwait callers
;                 via rbt_hook_frame, or explicitly with MUSIC TICK).
; rbt_sid_stop  - stop playback and silence all voices.
;
; Row format (produced by encodeRayCbm / encodeRntCbm — AY rows are
; converted to SID regs at build time):
;   defb dur
;   voice 1: defw freq, defb ctrl
;   voice 2: defw freq, defb ctrl
;   voice 3: defw freq, defb ctrl
;   defw pw                ; shared pulse width (12-bit), written to all
;                          ; three voices — pulse only sounds on those
;                          ; whose ctrl selects the pulse wave
;   defb vol               ; master volume written to $D418
; end marker: defb 0, defw loop-offset-in-rows ($ffff = stop + silence)
; ctrl carries gate+waveform: gate | $10 tri / $20 saw / $40 pulse /
; $80 noise, $00 voice off — auto-mapped from the AY mixer unless the
; .ray row supplies a "wave" name per voice.
; ============================================================================

        .code

; ----------------------------------------------------------------------------
; rbt_sid_start - rbt_hl = song data
; ----------------------------------------------------------------------------
rbt_sid_start:
        lda     rbt_hl
        sta     rbt_sid_base
        sta     z:rbt_sid_pos
        lda     rbt_hl+1
        sta     rbt_sid_base+1
        sta     z:rbt_sid_pos+1
        ; voice setup: 50% pulse width ($800), fast attack / full sustain
        ; PW hi registers are 4-bit, so $800 needs #$08 not #$80
        jsr     rbt_mapio               ; SID regs live in the I/O window
        lda     #$08
        sta     $d403                   ; PW hi voice 1
        sta     $d40a                   ; voice 2
        sta     $d411                   ; voice 3
        lda     #$09                    ; A=0, D=9
        sta     $d405
        sta     $d40c
        sta     $d413
        lda     #$f0                    ; S=15, R=0
        sta     $d406
        sta     $d40d
        sta     $d414
        jsr     rbt_maprun
        lda     #0
        sta     rbt_sid_dur             ; force row load on next tick
        lda     #1
        sta     rbt_sid_on
        rts

; ----------------------------------------------------------------------------
; rbt_sid_stop - stop playback and silence all voices
; ----------------------------------------------------------------------------
rbt_sid_stop:
        lda     #0
        sta     rbt_sid_on
        jsr     rbt_mapio
        sta     $d404                   ; gates off
        sta     $d40b
        sta     $d412
        sta     $d418                   ; master vol
        jmp     rbt_maprun              ; tail: restore map + rts

; ----------------------------------------------------------------------------
; rbt_sid_tick - advance one frame. Called from rbt_hook_frame inside the
; frame-wait loops, which hold live counters in X — preserve all regs.
; ----------------------------------------------------------------------------
rbt_sid_tick:
        pha
        txa
        pha
        tya
        pha
        jsr     rbt_mapio               ; SID regs live in the I/O window
        lda     rbt_sid_on
        bne     @go
        jmp     @ret
@go:
        lda     rbt_sid_dur
        beq     @row
        dec     rbt_sid_dur
        bne     @ret
@row:
        ldy     #0
        lda     (rbt_sid_pos),y         ; dur byte
        beq     @end
        sta     rbt_sid_dur
        iny
        ldx     #0                      ; voice reg offset: 0, 7, 14
@voice:
        lda     (rbt_sid_pos),y         ; freq lo
        sta     $d400,x
        iny
        lda     (rbt_sid_pos),y         ; freq hi
        sta     $d401,x
        iny
        lda     (rbt_sid_pos),y         ; ctrl
        sta     $d404,x
        iny
        txa
        clc
        adc     #7
        tax
        cmp     #21
        bcc     @voice
        lda     (rbt_sid_pos),y         ; pulse width lo (y = 10)
        sta     $d402
        sta     $d409
        sta     $d410
        iny
        lda     (rbt_sid_pos),y         ; pulse width hi (12-bit)
        sta     $d403
        sta     $d40a
        sta     $d411
        iny
        lda     (rbt_sid_pos),y         ; master volume (y = 12)
        sta     $d418
        clc
        lda     z:rbt_sid_pos
        adc     #13
        sta     z:rbt_sid_pos
        bcc     @ret
        inc     z:rbt_sid_pos+1
@ret:
        jsr     rbt_maprun
        pla
        tay
        pla
        tax
        pla
        rts
@end:
        ldy     #1
        lda     (rbt_sid_pos),y         ; loop offset lo -> X
        tax
        iny
        lda     (rbt_sid_pos),y         ; loop offset hi -> Y
        tay
        cpy     #$ff                    ; $ffff -> stop + silence
        bne     @loop
        cpx     #$ff
        beq     @stop
@loop:
        ; pos = base + offset (Y=hi, X=lo)
        txa
        clc
        adc     rbt_sid_base
        sta     z:rbt_sid_pos
        tya
        adc     rbt_sid_base+1
        sta     z:rbt_sid_pos+1
        jmp     @ret
@stop:
        jsr     rbt_sid_stop
        jmp     @ret

        .zeropage
rbt_sid_pos:    .res    2               ; current row pointer (indirect)

        .code
rbt_sid_base:   .res    2               ; song data base
rbt_sid_dur:    .res    1               ; frames left on current row
rbt_sid_on:     .res    1               ; playback active flag
''',
    'spcoll': r'''
; ============================================================================
; rbt_spcoll - sprite <-> tilemap collision bridge (Commodore 64, ca65)
; Requires BOTH the sprite module (rbt_slot) and the tilemap module
; (rbt_tm_* vars, rbt_tm_mapat, rbt_ct_* scratch).
; ============================================================================

        .code

; ----------------------------------------------------------------------------
; rbt_colltile - A = sprite id -> A = flags of first solid tile overlapped
; (0 = none). Cell range comes from the slot's logical pixel bbox; sprite
; cells outside the tile view are skipped, then map coords = camera +
; (cell - view origin), same contract as the ZX engine.
; ----------------------------------------------------------------------------
rbt_colltile:
        jsr     rbt_slot        ; ptr = slot
        ldy     #0
        lda     (rbt_ptr),y
        and     #1
        bne     @live
        jmp     @none           ; inactive -> no collision
@live:
        ; c0 = x>>3, c1 = (x+w-1)>>3
        ldy     #1
        lda     (rbt_ptr),y     ; x
        lsr
        lsr
        lsr
        sta     rbt_ct_c0
        ldy     #1
        lda     (rbt_ptr),y     ; x
        ldy     #3
        clc
        adc     (rbt_ptr),y     ; x+w (w<=24, x<=255 -> may wrap; clamp)
        bcc     @nw
        lda     #$ff
@nw:    sec
        sbc     #1              ; x+w-1
        lsr
        lsr
        lsr
        sta     rbt_ct_c1
        ; r0 = y>>3, r1 = (y+h-1)>>3
        ldy     #2
        lda     (rbt_ptr),y     ; y
        lsr
        lsr
        lsr
        sta     rbt_ct_r0
        ldy     #2
        lda     (rbt_ptr),y
        ldy     #4
        clc
        adc     (rbt_ptr),y     ; y+h
        bcc     @nh
        lda     #$ff
@nh:    sec
        sbc     #1
        lsr
        lsr
        lsr
        sta     rbt_ct_r1
        ; loop rows r0..r1
        lda     rbt_ct_r0
        sta     rbt_ct_r
@cr:    lda     rbt_ct_c0
        sta     rbt_ct_c
@cc:    ; inside view?
        lda     rbt_ct_c
        cmp     rbt_tm_vx
        bcc     @cskip
        lda     rbt_tm_vx
        clc
        adc     rbt_tm_vw
        cmp     rbt_ct_c
        beq     @cskip
        bcc     @cskip
        lda     rbt_ct_r
        cmp     rbt_tm_vy
        bcc     @cskip
        lda     rbt_tm_vy
        clc
        adc     rbt_tm_vh
        cmp     rbt_ct_r
        beq     @cskip
        bcc     @cskip
        ; map coords: mx = camx + c - vx, my = camy + r - vy
        clc
        lda     rbt_tm_camx
        adc     rbt_ct_c
        sec
        sbc     rbt_tm_vx
        sta     rbt_b
        clc
        lda     rbt_tm_camy
        adc     rbt_ct_r
        sec
        sbc     rbt_tm_vy
        sta     rbt_c
        jsr     rbt_tm_mapat    ; A = tile (0 when out of map)
        jsr     rbt_tileflags   ; A = flags byte
        sta     rbt_t0
        and     #1
        beq     @cskip
        lda     rbt_t0          ; solid -> return its flags
        rts
@cskip: inc     rbt_ct_c
        lda     rbt_ct_c
        cmp     rbt_ct_c1
        bcc     @cc
        beq     @cc             ; c <= c1: keep scanning the row
        inc     rbt_ct_r
        lda     rbt_ct_r
        cmp     rbt_ct_r1
        bcc     @cr
        beq     @cr             ; r <= r1: next row
@none:  lda     #0
        rts
''',
    'sprite': r'''
; ============================================================================
; rbt_sprite - VIC-II hardware sprite engine + Y-sorted raster-IRQ
; multiplexer (Commodore 64, ca65)
;
; TODO(revisit): the mux is much better but still not perfect — >8-sprite
; games (invaders) can still show occasional flicker when a rebind lands
; late. Next steps worth trying: tighter staging, a smaller lead time on
; the early arm, or double-buffering the pending stages so mid-frame
; applies never wait on sched output.
;
; 16 virtual slots drive the 8 hardware sprites. A raster IRQ at the
; frame-reset line (300, bottom border) does the once-per-frame commit —
; step animations, sort the live slots by Y, stage each slot's hw
; register image and bind the first 8 to the hardware — so every bind
; lands inside the border, before any sprite's top line. Mid-frame raster
; IRQs then rebind each hardware sprite to the next pending slot as the
; beam reaches its bottom, armed early enough that the rebind lands
; before the pending sprite's top. SPRITES UPDATE/DRAWALL/DRAW only
; ensure the mux is installed; the frame IRQ owns the schedule.
; SPRITECOLLIDE is a bounding-box test like the ZX engine (the VIC's
; $D01E/$D01F latches only cover currently-bound hardware pairs, so
; software bbox is the portable semantic).
;
; Logical coords match the ZX model: x 0-255, y 0-191 inside the text area.
; Hardware coords add the C64 border offsets: hwX = x+24 ($D010 bit for
; x>231), hwY = y+50.
;
; Sprite data is normally addressed in place: .rbs frames are padded
; to 64B and emitted in the SPDATA segment (linked on a 64B boundary),
; so each frame lands on a SPRPTR-addressable boundary in the active VIC
; bank and binding a slot is just a pointer write. A fallback pool of
; 8 x 64B buffers still serves frames that aren't directly addressable —
; runtime-loaded (COPYBANK) or linked outside the active bank. The pool
; sits inside the custom-charset window's unused codes 64-127 — text
; uses 0-63, tiles 128+ (C64: $CA00 in the bank-3 charset at $C800;
; C128: $3A00 in the bank-0 charset at $3800; the live base is in core's
; rbt_sppool/rbt_spptrb).
;
; .rbs (cbm encode): defb w,h,nframes,colour padded to 64 bytes; then
; frames of 63 bytes + pad (21 rows x 3 bytes, MSB-left), source
; clipped/padded to 24x21.
;
; Slot record (16 bytes, mirrors the ZX layout):
;   +0  flags: bit0 live, bit1 hidden
;   +1  x +2 y (logical pixels)
;   +3  w +4 h (source pixels; collision bbox)
;   +5  frame +6,7 asset ptr
;   +8  colour +9 mode (stored; hardware sprites have no blend mode)
;   +10 animFirst +11 animLast
;   +12 animFlags: bit0 pingpong, bit1 animating
;   +13 animDir (1 / $ff)
;   +14 asset bank ($ff - unused, no banked RAM)
;   +15 unused (was hw binding; the mux tracks binding in rbt_sp_bind)
; ============================================================================

RBT_SP_N        = 16            ; virtual slots
RBT_SP_SLOT     = 16            ; bytes per slot
RBT_SP_XOFF     = 24            ; logical->hardware offsets
RBT_SP_YOFF     = 50
RBT_SP_POOL     = RBT_POOLH<<8  ; 8 x 64B sprite data buffers (text-mode
                                ;  defaults — MODE 1 moves the pool to the
                                ;  bank-1 $7800 window; the live base is in
                                ;  core's rbt_sppool/rbt_spptrb)
RBT_SP_PTRBASE  = RBT_POOLP     ; SPRPTR value for the pool base
RBT_SP_FLINE    = 250           ; frame-reset raster line — past the visible
                                ; area, valid on PAL (312) and NTSC (263)
RBT_SP_H        = 21            ; hardware sprite height
RBT_SP_LEAD     = 12            ; max lines a bound sprite may be cut short

        .code

rbt_sprites:    .res 256        ; RBT_SP_N * RBT_SP_SLOT
rbt_sp_order:   .res RBT_SP_N   ; live slot ids sorted by y
rbt_sp_ordy:    .res RBT_SP_N   ; slot y parallel to order[] (fast sort)
rbt_sp_bind:    .res 8          ; order[] index bound to hw sprite n
rbt_sp_nlive:   .res 1
rbt_sp_next:    .res 1          ; next order[] index awaiting a hw sprite
rbt_sp_phase:   .res 1          ; 0 = mid-frame rebind, 1 = frame reset
rbt_sp_line:    .res 2          ; currently armed raster line
rbt_sp_inited:  .res 1
rbt_sp_j:       .res 1          ; sort inner-loop index
rbt_sp_src:     .res 16         ; per-hw pool-copy key: src lo/hi
rbt_sp_stage:   .res 128        ; 16 x 8B register images, by order idx
rbt_sp_bot:     .res 8          ; bound occupant's bottom line per hw
rbt_sp_d010:    .res 1          ; $D010/$D015 are write-only — reads return
rbt_sp_d015:    .res 1          ; open bus, so RMW goes through shadows

; Stage record (8 bytes, indexed by order position): precomputed at
; sched time so the raster-IRQ apply is just a burst of register writes.
;   +0  hw x low byte (lx + 24)
;   +1  hw y (ly + 50) — also the sprite's top line
;   +2  colour nibble
;   +3  SPRPTR value (direct path only)
;   +4  flags: bit7 = needs pool copy (unaligned/out-of-bank frame),
;       bit0 = hw x bit8 ($D010)
;   +5  bottom line (hw y + 21, clamped to 255)
;   +6,+7 frame source address (pool-copy path)

; The raster IRQ handlers only ever touch these private zero-page regs —
; the IRQ can fire anywhere in mainline code, so they must not clobber
; the rbt_hl/de/bc/t*/ptr regs the compiler emits around calls.
        .zeropage
rbt_si0:        .res 1          ; hw sprite n / loop index
rbt_si1:        .res 1          ; order idx
rbt_si2:        .res 1          ; byte temps; si2:si3 hold words
rbt_si3:        .res 1
rbt_sptr:       .res 2          ; slot pointer inside mux paths
        .code

; ----------------------------------------------------------------------------
; rbt_slot - A = sprite id -> rbt_ptr = slot. Clobbers A/X.
; ----------------------------------------------------------------------------
rbt_sp_sltab:
        .word   rbt_sprites+0,   rbt_sprites+16,  rbt_sprites+32
        .word   rbt_sprites+48,  rbt_sprites+64,  rbt_sprites+80
        .word   rbt_sprites+96,  rbt_sprites+112, rbt_sprites+128
        .word   rbt_sprites+144, rbt_sprites+160, rbt_sprites+176
        .word   rbt_sprites+192, rbt_sprites+208, rbt_sprites+224
        .word   rbt_sprites+240

rbt_slot:
        and     #RBT_SP_N-1
        asl
        tax
        lda     rbt_sp_sltab,x
        sta     rbt_ptr
        lda     rbt_sp_sltab+1,x
        sta     rbt_ptr+1
        rts

; ----------------------------------------------------------------------------
; rbt_sp_hwinit - one-time: install the raster IRQ handler, enable VIC
; raster IRQs. Non-raster IRQs (CIA1's 60Hz tick) still chain to $EA31,
; so keyboard scan and the jiffy clock keep working.
; ----------------------------------------------------------------------------
rbt_sp_hwinit:
        lda     rbt_sp_inited
        bne     @done
        sei
        lda     #<rbt_irq
        sta     $0314
        lda     #>rbt_irq
        sta     $0315
        jsr     rbt_mapio       ; VIC regs live in the I/O window on c128
        lda     #$01
        sta     $d019           ; ack any pending VIC IRQ
        sta     $d01a           ; raster IRQ enable
        lda     #0
        sta     $d010
        sta     rbt_sp_d010     ; sync the write-only-reg shadows
        sta     $d015
        sta     rbt_sp_d015
        lda     #1
        sta     rbt_sp_inited
        lda     #$ff
        ldx     #7
@clr:   sta     rbt_sp_bind,x
        sta     rbt_sp_bot,x
        dex
        bpl     @clr
        lda     #0
        ldx     #15
@cl2:   sta     rbt_sp_src,x    ; no asset lives at $0000 -> first apply copies
        dex
        bpl     @cl2
        lda     #<RBT_SP_FLINE
        sta     rbt_sp_line
        lda     #>RBT_SP_FLINE
        sta     rbt_sp_line+1
        lda     #1
        sta     rbt_sp_phase
        jsr     rbt_sp_setline
        jsr     rbt_maprun
        cli
@done:  rts

; rbt_irq - $0314 vector target. Ours iff $D019 bit0. The kernal already
; pushed A/X/Y; the mux handlers only touch their private ZP regs
; (rbt_si*/rbt_sptr), so no save/restore is needed and there is no kernal
; chain on raster IRQs — CIA1's own 60Hz IRQ still reaches $EA31 for
; keyboard scan and the jiffy clock.
rbt_irq:
        .if RBT_C128
        lda     #$3e
        sta     $ff00           ; I/O + RAM $4000+ (no kernal, but the I
                                ; flag is already set — nothing can fire)
        .endif
        lda     $d019
        and     #1
        beq     @kern
        jsr     rbt_sp_irq
        lda     #$01
        sta     $d019           ; ack raster IRQ
        .if RBT_C128
        lda     #$0f
        sta     $ff00           ; $ff33 is kernal ROM — remap it first
        jmp     $ff33           ; c128 trampoline pushed A,X,Y then CR —
                                ; its exit restores all four, then rti
        .else
        pla                     ; kernal entry pushed A,X,Y (Y on top)
        tay
        pla
        tax
        pla
        rti
        .endif
@kern:
        .if RBT_C128
        lda     #$00
        sta     $ff00           ; all-ROM map — the kernal handler calls
                                ; editor code at $4006 in ROM-lo
        .endif
        jmp     RBT_KERNAL_IRQ  ; kernal housekeeping ($EA31 c64 / $FA6B
                                ; c128 — past its raster-split manager at
                                ; $C024, which would re-arm $D012 every
                                ; tick and steal our raster IRQ)

; rbt_slot2 - A = sprite id -> rbt_sptr = slot. IRQ-side twin of
; rbt_slot; writes rbt_sptr so it can't clobber a live rbt_ptr.
; Clobbers A/X.
rbt_slot2:
        and     #RBT_SP_N-1
        asl
        tax
        lda     rbt_sp_sltab,x
        sta     rbt_sptr
        lda     rbt_sp_sltab+1,x
        sta     rbt_sptr+1
        rts

; ----------------------------------------------------------------------------
; rbt_sp_setline - arm the raster IRQ at rbt_sp_line (9-bit).
; ----------------------------------------------------------------------------
rbt_sp_setline:
        lda     rbt_sp_line
        sta     $d012
        lda     $d011
        and     #$7f
        ldx     rbt_sp_line+1
        beq     @lo
        ora     #$80
@lo:    sta     $d011
        rts

; ----------------------------------------------------------------------------
; rbt_sp_create - A=id, B=mode, C=x, D=y, E=bank, rbt_hl=asset.
; ----------------------------------------------------------------------------
rbt_sp_create:
        pha                     ; id
        lda     rbt_hl
        sta     rbt_de
        lda     rbt_hl+1
        sta     rbt_de+1        ; de = asset
        pla
        jsr     rbt_slot        ; ptr = slot
        ; header: w,h,nframes,colour at asset+0..3
        ldy     #0
        lda     (rbt_de),y
        ldy     #3
        sta     (rbt_ptr),y     ; +3 w
        ldy     #1
        lda     (rbt_de),y
        ldy     #4
        sta     (rbt_ptr),y     ; +4 h
        ldy     #2
        lda     (rbt_de),y      ; nframes
        beq     @nf
        sec
        sbc     #1              ; animLast = nframes-1
@nf:    ldy     #11
        sta     (rbt_ptr),y     ; +11 animLast
        ldy     #3
        lda     (rbt_de),y
        ldy     #8
        sta     (rbt_ptr),y     ; +8 colour
        ; identity fields
        ldy     #6
        lda     rbt_de
        sta     (rbt_ptr),y
        iny
        lda     rbt_de+1
        sta     (rbt_ptr),y     ; +6,7 asset
        ldy     #0
        lda     #1
        sta     (rbt_ptr),y     ; +0 live
        iny
        lda     rbt_c
        sta     (rbt_ptr),y     ; +1 x
        iny
        lda     rbt_d
        sta     (rbt_ptr),y     ; +2 y
        ldy     #5
        lda     #0
        sta     (rbt_ptr),y     ; +5 frame
        ldy     #9
        lda     rbt_b
        sta     (rbt_ptr),y     ; +9 mode (stored, unused by hw sprites)
        ldy     #10
        lda     #0
        sta     (rbt_ptr),y     ; +10 animFirst
        ldy     #12
        sta     (rbt_ptr),y     ; +12 animFlags = 0
        ldy     #13
        lda     #1
        sta     (rbt_ptr),y     ; +13 animDir
        ldy     #14
        lda     rbt_e
        sta     (rbt_ptr),y     ; +14 bank ($ff)
        ldy     #15
        lda     #$ff
        sta     (rbt_ptr),y     ; +15 no hw sprite yet
        jsr     rbt_sp_hwinit   ; arm the mux on first sprite use
        rts

; ----------------------------------------------------------------------------
; rbt_sp_place - A=id, B=x, C=y. rbt_sp_move - A=id, B=dx, C=dy (signed).
; ----------------------------------------------------------------------------
rbt_sp_place:
        jsr     rbt_slot
        ldy     #1
        lda     rbt_b
        sta     (rbt_ptr),y
        iny
        lda     rbt_c
        sta     (rbt_ptr),y
        rts

rbt_sp_move:
        jsr     rbt_slot
        ldy     #1
        clc
        lda     (rbt_ptr),y
        adc     rbt_b
        sta     (rbt_ptr),y
        iny
        clc
        lda     (rbt_ptr),y
        adc     rbt_c
        sta     (rbt_ptr),y
        rts

; ----------------------------------------------------------------------------
; rbt_sp_frame - A=id, B=frame (mod nframes via asset[2])
; ----------------------------------------------------------------------------
rbt_sp_frame:
        jsr     rbt_slot
        ldy     #5
        lda     rbt_b
        sta     (rbt_ptr),y
        rts

; ----------------------------------------------------------------------------
; rbt_sp_anim - A=id, B=first, C=last, D=0 loop / 1 pingpong
; ----------------------------------------------------------------------------
rbt_sp_anim:
        jsr     rbt_slot
        ldy     #10
        lda     rbt_b
        sta     (rbt_ptr),y     ; animFirst
        iny
        lda     rbt_c
        sta     (rbt_ptr),y     ; animLast
        ldy     #5
        lda     rbt_b
        sta     (rbt_ptr),y     ; start at first
        ldy     #12
        lda     #2              ; animating
        ldx     rbt_d
        beq     @np
        ora     #1              ; pingpong
@np:    sta     (rbt_ptr),y
        ldy     #13
        lda     #1
        sta     (rbt_ptr),y     ; dir forward
        rts

; ----------------------------------------------------------------------------
; rbt_sp_kill / rbt_sp_hide / rbt_sp_show - A=id
; ----------------------------------------------------------------------------
rbt_sp_kill:
        jsr     rbt_slot
        ldy     #0
        lda     #0
        sta     (rbt_ptr),y
        rts

rbt_sp_hide:
        jsr     rbt_slot
        ldy     #0
        lda     (rbt_ptr),y
        ora     #2
        sta     (rbt_ptr),y
        rts

rbt_sp_show:
        jsr     rbt_slot
        ldy     #0
        lda     (rbt_ptr),y
        and     #%11111101
        sta     (rbt_ptr),y
        rts

; ----------------------------------------------------------------------------
; rbt_sp_attr - A=id, B=colour nibble
; ----------------------------------------------------------------------------
rbt_sp_attr:
        jsr     rbt_slot
        ldy     #8
        lda     rbt_b
        and     #$0f
        sta     (rbt_ptr),y
        rts

; ----------------------------------------------------------------------------
; rbt_sp_draw - A=id. Hardware sprites need no per-sprite blit: the
; frame-reset IRQ picks up the slot state next frame.
; ----------------------------------------------------------------------------
rbt_sp_draw:
        jmp     rbt_sp_hwinit   ; commits happen at the frame-reset IRQ

; ----------------------------------------------------------------------------
; rbt_spx / rbt_spy - A=id -> A = logical x/y
; ----------------------------------------------------------------------------
rbt_spx:
        jsr     rbt_slot
        ldy     #1
        lda     (rbt_ptr),y
        rts

rbt_spy:
        jsr     rbt_slot
        ldy     #2
        lda     (rbt_ptr),y
        rts

; ----------------------------------------------------------------------------
; rbt_spcoll - A=id1, B=id2 -> A=1 when bounding boxes overlap.
; ----------------------------------------------------------------------------
rbt_spcoll:
        jsr     rbt_slot
        ldy     #0
        lda     (rbt_ptr),y
        and     #3
        cmp     #1
        beq     @a
        jmp     @no             ; slot1 not live (or hidden)
@a:     ; stash slot1 x,y,w,h in bc/de zps via t0.. — copy to rbt_de/rbt_bc
        ldy     #1
        lda     (rbt_ptr),y
        sta     rbt_t0          ; x1
        iny
        lda     (rbt_ptr),y
        sta     rbt_t1          ; y1
        ldy     #3
        lda     (rbt_ptr),y
        sta     rbt_de          ; w1
        ldy     #4
        lda     (rbt_ptr),y
        sta     rbt_de+1        ; h1
        lda     rbt_b
        jsr     rbt_slot
        ldy     #0
        lda     (rbt_ptr),y
        and     #3
        cmp     #1
        bne     @no
        ; x2 < x1+w1 ?
        ldy     #1
        lda     (rbt_ptr),y     ; x2
        sta     rbt_t2
        lda     rbt_t0
        clc
        adc     rbt_de          ; x1+w1
        bcs     @chk1           ; wrapped: x1+w1 >= 256 -> x2< that true
        cmp     rbt_t2
        beq     @no             ; x1+w1 == x2 -> no overlap
        bcc     @no             ; x1+w1 <  x2 -> no
@chk1:  ; x1 < x2+w2 ?
        ldy     #3
        lda     (rbt_ptr),y     ; w2
        ldy     #1
        clc
        adc     (rbt_ptr),y     ; x2+w2
        bcs     @chk2
        cmp     rbt_t0
        beq     @no
        bcc     @no
@chk2:  ; y2 < y1+h1 ?
        ldy     #2
        lda     (rbt_ptr),y     ; y2
        sta     rbt_t2
        lda     rbt_t1
        clc
        adc     rbt_de+1        ; y1+h1
        bcs     @chk3
        cmp     rbt_t2
        beq     @no
        bcc     @no
@chk3:  ; y1 < y2+h2 ?
        ldy     #4
        lda     (rbt_ptr),y     ; h2
        ldy     #2
        clc
        adc     (rbt_ptr),y     ; y2+h2
        bcs     @yes
        cmp     rbt_t1
        beq     @no
        bcc     @no
@yes:   lda     #1
        rts
@no:    lda     #0
        rts

; ----------------------------------------------------------------------------
; rbt_sp_update / rbt_sp_drawall - hardware sprites commit once per frame
; at the frame-reset IRQ (line 300) where ~50+ border lines are guaranteed
; before the first sprite window; the calls only ensure the mux exists.
; ----------------------------------------------------------------------------
rbt_sp_update:
rbt_sp_drawall:
        jmp     rbt_sp_hwinit

; ----------------------------------------------------------------------------
; rbt_sp_sched - step animations, rebuild the sorted order, stage
; register images, bind the first 8 hw sprites, arm the next IRQ. Runs
; once per frame at the frame-reset IRQ — never from mainline — so the
; binds always land in the border, ahead of every sprite window. Uses
; only the private rbt_si*/rbt_sptr regs so it cannot clobber the
; compiler's live ZP registers mid-instruction.
; ----------------------------------------------------------------------------
rbt_sp_sched:
        ; collect live && !hidden slot ids into order[]
        lda     #0
        sta     rbt_sp_nlive
        sta     rbt_si0         ; id
@scan:  lda     rbt_si0
        jsr     rbt_slot2
        ldy     #0
        lda     (rbt_sptr),y
        and     #1
        beq     @skip           ; not live: no anim, no draw
        jsr     _sp_anim1       ; step this slot's animation
        ldy     #0
        lda     (rbt_sptr),y
        and     #3
        cmp     #1              ; live && !hidden
        bne     @skip
        ldy     #2
        lda     (rbt_sptr),y    ; y
        cmp     #192            ; logical y off screen -> skip
        bcs     @skip
        ldx     rbt_sp_nlive
        sta     rbt_sp_ordy,x   ; sort key kept parallel — no slot
        lda     rbt_si0         ;  lookup per comparison later
        sta     rbt_sp_order,x
        inc     rbt_sp_nlive
@skip:  inc     rbt_si0
        lda     rbt_si0
        cmp     #RBT_SP_N
        bcc     @scan
        ; insertion sort order[]/ordy[] by y — pure byte compares
        lda     #1
        sta     rbt_si0         ; i
@si:    lda     rbt_si0
        cmp     rbt_sp_nlive
        bcs     @sorted
        ldx     rbt_si0
        lda     rbt_sp_order,x
        sta     rbt_si1         ; key id
        lda     rbt_sp_ordy,x
        sta     rbt_si2         ; key y
        ldx     rbt_si0
        stx     rbt_sp_j        ; j = i
@sj:    lda     rbt_sp_j
        beq     @sins
        ; ordy[j-1] > key.y ?
        ldx     rbt_sp_j
        dex
        lda     rbt_sp_ordy,x
        cmp     rbt_si2
        beq     @sins
        bcc     @sins
        ; shift both arrays at j-1 -> j
        lda     rbt_sp_order,x
        ldx     rbt_sp_j
        sta     rbt_sp_order,x
        dex
        lda     rbt_sp_ordy,x
        ldx     rbt_sp_j
        sta     rbt_sp_ordy,x
        dec     rbt_sp_j
        jmp     @sj
@sins:  ldx     rbt_sp_j
        lda     rbt_si1
        sta     rbt_sp_order,x
        lda     rbt_si2
        sta     rbt_sp_ordy,x
        inc     rbt_si0
        jmp     @si
@sorted:
        ; stage + bind the first min(8,nlive) to hw 0..7 — their tops are
        ; the earliest on screen so these applies must land before
        ; anything else. No global $d015 clear: bound sprites keep their
        ; enable bit or they vanish for any window this sched runs across.
        lda     #$ff
        ldx     #7
@cb:    sta     rbt_sp_bind,x
        sta     rbt_sp_bot,x
        dex
        bpl     @cb
        lda     #0
        sta     rbt_si0         ; order idx == hw n for this loop
@bind:  lda     rbt_si0
        cmp     #8
        bcs     @ub
        cmp     rbt_sp_nlive
        bcs     @ub
        tax
        lda     rbt_sp_order,x
        jsr     rbt_slot2       ; sptr = slot
        jsr     _sp_stage       ; stage[si0] <- slot
        ldx     rbt_si0
        txa
        sta     rbt_sp_bind,x   ; bind[hw] = order idx
        jsr     rbt_sp_apply    ; A = order idx, si0 = hw n
        inc     rbt_si0
        jmp     @bind
@ub:    ; hw sprites left unbound get disabled (dead/hidden slots must
        ; not linger); bound ones keep their enable bit
        ldx     rbt_si0
@ub2:   cpx     #8
        bcs     @pstg
        lda     rbt_sp_d015
        and     rbt_sp_mask,x
        sta     $d015
        sta     rbt_sp_d015
        inx
        jmp     @ub2
@pstg:  ; stage the pending group — mid-frame IRQs apply them from here
        lda     rbt_si0
        sta     rbt_sp_next     ; first pending = first unbound order idx
@pstg2: lda     rbt_si0
        cmp     rbt_sp_nlive
        bcs     @arm
        tax
        lda     rbt_sp_order,x
        jsr     rbt_slot2
        jsr     _sp_stage
        inc     rbt_si0
        jmp     @pstg2
@arm:   jmp     rbt_sp_arm

; ----------------------------------------------------------------------------
; _sp_anim1 - step the animation of the live slot at rbt_sptr. IRQ-side;
; uses only rbt_sptr + A/Y. Clobbers A/Y.
; ----------------------------------------------------------------------------
_sp_anim1:
        ldy     #12
        lda     (rbt_sptr),y
        and     #2
        beq     @no             ; not animating
        ldy     #13
        lda     (rbt_sptr),y
        bmi     @down
        ; dir = +1
        ldy     #5
        lda     (rbt_sptr),y    ; frame
        ldy     #11
        cmp     (rbt_sptr),y    ; animLast
        bcc     @inc
        ; at last
        ldy     #12
        lda     (rbt_sptr),y
        and     #1
        beq     @wrap           ; loop mode -> first
        ; pingpong: reverse
        ldy     #13
        lda     #$ff
        sta     (rbt_sptr),y
        ldy     #11
        lda     (rbt_sptr),y    ; last
        ldy     #10
        cmp     (rbt_sptr),y    ; last == first?
        beq     @no             ; single-frame range: stay
        sec
        sbc     #1
        jmp     @set            ; last-1
@wrap:  ldy     #10
        lda     (rbt_sptr),y    ; animFirst
        jmp     @set
@inc:   ldy     #5
        lda     (rbt_sptr),y
        clc
        adc     #1
        jmp     @set
@down:  ; dir = -1
        ldy     #5
        lda     (rbt_sptr),y    ; frame
        ldy     #10
        cmp     (rbt_sptr),y    ; animFirst
        beq     @atfirst
        bcc     @atfirst
        sec
        sbc     #1
        jmp     @set
@atfirst:
        ldy     #12
        lda     (rbt_sptr),y
        and     #1
        beq     @wraph          ; loop mode -> last
        ldy     #13
        lda     #1
        sta     (rbt_sptr),y    ; dir forward
        ldy     #10
        lda     (rbt_sptr),y    ; first
        ldy     #11
        cmp     (rbt_sptr),y
        beq     @no             ; single-frame
        clc
        adc     #1
        jmp     @set            ; first+1
@wraph: ldy     #11
        lda     (rbt_sptr),y    ; animLast
@set:   ldy     #5
        sta     (rbt_sptr),y
@no:    rts

; ----------------------------------------------------------------------------
; _sp_stage - build the hw register image for the order idx in rbt_si0
; from the slot at rbt_sptr. Clobbers A/X/Y, rbt_si2/si3.
; ----------------------------------------------------------------------------
_sp_stage:
        lda     rbt_si0
        asl
        asl
        asl
        tax                     ; X = order idx * 8
        ; src = asset + 64 + frame*64  (header is one padded 64B block)
        ldy     #5
        lda     (rbt_sptr),y    ; frame
        sta     rbt_si2
        lda     #0
        sta     rbt_si3
        asl     rbt_si2
        rol     rbt_si3
        asl     rbt_si2
        rol     rbt_si3
        asl     rbt_si2
        rol     rbt_si3
        asl     rbt_si2
        rol     rbt_si3
        asl     rbt_si2
        rol     rbt_si3
        asl     rbt_si2
        rol     rbt_si3         ; si2:si3 = frame*64
        ldy     #6
        clc
        lda     (rbt_sptr),y    ; asset lo
        adc     rbt_si2
        sta     rbt_si2
        iny
        lda     (rbt_sptr),y    ; asset hi
        adc     rbt_si3
        sta     rbt_si3
        clc
        lda     rbt_si2
        adc     #64
        sta     rbt_si2
        lda     rbt_si3
        adc     #0
        sta     rbt_si3         ; si2:si3 = frame src
        sta     rbt_sp_stage+7,x
        lda     rbt_si2
        sta     rbt_sp_stage+6,x
        ; SPRPTR: point at the frame directly when it is 64-aligned
        ; inside the pool's 16K VIC bank; flag the pool-copy fallback
        ; otherwise (runtime-loaded/unaligned data, or linked outside
        ; the bank — text mode's bank 3 never contains linked frames)
        lda     #0
        sta     rbt_si3         ; flags accumulator
        lda     rbt_sp_stage+7,x
        eor     rbt_sppool
        and     #$c0            ; same 16K bank as the sprite pool?
        bne     @cpflg
        lda     rbt_si2
        and     #$3f
        bne     @cpflg
        ; SPRPTR = src >> 6 = (hi<<2) | (lo>>6)
        lda     rbt_sp_stage+7,x
        asl
        asl
        sta     rbt_si2
        lda     rbt_sp_stage+6,x
        lsr
        lsr
        lsr
        lsr
        lsr
        lsr
        ora     rbt_si2
        jmp     @ptr
@cpflg: lda     #$80
        sta     rbt_si3         ; flag bit7: copy to pool at apply time
        lda     #0
@ptr:   sta     rbt_sp_stage+3,x
        ; x -> hw x lo + msb flag
        ldy     #1
        lda     (rbt_sptr),y    ; lx
        clc
        adc     #RBT_SP_XOFF
        sta     rbt_sp_stage+0,x
        bcc     @nomsb
        lda     rbt_si3
        ora     #1
        sta     rbt_si3         ; flag bit0: $D010 bit set
@nomsb: ; y -> hw y (top line) and bottom
        ldy     #2
        lda     (rbt_sptr),y    ; ly
        clc
        adc     #RBT_SP_YOFF
        sta     rbt_sp_stage+1,x
        clc
        adc     #RBT_SP_H
        bcc     @bot
        lda     #$ff            ; bottom >= 256 -> treat as 255
@bot:   sta     rbt_sp_stage+5,x
        ldy     #8
        lda     (rbt_sptr),y    ; colour
        and     #$0f
        sta     rbt_sp_stage+2,x
        lda     rbt_si3
        sta     rbt_sp_stage+4,x
        rts

; ----------------------------------------------------------------------------
; rbt_sp_arm - pick the next raster IRQ line and program it.
; ----------------------------------------------------------------------------
rbt_sp_arm:
        ldx     rbt_sp_next
        cpx     rbt_sp_nlive
        bcc     @mid
        ; nothing pending -> idle at the frame-reset line
        lda     #<RBT_SP_FLINE
        sta     rbt_sp_line
        lda     #>RBT_SP_FLINE
        sta     rbt_sp_line+1
        lda     #1
        sta     rbt_sp_phase
        jmp     rbt_sp_setline
@mid:   ; earliest bottom among bound hw sprites, pulled forward when the
        ; next pending sprite's window opens sooner than that — rebinding
        ; must land before the pending top or the sprite misses the frame
        ; entirely, while an occupant cut a few lines short only loses
        ; (usually empty) bottom rows
        lda     #$ff
        sta     rbt_si2         ; min bound bottom
        ldx     #0
@h:     lda     rbt_sp_bot,x
        cmp     rbt_si2
        bcs     @hn
        sta     rbt_si2
@hn:    inx
        cpx     #8
        bcc     @h
        lda     rbt_si2
        cmp     #$ff
        bne     @have
        lda     #200            ; nothing bound? fallback line
@have:  sta     rbt_si2         ; B = earliest bound bottom
        ; T = next pending's top; K = pendings sharing its band
        ; (top within one sprite height — they contend for the same gap)
        ldx     rbt_sp_next
        txa
        asl
        asl
        asl
        tay
        lda     rbt_sp_stage+1,y
        sta     rbt_si3         ; T (stage tops ascend with the order)
        lda     #0
        sta     rbt_si1         ; K
@k:     cpx     rbt_sp_nlive
        bcs     @kd
        txa
        asl
        asl
        asl
        tay
        lda     rbt_sp_stage+1,y
        sec
        sbc     rbt_si3
        cmp     #RBT_SP_H
        bcs     @kd             ; ascending tops -> out of the band
        inc     rbt_si1
        inx
        jmp     @k
@kd:    ; want the IRQ ~3K+2 lines before T (a staged apply is ~2-3
        ; lines with VIC steals); never cut a bound sprite by > LEAD
        lda     rbt_si1
        asl
        clc
        adc     rbt_si1         ; 3K
        adc     #2
        sta     rbt_si1         ; need
        lda     rbt_si3
        sec
        sbc     rbt_si1         ; cand = T - need
        bcs     @c1
        lda     #1
@c1:    sta     rbt_si1
        lda     rbt_si2
        sec
        sbc     #RBT_SP_LEAD    ; floor = B - LEAD
        bcs     @c2
        lda     #1
@c2:    cmp     rbt_si1
        bcs     @cmpb           ; floor >= cand -> fire at floor
        lda     rbt_si1         ; else cand
@cmpb:  cmp     rbt_si2
        bcs     @fireB          ; cand/floor >= B -> fire at B (no cut)
        jmp     @fire
@fireB: lda     rbt_si2
@fire:  sta     rbt_sp_line
        lda     #0
        sta     rbt_sp_line+1
        sta     rbt_sp_phase
        jmp     rbt_sp_setline

; ----------------------------------------------------------------------------
; rbt_sp_irq - raster IRQ dispatch on rbt_sp_phase.
; ----------------------------------------------------------------------------
rbt_sp_irq:
        lda     rbt_sp_phase
        bne     @frame
        jmp     _sp_irq_mid
@frame: jmp     _sp_irq_frame

; _sp_irq_frame - frame-reset line 300: run the whole schedule in the
; border, where ~50 lines are guaranteed before the first sprite window,
; so every bind lands before its occupant's top regardless of when the
; game last called UPDATE (or whether it calls it at all).
_sp_irq_frame:
        jmp     rbt_sp_sched

; _sp_irq_mid - sprite bottom(s) reached: rebind those hw sprites to
; pending slots, then rearm. A bound sprite counts as finished when its
; bottom is at most RBT_SP_LEAD lines below the armed line — the early
; arm already cut it, and grouping near-simultaneous bottoms into one IRQ
; keeps the rebind burst short.
_sp_irq_mid:
        ldx     #0
@h:     stx     rbt_si0         ; hw n
        lda     rbt_sp_bind,x
        cmp     #$ff
        beq     @next
        lda     rbt_sp_bot,x
        sec
        sbc     #RBT_SP_LEAD    ; bottom >= 71 always, never wraps
        cmp     rbt_sp_line
        beq     @fin
        bcs     @next           ; bottom-LEAD > armed line: still on screen
                                ; (recomputed per hw: apply clobbers si*)
@fin:                           ; bottom-LEAD <= line: finished
        ; this hw sprite finished
        ldx     rbt_sp_next
        cpx     rbt_sp_nlive
        bcs     @off
        txa                     ; order idx of next pending slot
        ldx     rbt_si0
        sta     rbt_sp_bind,x   ; bind[hw] = order idx
        inc     rbt_sp_next
        jsr     rbt_sp_apply    ; A = order idx, si0 = hw n
        jmp     @next
@off:   ldx     rbt_si0
        lda     #$ff
        sta     rbt_sp_bind,x
        sta     rbt_sp_bot,x
        lda     rbt_sp_d015
        and     rbt_sp_mask,x   ; (mask table below)
        sta     $d015
        sta     rbt_sp_d015
@next:  ldx     rbt_si0
        inx
        cpx     #8
        bcc     @h
        jmp     rbt_sp_arm

rbt_sp_mask:    .byte $fe,$fd,$fb,$f7,$ef,$df,$bf,$7f   ; ~bit n
rbt_sp_bits:    .byte $01,$02,$04,$08,$10,$20,$40,$80   ;  bit n

; ----------------------------------------------------------------------------
; rbt_sp_apply - program hw sprite rbt_si0 from the staged register image
; for order idx A. Just a burst of register writes — all the src/pos math
; was precomputed by _sp_stage at sched time — except on the rare pool-
; copy fallback (stage flag bit7) for frames the VIC can't address.
; Clobbers A/X/Y, rbt_si1-si3, rbt_sptr.
; ----------------------------------------------------------------------------
rbt_sp_apply:
        sta     rbt_si1         ; order idx
        asl
        asl
        asl
        tay                     ; Y = stage idx (idx*8)
        ; hw y first: a sprite that misses its top line is invisible all
        ; frame — a late ptr/x only corrupts its first rows, so trigger
        ; the window before doing anything else
        ldx     rbt_si0
        txa
        asl
        tax
        lda     rbt_sp_stage+1,y
        sta     $d001,x         ; hw y
        lda     rbt_sp_stage+4,y
        bmi     @copy           ; frame needs a pool copy
        ldx     rbt_smode
        bne     @copy           ; bitmap mode: only the bank-1 pool is
                                ;  VIC-visible
        lda     rbt_sp_stage+3,y
        ldx     rbt_si0
        sta     RBT_SPPT,x      ; SPRPTR -> frame data, no copy
        sta     $7ff8,x         ;  (both tables: the matrix moves banks
        jmp     @tail           ;   with the mode, stay in sync either way)
@copy:  ; src = stage+6,7 -> rbt_sptr;  dst = pool + hw*64 -> si2:si3
        lda     rbt_sp_stage+6,y
        sta     rbt_sptr
        lda     rbt_sp_stage+7,y
        sta     rbt_sptr+1
        lda     rbt_si0
        lsr
        lsr
        clc
        adc     rbt_sppool      ; dst hi — pool rides the active VIC bank
        sta     rbt_si3
        lda     rbt_si0
        and     #3
        asl
        asl
        asl
        asl
        asl
        asl                     ; (hw&3)<<6
        sta     rbt_si2         ; dst lo
        ; skip the 63-byte copy when this hw buffer already holds this
        ; frame: it is the bulk of apply's raster time, and running it
        ; inside the sprite's window tears it
        lda     rbt_si0
        asl
        tax                     ; hw*2
        lda     rbt_sptr
        cmp     rbt_sp_src,x
        bne     @new
        lda     rbt_sptr+1
        eor     rbt_sppool      ; key hi = src hi XOR pool bank — the cache
        cmp     rbt_sp_src+1,x  ;  self-invalidates when MODE moves the pool
        beq     @nocp
@new:   lda     rbt_sptr
        sta     rbt_sp_src,x
        lda     rbt_sptr+1
        eor     rbt_sppool
        sta     rbt_sp_src+1,x
        ldy     #62
@cp:    lda     (rbt_sptr),y
        sta     (rbt_si2),y
        dey
        bpl     @cp
        ldy     #63
        lda     #0
        sta     (rbt_si2),y     ; pad byte
@nocp:  ldx     rbt_si0
        txa
        clc
        adc     rbt_spptrb      ; pool SPRPTR base for the active VIC bank
        sta     RBT_SPPT,x      ; SPRPTR -> pool buffer
        sta     $7ff8,x         ;  (both tables — see above)
        lda     rbt_si1         ; restore stage idx
        asl
        asl
        asl
        tay
@tail:  ; colour -> $D027+n, x -> $D000+2n/$D010, bound bottom ->
        ; rbt_sp_bot[n], enable -> $D015  (hw y already written)
        ldx     rbt_si0
        lda     rbt_sp_stage+2,y
        sta     $d027,x
        txa
        asl
        tax
        lda     rbt_sp_stage+0,y
        sta     $d000,x         ; hw x lo
        lda     rbt_sp_stage+5,y
        ldx     rbt_si0
        sta     rbt_sp_bot,x    ; occupant's bottom line
        lda     rbt_sp_bits,x   ; 1<<n
        sta     rbt_si2
        lda     rbt_sp_stage+4,y
        lsr                     ; msb flag -> carry
        lda     rbt_sp_d010
        bcc     @xlo
        ora     rbt_si2
        bne     @xs             ; always
@xlo:   and     rbt_sp_mask,x
@xs:    sta     $d010
        sta     rbt_sp_d010
        lda     rbt_sp_d015
        ora     rbt_si2
        sta     $d015           ; enable hw sprite
        sta     rbt_sp_d015
        rts
''',
    'tilemap': r'''
; ============================================================================
; rbt_tilemap - text-mode tilemap engine (Commodore 64, ca65)
;
; On the C64 the screen IS a tilemap: a tile is an 8x8 character cell.
; TILESET copies the .rbt bitmaps into charset RAM at screen codes 128+
; ($3C00, charset base $3800), so TILEMAP DRAW writes tile indices straight
; to screen RAM ($0400) and the tile's colour nibble to colour RAM ($D800).
;
; To keep text rendering intact TILESET first fills charset RAM from the
; chargen ROM when no custom font is bound (rbt_font == 0); a bound font
; already covers every text code 0-63, so only the tile glyphs go in.
; Consequence: reverse-video text (FLASH/OVER set) collides with tile
; glyphs — a documented limitation of the shared charset.
;
; .rbt binary: defb n; n*8 bitmaps; n attrs; n flags  (n clamped to 128)
; .rbm binary: defb w,h; w*h tile indices row-major
;
; Register contract (matches the Z80 engine): byte args in rbt_b/c/d/e,
; pointers in rbt_hl; routines clobber A/X/Y and all rbt_ regs.
; ============================================================================

RBT_TM_CODEBASE = $80           ; tile i -> screen code $80+i

        .code

; ----------------------------------------------------------------------------
; rbt_tm_settiles - rbt_hl = tileset data. Parses the tables and copies tile
; bitmaps into charset RAM.
; ----------------------------------------------------------------------------
rbt_tm_settiles:
        lda     rbt_hl
        sta     rbt_tm_tiles
        lda     rbt_hl+1
        sta     rbt_tm_tiles+1
        ; rbt_tm_bmp = tiles+1
        clc
        lda     rbt_hl
        adc     #1
        sta     rbt_tm_bmp
        lda     rbt_hl+1
        adc     #0
        sta     rbt_tm_bmp+1
        ; n = tiles[0], clamped to 128
        ldy     #0
        lda     (rbt_hl),y
        cmp     #129
        bcc     @nok
        lda     #128
@nok:   sta     rbt_tm_n
        ; rbt_tm_tattr = bmp + n*8; tflags = tattr + n
        sta     rbt_t0
        sta     rbt_de
        lda     #0
        sta     rbt_de+1
        asl     rbt_de
        rol     rbt_de+1        ; *2
        asl     rbt_de
        rol     rbt_de+1        ; *4
        asl     rbt_de
        rol     rbt_de+1        ; de = n*8
        clc
        lda     rbt_tm_bmp
        adc     rbt_de
        sta     rbt_tm_tattr
        lda     rbt_tm_bmp+1
        adc     rbt_de+1
        sta     rbt_tm_tattr+1
        clc
        lda     rbt_tm_tattr
        adc     rbt_t0
        sta     rbt_tm_tflags
        lda     rbt_tm_tattr+1
        adc     #0
        sta     rbt_tm_tflags+1

        ; --- populate charset RAM from the chargen ROM ---
        ; CHAREN=0 maps the chargen ROM over $D000-$DFFF for CPU reads.
        ; Only needed when no custom font is bound — a bound font already
        ; covers every text code (0-63), and copying chargen codes 0-31
        ; over $3800-$38FF would clobber its letter glyphs.
        lda     rbt_font
        ora     rbt_font+1
        bne     @tiles          ; font bound: skip chargen copy
        sei
        lda     #$37
        and     #%11111011
        sta     $01
        ldx     #8              ; 8 pages: $D000-$D7FF -> charset RAM
        lda     #$00
        sta     rbt_ptr
        lda     #$d0
        sta     rbt_ptr+1
        lda     #$00
        sta     rbt_hl
        lda     #>RBT_CSET
        sta     rbt_hl+1
@cpg:   ldy     #0
@cpl:   lda     (rbt_ptr),y
        sta     (rbt_hl),y
        iny
        bne     @cpl
        inc     rbt_ptr+1
        inc     rbt_hl+1
        dex
        bne     @cpl
        lda     #$37
        sta     $01
        cli
@tiles:

        ; --- tile bitmaps -> charset+$400 (screen codes 128+) ---
        ; count = n*8 bytes; n<=128 so <=4 pages + partial.
        lda     rbt_tm_bmp
        sta     rbt_ptr
        lda     rbt_tm_bmp+1
        sta     rbt_ptr+1
        lda     #$00
        sta     rbt_hl
        lda     #>(RBT_CSET+$400)
        sta     rbt_hl+1
        ldx     rbt_de+1        ; full pages of n*8
        ldy     #0
        cpx     #0
        beq     @rem
@tpg:   lda     (rbt_ptr),y
        sta     (rbt_hl),y
        iny
        bne     @tpg
        inc     rbt_ptr+1
        inc     rbt_hl+1
        dex
        bne     @tpg
@rem:   ; remaining de.lo bytes (0..255)
        lda     rbt_de
        beq     @done
        sta     rbt_t0
@rl:    lda     (rbt_ptr),y
        sta     (rbt_hl),y
        iny
        cpy     rbt_t0
        bne     @rl
@done:
        ; VIC: screen + charset bases for the active bank
        lda     #RBT_D018T
        jsr     rbt_mapio       ; preserves A
        sta     $d018
        jsr     rbt_maprun
        sta     rbt_d018        ; text-mode shadow (rbt_scrmode restores it)
        rts

; ----------------------------------------------------------------------------
; rbt_tm_setmap - rbt_hl = map data (defb w,h; cells)
; ----------------------------------------------------------------------------
rbt_tm_setmap:
        ldy     #0
        lda     (rbt_hl),y
        sta     rbt_tm_mw
        iny
        lda     (rbt_hl),y
        sta     rbt_tm_mh
        clc
        lda     rbt_hl
        adc     #2
        sta     rbt_tm_cells
        lda     rbt_hl+1
        adc     #0
        sta     rbt_tm_cells+1
        lda     rbt_hl
        sta     rbt_tm_map
        lda     rbt_hl+1
        sta     rbt_tm_map+1
        ; clamp camera into the map
        jsr     rbt_tm_camclamp
        rts

; ----------------------------------------------------------------------------
; rbt_tm_view - rbt_b=x, rbt_c=y, rbt_d=w, rbt_e=h (screen cells, clamped
; to the 40x25 screen)
; ----------------------------------------------------------------------------
rbt_tm_view:
        lda     rbt_b
        cmp     #40
        bcc     @vxok
        lda     #0
@vxok:  sta     rbt_tm_vx
        lda     rbt_c
        cmp     #25
        bcc     @vyok
        lda     #0
@vyok:  sta     rbt_tm_vy
        ; vw = min(d, 40-vx); clamp 1..40
        lda     #40
        sec
        sbc     rbt_tm_vx
        sta     rbt_t0          ; max w
        lda     rbt_d
        cmp     rbt_t0
        bcc     @wok
        lda     rbt_t0
@wok:   beq     @w1
        cmp     #1
        bcs     @ws
@w1:    lda     #1
@ws:    sta     rbt_tm_vw
        lda     #25
        sec
        sbc     rbt_tm_vy
        sta     rbt_t0
        lda     rbt_e
        cmp     rbt_t0
        bcc     @hok
        lda     rbt_t0
@hok:   beq     @h1
        cmp     #1
        bcs     @hs
@h1:    lda     #1
@hs:    sta     rbt_tm_vh
        ; raster window for the scroll's beam-safe shift (row r of the
        ; text screen starts at line 50+r*8)
        lda     rbt_tm_vy
        asl
        asl
        asl
        clc
        adc     #50
        sta     rbt_tm_vbt
        lda     rbt_tm_vh
        asl
        asl
        asl
        clc
        adc     rbt_tm_vbt
        sta     rbt_tm_vbb
        rts

; ----------------------------------------------------------------------------
; rbt_tm_camera - rbt_b=cx, rbt_c=cy (map cells); clamped so the view
; stays inside the map.
; ----------------------------------------------------------------------------
rbt_tm_camera:
        lda     rbt_b
        sta     rbt_tm_camx
        lda     rbt_c
        sta     rbt_tm_camy
rbt_tm_camclamp:
        ; camx <= mw-vw (or 0 when the map is narrower than the view)
        sec
        lda     rbt_tm_mw
        sbc     rbt_tm_vw
        bcs     @mx
        lda     #0
@mx:    cmp     rbt_tm_camx
        bcs     @cxok
        sta     rbt_tm_camx
@cxok:  sec
        lda     rbt_tm_mh
        sbc     rbt_tm_vh
        bcs     @my
        lda     #0
@my:    cmp     rbt_tm_camy
        bcs     @cyok
        sta     rbt_tm_camy
@cyok:  rts

; ----------------------------------------------------------------------------
; rbt_tm_blit - draw tile A at screen cell rbt_b=x, rbt_c=y.
; ----------------------------------------------------------------------------
rbt_tm_blit:
        sta     rbt_t0          ; tile index
        ; rbt_ptr = $0400 + y*40 + x   (y*40 = y*32 + y*8)
        lda     rbt_c
        sta     rbt_t2
        lda     #0
        sta     rbt_t2+1
        asl     rbt_t2
        rol     rbt_t2+1
        asl     rbt_t2
        rol     rbt_t2+1
        asl     rbt_t2
        rol     rbt_t2+1        ; t2 = y*8
        lda     rbt_t2
        sta     rbt_ptr
        lda     rbt_t2+1
        sta     rbt_ptr+1
        asl     rbt_ptr
        rol     rbt_ptr+1
        asl     rbt_ptr
        rol     rbt_ptr+1       ; ptr = y*32
        clc
        lda     rbt_ptr
        adc     rbt_t2
        sta     rbt_ptr
        lda     rbt_ptr+1
        adc     rbt_t2+1
        sta     rbt_ptr+1       ; ptr = y*40
        clc
        lda     rbt_ptr
        adc     rbt_b
        sta     rbt_ptr
        lda     rbt_ptr+1
        adc     #>RBT_SCRN
        sta     rbt_ptr+1       ; ptr = screen cell addr
        ; screen code
        ldy     #0
        lda     rbt_t0
        cmp     rbt_tm_n
        bcc     @valid
        lda     #32             ; out-of-range tile -> space
        bne     @wr
@valid: clc
        adc     #RBT_TM_CODEBASE
@wr:    sta     (rbt_ptr),y
        ; colour cell = ptr + RBT_CDELTA
        lda     rbt_ptr
        sta     rbt_t2
        lda     rbt_ptr+1
        clc
        adc     #>RBT_CDELTA
        sta     rbt_t2+1
        lda     rbt_t0
        cmp     rbt_tm_n
        bcc     @cok
        lda     rbt_attr        ; invalid tile: current ink
        bne     @cw
@cok:   ; colour = tattr[tile] & $0f
        clc
        lda     rbt_tm_tattr
        adc     rbt_t0
        sta     rbt_bc
        lda     rbt_tm_tattr+1
        adc     #0
        sta     rbt_bc+1
        lda     (rbt_bc),y      ; y is still 0
@cw:    and     #$0f
        sta     (rbt_t2),y
        rts

; ----------------------------------------------------------------------------
; rbt_tm_draw - draw the whole view window from the map
; ----------------------------------------------------------------------------
rbt_tm_draw:
        lda     #0
        sta     rbt_tm_r
@rloop: lda     #0
        sta     rbt_tm_c
@cloop: ; map coords (camx+c, camy+r)
        clc
        lda     rbt_tm_camx
        adc     rbt_tm_c
        sta     rbt_b
        clc
        lda     rbt_tm_camy
        adc     rbt_tm_r
        sta     rbt_c
        jsr     rbt_tm_mapat
        sta     rbt_tm_tid
        ; screen coords (vx+c, vy+r)
        clc
        lda     rbt_tm_vx
        adc     rbt_tm_c
        sta     rbt_b
        clc
        lda     rbt_tm_vy
        adc     rbt_tm_r
        sta     rbt_c
        lda     rbt_tm_tid
        jsr     rbt_tm_blit
        inc     rbt_tm_c
        lda     rbt_tm_c
        cmp     rbt_tm_vw
        bcc     @cloop
        inc     rbt_tm_r
        lda     rbt_tm_r
        cmp     rbt_tm_vh
        bcc     @rloop
        rts

; ----------------------------------------------------------------------------
; rbt_tm_redraw - rbt_b=x, rbt_c=y, rbt_d=w, rbt_e=h: repair a screen-cell
; rect (clipped to the view) from the map.
; ----------------------------------------------------------------------------
rbt_tm_redraw:
        ; clip rect to the view: x0..x1, y0..y1 in rbt_tm_r0-style temps
        lda     rbt_b
        sta     rbt_tm_tid      ; x0 (absolute screen col)
        lda     rbt_c
        sta     rbt_tm_cnt      ; y0
        clc
        lda     rbt_b
        adc     rbt_d
        sta     rbt_tm_dir      ; x1 (exclusive)
        clc
        lda     rbt_c
        adc     rbt_e
        sta     rbt_tm_steps    ; y1 (exclusive)
        ; clip x0,y0 up to view origin; x1,y1 down to view end
        lda     rbt_tm_tid
        cmp     rbt_tm_vx
        bcs     @x0ok
        lda     rbt_tm_vx
        sta     rbt_tm_tid
@x0ok:  lda     rbt_tm_cnt
        cmp     rbt_tm_vy
        bcs     @y0ok
        lda     rbt_tm_vy
        sta     rbt_tm_cnt
@y0ok:  clc
        lda     rbt_tm_vx
        adc     rbt_tm_vw
        cmp     rbt_tm_dir
        bcs     @x1ok
        sta     rbt_tm_dir
@x1ok:  clc
        lda     rbt_tm_vy
        adc     rbt_tm_vh
        cmp     rbt_tm_steps
        bcs     @y1ok
        sta     rbt_tm_steps
@y1ok:  ; r = y0..y1-1
        lda     rbt_tm_cnt
        sta     rbt_tm_r
@rl:    lda     rbt_tm_r
        cmp     rbt_tm_steps
        bcs     @rdone
        lda     rbt_tm_tid
        sta     rbt_tm_c
@cl:    lda     rbt_tm_c
        cmp     rbt_tm_dir
        bcs     @cdone
        ; map coords = camx + (c - vx), camy + (r - vy)
        sec
        lda     rbt_tm_c
        sbc     rbt_tm_vx
        clc
        adc     rbt_tm_camx
        sta     rbt_b
        sec
        lda     rbt_tm_r
        sbc     rbt_tm_vy
        clc
        adc     rbt_tm_camy
        sta     rbt_c
        jsr     rbt_tm_mapat
        sta     rbt_t0
        lda     rbt_tm_c
        sta     rbt_b
        lda     rbt_tm_r
        sta     rbt_c
        lda     rbt_t0
        jsr     rbt_tm_blit
        inc     rbt_tm_c
        jmp     @cl
@cdone: inc     rbt_tm_r
        jmp     @rl
@rdone: rts

; ----------------------------------------------------------------------------
; rbt_tm_scroll - A = dir (0=left,1=right,2=up,3=down), rbt_b = steps.
; Moves the camera one cell per step, shifts the view's screen+colour
; bytes and draws only the newly exposed edge.
; ----------------------------------------------------------------------------
rbt_tm_scroll:
        and     #3
        sta     rbt_tm_dir
        lda     rbt_b
        beq     @done
        sta     rbt_tm_steps
@step:  jsr     _tm_shift       ; move camera + shift + draw edge
        dec     rbt_tm_steps
        bne     @step
@done:  rts

; _tm_shift: one scroll step for rbt_tm_dir.
_tm_shift:
        jsr     _tm_beam        ; shift inside the beam-safe window
        lda     rbt_tm_dir
        cmp     #0
        bne     @n0
        jmp     _left
@n0:    cmp     #1
        bne     @n1
        jmp     _right
@n1:    cmp     #2
        bne     @n2
        jmp     _up
@n2:    jmp     _down

; --- helpers ---------------------------------------------------------------

; _rowbase: rbt_c = absolute screen row -> rbt_ptr = $0400+row*40+vx,
; rbt_t2 = same in colour RAM ($D800+...).
_rowbase:
        lda     rbt_c
        sta     rbt_t2
        lda     #0
        sta     rbt_t2+1
        asl     rbt_t2
        rol     rbt_t2+1
        asl     rbt_t2
        rol     rbt_t2+1
        asl     rbt_t2
        rol     rbt_t2+1        ; t2 = row*8
        lda     rbt_t2
        sta     rbt_ptr
        lda     rbt_t2+1
        sta     rbt_ptr+1
        asl     rbt_ptr
        rol     rbt_ptr+1
        asl     rbt_ptr
        rol     rbt_ptr+1       ; ptr = row*32
        clc
        lda     rbt_ptr
        adc     rbt_t2
        sta     rbt_ptr
        lda     rbt_ptr+1
        adc     rbt_t2+1
        sta     rbt_ptr+1       ; ptr = row*40
        clc
        lda     rbt_ptr
        adc     rbt_tm_vx
        sta     rbt_ptr
        lda     rbt_ptr+1
        adc     #>RBT_SCRN
        sta     rbt_ptr+1       ; ptr = screen addr of view cell (vx,row)
        lda     rbt_ptr
        sta     rbt_t2
        lda     rbt_ptr+1
        clc
        adc     #>RBT_CDELTA
        sta     rbt_t2+1        ; t2 = colour addr
        rts

; _tm_beam - wait until the raster is outside the view band (below its
; bottom edge or above its top) so the shift can't tear mid-row. Striker-
; style callers scroll right after HALT, so this almost never waits; a
; mid-frame SCROLL stalls to the border instead of shearing.
_tm_beam:
        .if RBT_C128
        jsr     rbt_mapio       ; $d011/$d012 live in the I/O window
        .endif
@w:     lda     $d011
        bmi     @go             ; raster > 255: below every legal view
        lda     $d012
        cmp     rbt_tm_vbb
        bcs     @go             ; below the view bottom
        cmp     rbt_tm_vbt
        bcc     @go             ; above the view top
        jmp     @w
@go:
        .if RBT_C128
        jmp     rbt_maprun
        .else
        rts
        .endif

; --- fast view shift --------------------------------------------------------
; The old (zp),y shift cost ~38c per screen+colour cell (~22K cycles for a
; 32x18 view — a whole frame). These blocks use unrolled absolute-indexed
; copies at ~16c per cell: X carries the row's byte offset, and since a
; 1K span needs four 256-byte pages there's one block per page, dispatched
; through the _shX_tab tables. Content-right and row-copy blocks execute
; descending and are entered mid-block at (width gap)*12; content-left must
; run ascending, so _right patches an exit RTS at (vw-1)*12 before the row
; loop and restores it after.

.macro  shlblk  g
        .repeat 31, I
        lda     RBT_SCRN+g*$100+I+1,x
        sta     RBT_SCRN+g*$100+I,x
        lda     RBT_SCRN+RBT_CDELTA+g*$100+I+1,x
        sta     RBT_SCRN+RBT_CDELTA+g*$100+I,x
        .endrepeat
        rts
.endmacro

.macro  shrblk  g
        .repeat 31, I
        lda     RBT_SCRN+g*$100+30-I,x
        sta     RBT_SCRN+g*$100+31-I,x
        lda     RBT_SCRN+RBT_CDELTA+g*$100+30-I,x
        sta     RBT_SCRN+RBT_CDELTA+g*$100+31-I,x
        .endrepeat
        rts
.endmacro

_shl_b0:        shlblk  0
_shl_b1:        shlblk  1
_shl_b2:        shlblk  2
_shl_b3:        shlblk  3
_shr_b0:        shrblk  0
_shr_b1:        shrblk  1
_shr_b2:        shrblk  2
_shr_b3:        shrblk  3

_shl_tab:       .word _shl_b0, _shl_b1, _shl_b2, _shl_b3
_shr_tab:       .word _shr_b0, _shr_b1, _shr_b2, _shr_b3

; _offjmp - rbt_t2 += A*12 then jmp (rbt_t2). X preserved.
_offjmp:
        sta     rbt_t0
        asl
        asl                     ; t*4 (t<=40 -> <256)
        sta     rbt_t1
        lda     rbt_t0
        asl
        asl
        asl                     ; t*8 lo
        sta     rbt_bc
        lda     #0
        rol                     ; t*8 hi
        tay
        clc
        lda     rbt_bc
        adc     rbt_t1          ; t*12 lo
        bcc     @n1
        iny
@n1:    clc
        adc     rbt_t2
        sta     rbt_t2
        tya
        adc     rbt_t2+1
        sta     rbt_t2+1
        jmp     (rbt_t2)

; _shlpatch - plant an exit RTS at (vw-1)*12 in every shl block. A = 0
; restores the saved bytes instead.
_shlpatch:
        sta     rbt_t1          ; 0 = restore
        lda     rbt_tm_vw
        sec
        sbc     #1              ; t = vw-1 (<=39)
        sta     rbt_t0
        asl
        asl                     ; t*4
        sta     rbt_bc
        lda     rbt_t0
        asl
        asl
        asl                     ; t*8 lo
        sta     rbt_t0
        lda     #0
        rol                     ; t*8 hi
        sta     rbt_t2+1
        clc
        lda     rbt_t0
        adc     rbt_bc
        sta     rbt_t2          ; offset lo
        lda     rbt_t2+1
        adc     #0
        sta     rbt_t2+1        ; offset hi
        ldx     #0
@pl:    txa
        asl
        tay
        clc
        lda     _shl_tab,y
        adc     rbt_t2
        sta     rbt_ptr
        lda     _shl_tab+1,y
        adc     rbt_t2+1
        sta     rbt_ptr+1
        ldy     #0
        lda     rbt_t1
        beq     @rs
        lda     (rbt_ptr),y
        sta     rbt_tm_sv,x
        lda     #$60            ; rts
        bne     @st
@rs:    lda     rbt_tm_sv,x
@st:    sta     (rbt_ptr),y
        inx
        cpx     #4
        bcc     @pl
        rts

; _shrow - shift one view row horizontally. rbt_tm_cnt: 0 = content right
; (descending mid-block entry), 1 = content left (top entry, exit-patched).
; rbt_ptr = screen addr of the row's first view cell.
_shrow:
        ldx     rbt_ptr         ; row byte offset lo (SCRN is page-aligned)
        lda     rbt_ptr+1
        sec
        sbc     #>RBT_SCRN      ; page group 0-3
        asl
        tay
        lda     rbt_tm_cnt
        bne     @lft
        lda     _shr_tab,y
        sta     rbt_t2
        lda     _shr_tab+1,y
        sta     rbt_t2+1
        lda     #32
        sec
        sbc     rbt_tm_vw
        jmp     _offjmp
@lft:   lda     _shl_tab,y
        sta     rbt_t2
        lda     _shl_tab+1,y
        sta     rbt_t2+1
        lda     #0
        jmp     _offjmp

; _vrow - copy one view row's bytes vertically (dual-pointer zp loop —
; the hot path is horizontal scrolling; this stays simple). rbt_ptr/t2 =
; src row, rbt_bc/rbt_hl = dst row.
_vrow:
        ldy     #0
@l:     lda     (rbt_ptr),y
        sta     (rbt_bc),y
        lda     (rbt_t2),y
        sta     (rbt_hl),y
        iny
        cpy     rbt_tm_vw
        bcc     @l
        rts

; --- scroll directions -----------------------------------------------------

_left:  ; camera left (content shifts right), new column = left edge
        lda     rbt_tm_camx
        beq     @done           ; at map edge: nothing moves
        dec     rbt_tm_camx
        ; shift all view rows right
        lda     #0
        sta     rbt_tm_r
@rows:  lda     rbt_tm_r
        cmp     rbt_tm_vh
        bcs     @edge
        clc
        adc     rbt_tm_vy
        sta     rbt_c
        lda     #0
        sta     rbt_tm_cnt      ; 0 = shift right
        jsr     _rowbase
        jsr     _shrow
        inc     rbt_tm_r
        bne     @rows
@edge:  ; draw new left column
        lda     #0
        sta     rbt_tm_r
@ecl:   lda     rbt_tm_r
        cmp     rbt_tm_vh
        bcs     @done
        lda     rbt_tm_camx
        sta     rbt_b
        clc
        lda     rbt_tm_camy
        adc     rbt_tm_r
        sta     rbt_c
        jsr     rbt_tm_mapat
        sta     rbt_t0
        lda     rbt_tm_vx
        sta     rbt_b
        clc
        lda     rbt_tm_vy
        adc     rbt_tm_r
        sta     rbt_c
        lda     rbt_t0
        jsr     rbt_tm_blit
        inc     rbt_tm_r
        bne     @ecl
@done:  rts

_right: ; camera right (content shifts left), new column = right edge
        sec
        lda     rbt_tm_mw
        sbc     rbt_tm_vw
        bcs     @lim
        lda     #0
@lim:   cmp     rbt_tm_camx
        beq     @done           ; at map edge: nothing moves
        bcc     @done
        inc     rbt_tm_camx
        lda     #1
        jsr     _shlpatch       ; exit-patched left-shift blocks
        lda     #0
        sta     rbt_tm_r
@rows:  lda     rbt_tm_r
        cmp     rbt_tm_vh
        bcs     @x
        clc
        adc     rbt_tm_vy
        sta     rbt_c
        lda     #1
        sta     rbt_tm_cnt      ; 1 = shift left
        jsr     _rowbase
        jsr     _shrow
        inc     rbt_tm_r
        bne     @rows
@x:     lda     #0
        jsr     _shlpatch       ; restore the patched exit
@edge:  lda     #0
        sta     rbt_tm_r
@ecl:   lda     rbt_tm_r
        cmp     rbt_tm_vh
        bcs     @done
        clc
        lda     rbt_tm_camx
        adc     rbt_tm_vw
        sec
        sbc     #1
        sta     rbt_b
        clc
        lda     rbt_tm_camy
        adc     rbt_tm_r
        sta     rbt_c
        jsr     rbt_tm_mapat
        sta     rbt_t0
        clc
        lda     rbt_tm_vx
        adc     rbt_tm_vw
        sec
        sbc     #1
        sta     rbt_b
        clc
        lda     rbt_tm_vy
        adc     rbt_tm_r
        sta     rbt_c
        lda     rbt_t0
        jsr     rbt_tm_blit
        inc     rbt_tm_r
        bne     @ecl
@done:  rts

_up:    ; camera up (content shifts down), new row = top edge
        lda     rbt_tm_camy
        bne     @m
        rts                     ; at map edge: nothing moves
@m:     dec     rbt_tm_camy
        ; shift rows down: r = vh-2 downto 0 -> copy row r to r+1
        lda     rbt_tm_vh
        cmp     #2
        bcc     @edge
        sec
        sbc     #2
        sta     rbt_tm_r
@rows:  lda     rbt_tm_r
        bmi     @edge
        ; src row = vy + r, dst = src+1: copy vw cells screen+colour
        clc
        adc     rbt_tm_vy
        sta     rbt_c
        jsr     _rowbase        ; ptr/t2 = src row view start
        clc                     ; dst = src+40 (content moves down)
        lda     rbt_ptr
        adc     #40
        sta     rbt_bc
        lda     rbt_ptr+1
        adc     #0
        sta     rbt_bc+1
        clc
        lda     rbt_t2
        adc     #40
        sta     rbt_hl
        lda     rbt_t2+1
        adc     #0
        sta     rbt_hl+1
        jsr     _vrow
        dec     rbt_tm_r
        jmp     @rows
@edge:  ; draw new top row
        lda     #0
        sta     rbt_tm_c
@ecl:   lda     rbt_tm_c
        cmp     rbt_tm_vw
        bcs     @done
        clc
        lda     rbt_tm_camx
        adc     rbt_tm_c
        sta     rbt_b
        lda     rbt_tm_camy
        sta     rbt_c
        jsr     rbt_tm_mapat
        sta     rbt_t0
        clc
        lda     rbt_tm_vx
        adc     rbt_tm_c
        sta     rbt_b
        lda     rbt_tm_vy
        sta     rbt_c
        lda     rbt_t0
        jsr     rbt_tm_blit
        inc     rbt_tm_c
        bne     @ecl
@done:  rts

_down:  ; camera down (content shifts up), new row = bottom edge
        sec
        lda     rbt_tm_mh
        sbc     rbt_tm_vh
        bcs     @lim
        lda     #0
@lim:   cmp     rbt_tm_camy
        beq     @xit            ; at map edge: nothing moves
        bcc     @xit
        jmp     @go
@xit:   rts
@go:    inc     rbt_tm_camy
        lda     rbt_tm_vh
        cmp     #2
        bcc     @edge
        ; shift rows up: r = 1..vh-1 -> copy row r to r-1
        lda     #1
        sta     rbt_tm_r
@rows:  lda     rbt_tm_r
        cmp     rbt_tm_vh
        bcs     @edge
        clc
        adc     rbt_tm_vy
        sta     rbt_c
        jsr     _rowbase        ; ptr/t2 = src row view start
        sec                     ; dst = src-40 (content moves up)
        lda     rbt_ptr
        sbc     #40
        sta     rbt_bc
        lda     rbt_ptr+1
        sbc     #0
        sta     rbt_bc+1
        sec
        lda     rbt_t2
        sbc     #40
        sta     rbt_hl
        lda     rbt_t2+1
        sbc     #0
        sta     rbt_hl+1
        jsr     _vrow
        inc     rbt_tm_r
        bne     @rows
@edge:  lda     #0
        sta     rbt_tm_c
@ecl:   lda     rbt_tm_c
        cmp     rbt_tm_vw
        bcs     @done
        clc
        lda     rbt_tm_camx
        adc     rbt_tm_c
        sta     rbt_b
        clc
        lda     rbt_tm_camy
        adc     rbt_tm_vh
        sec
        sbc     #1
        sta     rbt_c
        jsr     rbt_tm_mapat
        sta     rbt_t0
        clc
        lda     rbt_tm_vx
        adc     rbt_tm_c
        sta     rbt_b
        clc
        lda     rbt_tm_vy
        adc     rbt_tm_vh
        sec
        sbc     #1
        sta     rbt_c
        lda     rbt_t0
        jsr     rbt_tm_blit
        inc     rbt_tm_c
        bne     @ecl
@done:  rts

; ----------------------------------------------------------------------------
; rbt_tileat - rbt_b=tx, rbt_c=ty -> A = tile id (255 = out of bounds)
; ----------------------------------------------------------------------------
rbt_tileat:
        lda     rbt_b
        cmp     rbt_tm_mw
        bcs     @oob
        lda     rbt_c
        cmp     rbt_tm_mh
        bcs     @oob
        jmp     rbt_tm_mapat
@oob:   lda     #255
        rts

; ----------------------------------------------------------------------------
; rbt_tileatset - rbt_b=tx, rbt_c=ty, rbt_d=id: write the map cell and
; repaint it when the cell is in view. There's no backdrop compositor on
; this platform (hardware sprites never touch screen RAM) — on ZX/CPC a
; map write under a sprite is picked up by the next SPRITES UPDATE, so
; the blit here is the only repaint a map change gets on C64.
; ----------------------------------------------------------------------------
rbt_tileatset:
        lda     rbt_b
        cmp     rbt_tm_mw
        bcs     @out
        lda     rbt_c
        cmp     rbt_tm_mh
        bcs     @out
        jsr     rbt_tm_mapat    ; rbt_ptr = cell addr (result A unused)
        lda     rbt_d
        ldy     #0
        sta     (rbt_ptr),y
        ; screen cell = view origin + (tx,ty) - camera
        sec
        lda     rbt_b
        sbc     rbt_tm_camx
        bmi     @out
        cmp     rbt_tm_vw
        bcs     @out
        clc
        adc     rbt_tm_vx
        sta     rbt_t0          ; screen x
        sec
        lda     rbt_c
        sbc     rbt_tm_camy
        bmi     @out
        cmp     rbt_tm_vh
        bcs     @out
        clc
        adc     rbt_tm_vy
        sta     rbt_c
        lda     rbt_t0
        sta     rbt_b
        lda     rbt_d
        jmp     rbt_tm_blit     ; draws screen + colour cell, rts to caller
@out:   rts

; ----------------------------------------------------------------------------
; rbt_tileflags - A = tile id -> A = flags byte (0 if out of range)
; ----------------------------------------------------------------------------
rbt_tileflags:
        cmp     rbt_tm_n
        bcc     @in
        lda     #0
        rts
@in:    clc
        adc     rbt_tm_tflags
        sta     rbt_ptr
        lda     rbt_tm_tflags+1
        adc     #0
        sta     rbt_ptr+1
        ldy     #0
        lda     (rbt_ptr),y
        rts
''',
    'tmdata': r'''
; ============================================================================
; rbt_tmdata - tilemap state + map query (Commodore 64, ca65)
; Mirrors runtime/zx/rbt_tmdata.asm minus the bank-page vars — a stock C64
; has no pageable RAM (rbt_tm_tbank/rbt_tm_mbank exist only because the
; emitter stores to them).
; ============================================================================

        .code

rbt_tm_tiles:   .res 2          ; tileset base
rbt_tm_bmp:     .res 2          ; bitmaps (tiles+1)
rbt_tm_tattr:   .res 2          ; attr table (tiles+1+8n)
rbt_tm_tflags:  .res 2          ; flag table (tiles+1+9n)
rbt_tm_n:       .res 1          ; tile count (clamped to 128)
rbt_tm_tbank:   .res 1          ; written by codegen ($ff) — unused
rbt_tm_map:     .res 2          ; map base
rbt_tm_mbank:   .res 1          ; written by codegen ($ff) — unused
rbt_tm_cells:   .res 2          ; map cells (map+2)
rbt_tm_mw:      .res 1          ; map width
rbt_tm_mh:      .res 1          ; map height
rbt_tm_vx:      .res 1          ; view: screen cells
rbt_tm_vy:      .res 1
rbt_tm_vw:      .byte 40
rbt_tm_vh:      .byte 25
rbt_tm_vbt:     .byte 50        ; raster line of the view's top edge
rbt_tm_vbb:     .byte 250       ; raster line of the view's bottom edge
rbt_tm_sv:      .res 4          ; saved bytes for the fast-shift exit patch
rbt_tm_camx:    .res 1          ; camera: map cell at view top-left
rbt_tm_camy:    .res 1
rbt_tm_r:       .res 1          ; row loop temp
rbt_tm_c:       .res 1          ; col loop temp
rbt_tm_dir:     .res 1          ; scroll dir
rbt_tm_steps:   .res 1          ; scroll steps left
rbt_tm_cnt:     .res 1          ; scratch counter
rbt_tm_tid:     .res 1          ; tile-id temp
rbt_ct_c0:      .res 1          ; COLLIDETILE cell-range scratch
rbt_ct_c1:      .res 1
rbt_ct_r0:      .res 1
rbt_ct_r1:      .res 1
rbt_ct_r:       .res 1
rbt_ct_c:       .res 1

; ----------------------------------------------------------------------------
; rbt_tm_mapat - rbt_b=mx, rbt_c=my -> A = tile id (0 when out of bounds).
; ----------------------------------------------------------------------------
rbt_tm_mapat:
        lda     rbt_b
        cmp     rbt_tm_mw
        bcs     @oob
        lda     rbt_c
        cmp     rbt_tm_mh
        bcs     @oob
        ; rbt_ptr = cells + my*mw + mx
        lda     rbt_tm_cells
        sta     rbt_ptr
        lda     rbt_tm_cells+1
        sta     rbt_ptr+1
        ldx     rbt_c
        beq     @addx
@rloop: clc
        lda     rbt_ptr
        adc     rbt_tm_mw
        sta     rbt_ptr
        lda     rbt_ptr+1
        adc     #0
        sta     rbt_ptr+1
        dex
        bne     @rloop
@addx:  clc
        lda     rbt_ptr
        adc     rbt_b
        sta     rbt_ptr
        lda     rbt_ptr+1
        adc     #0
        sta     rbt_ptr+1
        ldy     #0
        lda     (rbt_ptr),y
        rts
@oob:   lda     #0
        rts
''',
  },
};
